def test_owner_retirement_tombstone_has_exact_closed_canonical_schema(
    tmp_path: Path,
) -> None:
    runtime_root = tmp_path / "runtime"
    target = runtime_root / "CustomConfig" / ("old--sha256-" + "a" * 64)
    target.mkdir(parents=True)
    leaf_b = target / "b-config.json"
    leaf_b.write_bytes(b'{"old":"b"}\n')
    leaf_a = target / "a-config.json"
    leaf_a.write_bytes(b'{"old":"a"}\n')
    inventory = runtime_installer._collect_owner_retirement_cleanup_entries(
        target
    )
    assert inventory == (
        {
            "relative_path": "b-config.json",
            "entry_kind": "file",
            "identity": path_identity(leaf_b),
            "expected_parent_identity": path_identity(target),
            "size": len(leaf_b.read_bytes()),
            "sha256": "sha256:"
            + hashlib.sha256(leaf_b.read_bytes()).hexdigest(),
        },
        {
            "relative_path": "a-config.json",
            "entry_kind": "file",
            "identity": path_identity(leaf_a),
            "expected_parent_identity": path_identity(target),
            "size": len(leaf_a.read_bytes()),
            "sha256": "sha256:"
            + hashlib.sha256(leaf_a.read_bytes()).hexdigest(),
        },
    )
    retired_owner_id = "a" * 32
    successor_id = "b" * 32
    initial_owner_path = runtime_transaction_journal_path(
        runtime_root, retired_owner_id
    )
    successor_owner_path = runtime_transaction_journal_path(
        runtime_root, successor_id
    )
    def build_tombstone(
        entries: tuple[Mapping[str, object], ...],
    ) -> bytes:
        return runtime_installer._build_owner_retirement_tombstone_bytes(
            state="PREPARED",
            retired_owner_transaction_id=retired_owner_id,
            initial_owner_journal_path=initial_owner_path,
            initial_owner_journal_identity=(1, 2, 3),
            initial_owner_journal_sha256="sha256:" + "1" * 64,
            retired_target_path=target,
            retired_target_parent_identity=path_identity(target.parent),
            retired_target_identity=path_identity(target),
            retired_target_tree_sha256="sha256:" + "2" * 64,
            successor_transaction_id=successor_id,
            successor_package_root_sha256="sha256:" + "3" * 64,
            successor_owner_journal_path=successor_owner_path,
            successor_owner_journal_identity=(4, 5, 6),
            successor_owner_journal_sha256="sha256:" + "4" * 64,
            cleanup_entries=entries,
            completed_cleanup_cursor=None,
            completed_owner_journal_identity=None,
            completed_owner_journal_sha256=None,
        )

    tombstone = build_tombstone(inventory)
    with pytest.raises(
        ValueError,
        match="runtime_owner_retirement_tombstone_entry_order_invalid",
    ):
        build_tombstone(tuple(reversed(inventory)))
    decoded = json.loads(tombstone)
    parsed = runtime_installer._parse_owner_retirement_tombstone_bytes(
        tombstone,
        runtime_root=runtime_root,
    )
    assert set(decoded) == {
        "schema_version",
        "record_kind",
        "state",
        "retired_owner_transaction_id",
        "initial_owner_journal_path",
        "initial_owner_journal_identity",
        "initial_owner_journal_sha256",
        "retired_target_path",
        "retired_target_parent_identity",
        "retired_target_identity",
        "retired_target_tree_sha256",
        "successor_transaction_id",
        "successor_package_root_sha256",
        "successor_owner_journal_path",
        "successor_owner_journal_identity",
        "successor_owner_journal_sha256",
        "cleanup_manifest_sha256",
        "cleanup_entry_count",
        "cleanup_entries",
        "completed_cleanup_cursor",
        "completed_owner_journal_identity",
        "completed_owner_journal_sha256",
        "content_sha256",
    }
    assert decoded["state"] == "PREPARED"
    assert parsed["cleanup_manifest_sha256"] == decoded[
        "cleanup_manifest_sha256"
    ]
    assert decoded["cleanup_entry_count"] == 2
    assert decoded["completed_cleanup_cursor"] is None
    assert decoded["content_sha256"] == "sha256:" + hashlib.sha256(
        runtime_installer._canonical_owner_retirement_json(
            {key: value for key, value in decoded.items() if key != "content_sha256"}
        )
    ).hexdigest()
    assert runtime_installer.RUNTIME_OWNER_RETIREMENT_MAX_ENTRIES == (
        runtime_installer.MAX_RUN_FILES
    )


def test_owner_retirement_prepared_record_carries_complete_identity_inventory(
    tmp_path: Path,
) -> None:
    target = tmp_path / "runtime" / "CustomConfig" / "old"
    target.mkdir(parents=True)
    payload = b"x" * (64 * 1024 + 1)
    entry = target / "large-config.bin"
    entry.write_bytes(payload)

    inventory = runtime_installer._collect_owner_retirement_cleanup_entries(
        target
    )
    assert inventory[0]["relative_path"] == "large-config.bin"
    assert inventory[0]["size"] == len(payload)
    assert inventory[0]["sha256"] == "sha256:" + hashlib.sha256(
        payload
    ).hexdigest()


def test_owner_retirement_initial_preflight_bounds_all_four_future_payloads(
    tmp_path: Path,
) -> None:
    """The first owner cursor is refused only after all future blobs fit."""

    runtime_root = tmp_path / "runtime"
    target = runtime_root / "CustomConfig" / ("Deck--sha256-" + "a" * 64)
    target.mkdir(parents=True)
    (target / "config.json").write_bytes(b'{"owner":true}\n')
    old_id = "a" * 32
    successor_id = "b" * 32
    target_identity = path_identity(target)
    old_journal = _unit_journal(
        phase=RuntimeTransactionPhase.FINALIZED,
        candidate_identity=target_identity,
        target_identity=target_identity,
        owns_target=True,
        transaction_id=old_id,
    )
    inventory = runtime_installer._collect_owner_retirement_cleanup_entries(
        target
    )

    payloads = runtime_installer._owner_retirement_initial_preflight_payloads(
        old_journal=old_journal,
        cleanup_entries=inventory,
        initial_owner_journal_path=runtime_transaction_journal_path(
            runtime_root, old_id
        ),
        initial_owner_journal_identity=(1, 2, 3),
        initial_owner_journal_sha256="sha256:" + "1" * 64,
        retired_target_path=target,
        retired_target_parent_identity=path_identity(target.parent),
        retired_target_identity=target_identity,
        retired_target_tree_sha256=(
            runtime_installer._owner_retirement_tree_sha256(
                target_identity=target_identity,
                entries=inventory,
            )
        ),
        successor_transaction_id=successor_id,
        successor_package_root_sha256="sha256:" + "a" * 64,
        successor_owner_journal_path=runtime_transaction_journal_path(
            runtime_root, successor_id
        ),
        successor_owner_journal_identity=(4, 5, 6),
        successor_owner_journal_sha256="sha256:" + "2" * 64,
    )

    assert set(payloads) == {
        "cursor_zero_v1",
        "final_v1",
        "prepared_tombstone",
        "completed_tombstone",
    }
    assert all(
        len(payload) <= runtime_installer.MAX_RUNTIME_TRANSACTION_BYTES
        for name, payload in payloads.items()
        if name.endswith("_v1")
    )
    assert all(
        len(payload) <= runtime_installer.RUNTIME_OWNER_RETIREMENT_MAX_BYTES
        for name, payload in payloads.items()
        if name.endswith("_tombstone")
    )
    assert runtime_installer.parse_runtime_transaction_journal_bytes(
        payloads["cursor_zero_v1"], expected_transaction_id=old_id
    ).cleanup_cursor == 0
    assert runtime_installer.parse_runtime_transaction_journal_bytes(
        payloads["final_v1"], expected_transaction_id=old_id
    ).cleanup_cursor == len(inventory)
    assert runtime_installer._parse_owner_retirement_tombstone_bytes(
        payloads["prepared_tombstone"], runtime_root=runtime_root
    )["state"] == "PREPARED"
    assert runtime_installer._parse_owner_retirement_tombstone_bytes(
        payloads["completed_tombstone"], runtime_root=runtime_root
    )["state"] == "COMPLETED"


def test_owner_retirement_prepared_and_completed_use_external_file_action(
    tmp_path: Path,
) -> None:
    runtime_root, cursor, _target, tombstone_path, _old_path, actions = (
        _owner_retirement_runtime_trace(tmp_path, count=1)
    )

    completed = runtime_installer._parse_owner_retirement_tombstone_bytes(
        tombstone_path.read_bytes(), runtime_root=runtime_root
    )
    assert completed["state"] == "COMPLETED"
    assert actions.count("materialize_file_action_staging") == 4
    assert cursor.apply_recovery["expected_action"] == "observe_committed"


@pytest.mark.parametrize("mutation", ("unknown", "digest", "substitution"))
def test_owner_retirement_rejects_unknown_fields_bounds_self_digest_or_substitution(
    tmp_path: Path,
    mutation: str,
) -> None:
    runtime_root = tmp_path / "runtime"
    target = runtime_root / "CustomConfig" / ("old--sha256-" + "a" * 64)
    target.mkdir(parents=True)
    leaf = target / "config.json"
    leaf.write_bytes(b"{}\n")
    raw = runtime_installer._build_owner_retirement_tombstone_bytes(
        state="PREPARED",
        retired_owner_transaction_id="a" * 32,
        initial_owner_journal_path=runtime_transaction_journal_path(
            runtime_root, "a" * 32
        ),
        initial_owner_journal_identity=(1, 2, 3),
        initial_owner_journal_sha256="sha256:" + "1" * 64,
        retired_target_path=target,
        retired_target_parent_identity=path_identity(target.parent),
        retired_target_identity=path_identity(target),
        retired_target_tree_sha256="sha256:" + "2" * 64,
        successor_transaction_id="b" * 32,
        successor_package_root_sha256="sha256:" + "3" * 64,
        successor_owner_journal_path=runtime_transaction_journal_path(
            runtime_root, "b" * 32
        ),
        successor_owner_journal_identity=(4, 5, 6),
        successor_owner_journal_sha256="sha256:" + "4" * 64,
        cleanup_entries=runtime_installer._collect_owner_retirement_cleanup_entries(
            target
        ),
        completed_cleanup_cursor=None,
        completed_owner_journal_identity=None,
        completed_owner_journal_sha256=None,
    )
    value = json.loads(raw)
    if mutation == "unknown":
        value["unexpected"] = True
    elif mutation == "digest":
        value["content_sha256"] = "sha256:" + "f" * 64
    else:
        value["retired_target_identity"] = [9, 9, 0o040755]
    mutated = runtime_installer._canonical_owner_retirement_json(value)

    with pytest.raises(ValueError, match="owner_retirement_tombstone_invalid"):
        runtime_installer._parse_owner_retirement_tombstone_bytes(
            mutated, runtime_root=runtime_root
        )


def _owner_retirement_runtime_trace(
    base: Path,
    *,
    count: int,
    stop_before_action: str | None = None,
    session_root_out: list[Path] | None = None,
    crash_before_cas_checkpoint: tuple[str, str, int] | None = None,
    crash_replays_out: list[tuple[str, str, int]] | None = None,
) -> tuple[Path, object, Path, Path, Path, list[str]]:
    """Build a real v1 owner/tombstone trace, then drive Session CAS steps."""

    import hsconfig.live_start_session as session
    from tests.test_live_start_session import (
        _apply_recovery_cursor_for_action,
        _lease,
        _owner_retirement_fixture,
        _seal_literal_document,
    )

    runtime_root = (base / "runtime").absolute()
    target = runtime_root / "CustomConfig" / ("Deck--sha256-" + "a" * 64)
    target.mkdir(parents=True)
    for index in range(count):
        (target / f"entry-{index}.txt").write_bytes(
            f"owner-entry-{index}\n".encode("ascii")
        )
    old_id = "a" * 32
    successor_id = "b" * 32
    old_path = runtime_transaction_journal_path(runtime_root, old_id)
    successor_path = runtime_transaction_journal_path(runtime_root, successor_id)
    old_path.parent.mkdir(parents=True, exist_ok=True)
    target_identity = path_identity(target)
    old_journal = _unit_journal(
        phase=RuntimeTransactionPhase.FINALIZED,
        candidate_identity=target_identity,
        target_identity=target_identity,
        owns_target=True,
        transaction_id=old_id,
    )
    successor_journal = _unit_journal(
        phase=RuntimeTransactionPhase.FINALIZED,
        candidate_identity=target_identity,
        target_identity=target_identity,
        owns_target=True,
        transaction_id=successor_id,
    )
    write_runtime_transaction_journal(old_path, old_journal)
    write_runtime_transaction_journal(successor_path, successor_journal)
    old_raw = old_path.read_bytes()
    successor_raw = successor_path.read_bytes()
    inventory = runtime_installer._collect_owner_retirement_cleanup_entries(
        target
    )
    tree_sha256 = runtime_installer._owner_retirement_tree_sha256(
        target_identity=target_identity,
        entries=inventory,
    )
    tombstone_path = (
        runtime_root / ".hsconfig" / "owner-retirements" / f"{old_id}.json"
    )
    tombstone_path.parent.mkdir(parents=True, exist_ok=True)
    prepared_raw = runtime_installer._build_owner_retirement_tombstone_bytes(
        state="PREPARED",
        retired_owner_transaction_id=old_id,
        initial_owner_journal_path=old_path,
        initial_owner_journal_identity=path_identity(old_path),
        initial_owner_journal_sha256="sha256:" + hashlib.sha256(old_raw).hexdigest(),
        retired_target_path=target,
        retired_target_parent_identity=path_identity(target.parent),
        retired_target_identity=target_identity,
        retired_target_tree_sha256=tree_sha256,
        successor_transaction_id=successor_id,
        successor_package_root_sha256="sha256:" + "a" * 64,
        successor_owner_journal_path=successor_path,
        successor_owner_journal_identity=path_identity(successor_path),
        successor_owner_journal_sha256=(
            "sha256:" + hashlib.sha256(successor_raw).hexdigest()
        ),
        cleanup_entries=inventory,
        completed_cleanup_cursor=None,
        completed_owner_journal_identity=None,
        completed_owner_journal_sha256=None,
    )
    owner = _owner_retirement_fixture()
    owner.pop("content_sha256")
    owner.update(
        {
            "stage": "PREPARED_PLANNED",
            "tombstone_path": str(tombstone_path),
            "tombstone_parent_identity": list(path_identity(tombstone_path.parent)),
            "tombstone_identity": None,
            "tombstone_sha256": "sha256:" + hashlib.sha256(prepared_raw).hexdigest(),
            "retired_owner_transaction_id": old_id,
            "initial_owner_journal_path": str(old_path),
            "initial_owner_journal_identity": list(path_identity(old_path)),
            "initial_owner_journal_sha256": "sha256:" + hashlib.sha256(old_raw).hexdigest(),
            "current_owner_journal_identity": list(path_identity(old_path)),
            "current_owner_journal_sha256": "sha256:" + hashlib.sha256(old_raw).hexdigest(),
            "retired_target_path": str(target),
            "retired_target_parent_identity": list(path_identity(target.parent)),
            "retired_target_identity": list(target_identity),
            "retired_target_tree_sha256": tree_sha256,
            "successor_transaction_id": successor_id,
            "successor_package_root_sha256": "sha256:" + "a" * 64,
            "successor_owner_journal_path": str(successor_path),
            "successor_owner_journal_identity": list(path_identity(successor_path)),
            "successor_owner_journal_sha256": (
                "sha256:" + hashlib.sha256(successor_raw).hexdigest()
            ),
            "cleanup_manifest_sha256": "sha256:"
            + hashlib.sha256(
                runtime_installer._canonical_owner_retirement_json(
                    runtime_installer._plain_json_value(inventory)
                )
            ).hexdigest(),
            "cleanup_entry_count": count,
            "cleanup_cursor": 0,
            "planned_completed_tombstone_size": None,
            "planned_completed_tombstone_sha256": None,
            "next_entry_relative_path": (
                None if count == 0 else inventory[0]["relative_path"]
            ),
            "next_entry_kind": (
                None if count == 0 else inventory[0]["entry_kind"]
            ),
            "next_entry_identity": (
                None if count == 0 else list(inventory[0]["identity"])
            ),
            "next_entry_parent_identity": (
                None
                if count == 0
                else list(inventory[0]["expected_parent_identity"])
            ),
            "next_entry_size": None if count == 0 else inventory[0]["size"],
            "next_entry_sha256": None if count == 0 else inventory[0]["sha256"],
            "old_owner_journal_retired": False,
        }
    )
    owner = _seal_literal_document(owner)
    staging = tombstone_path.with_name(f"{tombstone_path.name}.staged")
    external = session._build_external_file_action(
        action_kind="commit_owner_retirement_prepared",
        action_index=10,
        final_path=tombstone_path,
        staging_path=staging,
        inner_temp_path=staging.with_name(
            f".{staging.name}.live-start-atomic.tmp"
        ),
        parent_identity=path_identity(tombstone_path.parent),
        predecessor_identity=None,
        predecessor_size=None,
        predecessor_sha256=None,
        planned_successor_size=len(prepared_raw),
        planned_successor_sha256="sha256:" + hashlib.sha256(prepared_raw).hexdigest(),
        commit_mode="create_no_replace",
    )
    root, cursor, _recovery = _apply_recovery_cursor_for_action(
        base / "session",
        action="materialize_file_action_staging",
        recovery_changes={
            "owner_retirement": owner,
            "external_file_action": session._thaw(external),
        },
    )
    if session_root_out is not None:
        session_root_out.append(root)

    actions: list[str] = []
    layout_identities = {
        "custom_config": path_identity(target.parent),
        "transactions": path_identity(old_path.parent),
        "owner_retirements": path_identity(tombstone_path.parent),
    }
    crash_injected = False

    def step(current: object) -> object:
        nonlocal crash_injected
        recovery = current.apply_recovery
        assert isinstance(recovery, Mapping)
        action = recovery["expected_action"]
        assert isinstance(action, str)
        actions.append(action)
        callback = {
            "materialize_file_action_staging": runtime_installer._owner_retirement_materialize_action,
            "commit_owner_retirement_prepared": runtime_installer._owner_retirement_commit_prepared_action,
            "initialize_owner_cleanup_journal": runtime_installer._owner_retirement_initialize_journal_action,
            "delete_owner_cleanup_entry": runtime_installer._owner_retirement_delete_entry_action,
            "advance_owner_cleanup_journal": runtime_installer._owner_retirement_advance_journal_action,
            "retire_owner_target_root": runtime_installer._owner_retirement_retire_root_action,
            "commit_owner_retirement_completed": runtime_installer._owner_retirement_commit_completed_action,
            "retire_old_owner_journal": runtime_installer._owner_retirement_retire_old_journal_action,
            "observe_owner_retirement_completed": runtime_installer._owner_retirement_observe_completed_action,
        }.get(action)
        if callback is None:
            return current
        owner_value = recovery.get("owner_retirement")
        assert isinstance(owner_value, Mapping)
        checkpoint = (
            str(owner_value["stage"]),
            action,
            int(owner_value["cleanup_cursor"]),
        )
        if (
            not crash_injected
            and crash_before_cas_checkpoint is not None
            and checkpoint == crash_before_cas_checkpoint
        ):
            callback(
                recovery=recovery,
                runtime_root=runtime_root,
                layout_identities=layout_identities,
            )
            crash_injected = True
            if crash_replays_out is not None:
                crash_replays_out.append(checkpoint)
            if action == "materialize_file_action_staging":
                with _lease(root) as lease:
                    retirement_authorization = (
                        session._authorize_nonterminal_apply_recovery_under_lock(
                            session_lease=lease,
                            expected_recovery_session=current,
                            expected_action=(
                                "retire_unbound_file_action_staging"
                            ),
                        )
                    )
                    retirement_receipt = (
                        session._execute_apply_recovery_physical_step(
                            recovery_authorization=retirement_authorization,
                            action="retire_unbound_file_action_staging",
                            physical_action=lambda: (
                                runtime_installer._retire_unbound_recovery_external_file_action(
                                    recovery=recovery
                                )
                            ),
                        )
                    )
                    current = (
                        session.advance_nonterminal_apply_recovery_under_lock(
                            session_lease=lease,
                            expected_recovery_session=current,
                            transition="physical_recovery_advanced",
                            recovery_evidence=None,
                            recovery_authorization=None,
                            physical_step_receipt=retirement_receipt,
                            runtime_observation_receipt=None,
                        )
                    )
                recovery = current.apply_recovery
                assert isinstance(recovery, Mapping)
                assert recovery["expected_action"] == action
        with _lease(root) as lease:
            authorization = session._authorize_nonterminal_apply_recovery_under_lock(
                session_lease=lease,
                expected_recovery_session=current,
                expected_action=action,
            )
            receipt = session._execute_apply_recovery_physical_step(
                recovery_authorization=authorization,
                action=action,
                physical_action=lambda: callback(
                    recovery=recovery,
                    runtime_root=runtime_root,
                    layout_identities=layout_identities,
                ),
            )
            return session.advance_nonterminal_apply_recovery_under_lock(
                session_lease=lease,
                expected_recovery_session=current,
                transition="physical_recovery_advanced",
                recovery_evidence=None,
                recovery_authorization=None,
                physical_step_receipt=receipt,
                runtime_observation_receipt=None,
            )

    while True:
        recovery = cursor.apply_recovery
        if (
            stop_before_action is not None
            and isinstance(recovery, Mapping)
            and recovery.get("expected_action") == stop_before_action
        ):
            break
        next_cursor = step(cursor)
        if next_cursor is cursor:
            break
        cursor = next_cursor
    if stop_before_action is not None:
        recovery = cursor.apply_recovery
        assert isinstance(recovery, Mapping)
        assert recovery["expected_action"] == stop_before_action
    return runtime_root, cursor, target, tombstone_path, old_path, actions


def test_owner_retirement_root_rmdir_action_before_cas_confirms_only_authorized_absence(
    tmp_path: Path,
    monkeypatch: pytest.MonkeyPatch,
) -> None:
    import hsconfig.live_start_session as live_start_session
    from tests.test_live_start_session import _lease

    def root_ready_trace(base: Path) -> SimpleNamespace:
        session_roots: list[Path] = []
        runtime_root, cursor, target, tombstone_path, old_path, actions = (
            _owner_retirement_runtime_trace(
                base,
                count=0,
                stop_before_action="retire_owner_target_root",
                session_root_out=session_roots,
            )
        )
        assert len(session_roots) == 1
        recovery = cursor.apply_recovery
        assert isinstance(recovery, Mapping)
        assert recovery["expected_action"] == "retire_owner_target_root"
        assert recovery["owner_retirement"]["stage"] == "CLEANING"
        assert target.exists()
        assert not tuple(target.iterdir())
        assert actions == [
            "materialize_file_action_staging",
            "commit_owner_retirement_prepared",
            "materialize_file_action_staging",
            "initialize_owner_cleanup_journal",
        ]
        return SimpleNamespace(
            runtime_root=runtime_root,
            session_root=session_roots[0],
            cursor=cursor,
            recovery=recovery,
            target=target,
            tombstone_path=tombstone_path,
            old_path=old_path,
            layout_identities={
                "runtime_root": path_identity(runtime_root),
                "custom_config": path_identity(target.parent),
                "transactions": path_identity(old_path.parent),
                "owner_retirements": path_identity(tombstone_path.parent),
            },
        )

    def root_callback(fixture: SimpleNamespace) -> object:
        return runtime_installer._owner_retirement_retire_root_action(
            recovery=fixture.recovery,
            runtime_root=fixture.runtime_root,
            layout_identities=fixture.layout_identities,
        )

    positive = root_ready_trace(tmp_path / "unchanged-parent")
    positive_session_path = positive.session_root / "session.json"
    positive_session_before = positive_session_path.read_bytes()
    positive_parent_identity = path_identity(positive.target.parent)
    with _lease(positive.session_root) as lease:
        first_authorization = (
            live_start_session._authorize_nonterminal_apply_recovery_under_lock(
                session_lease=lease,
                expected_recovery_session=positive.cursor,
                expected_action="retire_owner_target_root",
            )
        )
        first_receipt = (
            live_start_session._execute_apply_recovery_physical_step(
                recovery_authorization=first_authorization,
                action="retire_owner_target_root",
                physical_action=lambda: root_callback(positive),
            )
        )
        assert not positive.target.exists()
        assert positive_session_path.read_bytes() == positive_session_before
        assert path_identity(positive.target.parent) == positive_parent_identity
        runtime_after_first_delete = _runtime_nonlock_surface_evidence(
            positive.runtime_root
        )

        # Losing the caller-visible receipt in the same live process must not
        # release the one outstanding physical row slot.  Exiting the lease
        # below models the process boundary that clears only ephemeral authority.
        del first_receipt
        with pytest.raises(
            live_start_session.SessionConflictError,
            match="^live_start_nonterminal_physical_authorization_outstanding$",
        ):
            live_start_session._authorize_nonterminal_apply_recovery_under_lock(
                session_lease=lease,
                expected_recovery_session=positive.cursor,
                expected_action="retire_owner_target_root",
            )

    with _lease(positive.session_root) as lease:
        replay_authorization = (
            live_start_session._authorize_nonterminal_apply_recovery_under_lock(
                session_lease=lease,
                expected_recovery_session=positive.cursor,
                expected_action="retire_owner_target_root",
            )
        )
        replay_receipt = (
            live_start_session._execute_apply_recovery_physical_step(
                recovery_authorization=replay_authorization,
                action="retire_owner_target_root",
                physical_action=lambda: root_callback(positive),
            )
        )

    replay_postcondition = replay_receipt._opaque.successor
    assert replay_postcondition.action == "retire_owner_target_root"
    assert replay_postcondition.evidence["owner_root_postcondition"][
        "disposition"
    ] == "already_absent"
    assert replay_postcondition.evidence["_owner_object_preexisting"] is False
    assert _runtime_nonlock_surface_evidence(positive.runtime_root) == (
        runtime_after_first_delete
    )
    assert positive_session_path.read_bytes() == positive_session_before

    replaced = root_ready_trace(tmp_path / "replaced-parent")
    replaced_session_path = replaced.session_root / "session.json"
    replaced_session_before = replaced_session_path.read_bytes()
    replaced_parent = replaced.target.parent
    persisted_parent_identity = path_identity(replaced_parent)
    derivation_calls: list[str] = []
    real_prepared_tombstone = (
        runtime_installer._owner_retirement_prepared_tombstone
    )
    real_read_bound_file = runtime_installer._owner_retirement_read_bound_file

    def observe_prepared_tombstone(*args: object, **kwargs: object) -> object:
        derivation_calls.append("prepared_tombstone")
        return real_prepared_tombstone(*args, **kwargs)

    def observe_read_bound_file(*args: object, **kwargs: object) -> bytes:
        derivation_calls.append("read_bound_file")
        return real_read_bound_file(*args, **kwargs)

    with _lease(replaced.session_root) as lease:
        first_authorization = (
            live_start_session._authorize_nonterminal_apply_recovery_under_lock(
                session_lease=lease,
                expected_recovery_session=replaced.cursor,
                expected_action="retire_owner_target_root",
            )
        )
        first_receipt = (
            live_start_session._execute_apply_recovery_physical_step(
                recovery_authorization=first_authorization,
                action="retire_owner_target_root",
                physical_action=lambda: root_callback(replaced),
            )
        )
        assert not replaced.target.exists()
        del first_receipt
        with pytest.raises(
            live_start_session.SessionConflictError,
            match="^live_start_nonterminal_physical_authorization_outstanding$",
        ):
            live_start_session._authorize_nonterminal_apply_recovery_under_lock(
                session_lease=lease,
                expected_recovery_session=replaced.cursor,
                expected_action="retire_owner_target_root",
            )

    with _lease(replaced.session_root) as lease:
        replay_authorization = (
            live_start_session._authorize_nonterminal_apply_recovery_under_lock(
                session_lease=lease,
                expected_recovery_session=replaced.cursor,
                expected_action="retire_owner_target_root",
            )
        )
        parent_backup = replaced.runtime_root.parent / "original-custom-config"
        replaced_parent.rename(parent_backup)
        replaced_parent.mkdir()
        for child in tuple(parent_backup.iterdir()):
            child.rename(replaced_parent / child.name)
        assert path_identity(replaced_parent) != persisted_parent_identity
        runtime_after_parent_replacement = _runtime_nonlock_surface_evidence(
            replaced.runtime_root
        )

        with monkeypatch.context() as guarded:
            guarded.setattr(
                runtime_installer,
                "_owner_retirement_prepared_tombstone",
                observe_prepared_tombstone,
            )
            guarded.setattr(
                runtime_installer,
                "_owner_retirement_read_bound_file",
                observe_read_bound_file,
            )
            with pytest.raises(
                ValueError,
                match="^runtime_owner_retirement_target_parent_changed$",
            ):
                live_start_session._execute_apply_recovery_physical_step(
                    recovery_authorization=replay_authorization,
                    action="retire_owner_target_root",
                    physical_action=lambda: root_callback(replaced),
                )

    assert derivation_calls == []
    assert _runtime_nonlock_surface_evidence(replaced.runtime_root) == (
        runtime_after_parent_replacement
    )
    assert replaced_session_path.read_bytes() == replaced_session_before

    post_rmdir = root_ready_trace(tmp_path / "parent-replaced-after-rmdir")
    post_rmdir_session_path = post_rmdir.session_root / "session.json"
    post_rmdir_session_before = post_rmdir_session_path.read_bytes()
    post_rmdir_parent = post_rmdir.target.parent
    post_rmdir_parent_identity = path_identity(post_rmdir_parent)
    derivation_events: list[str] = []
    events_at_attack: list[str] = []
    attacked_runtime: list[tuple[object, ...]] = []
    real_secure_rmdir = runtime_installer.secure_rmdir_verified
    real_prepared_tombstone = (
        runtime_installer._owner_retirement_prepared_tombstone
    )
    real_read_bound_file = runtime_installer._owner_retirement_read_bound_file
    real_completed_bytes = runtime_installer._owner_retirement_completed_bytes
    real_external_action = runtime_installer._owner_retirement_external_action

    def observe_prepared_before_rmdir(
        *args: object,
        **kwargs: object,
    ) -> object:
        derivation_events.append("prepared_tombstone")
        return real_prepared_tombstone(*args, **kwargs)

    def observe_bound_read_before_or_after_rmdir(
        *args: object,
        **kwargs: object,
    ) -> bytes:
        raw_path = args[0] if args else kwargs["path"]
        path = Path(str(raw_path))
        derivation_events.append(
            "read_tombstone"
            if path == post_rmdir.tombstone_path
            else "read_journal"
        )
        return real_read_bound_file(*args, **kwargs)

    def observe_completed_after_rmdir(
        *args: object,
        **kwargs: object,
    ) -> bytes:
        derivation_events.append("completed_tombstone")
        return real_completed_bytes(*args, **kwargs)

    def observe_external_after_rmdir(
        *args: object,
        **kwargs: object,
    ) -> object:
        derivation_events.append("next_external")
        return real_external_action(*args, **kwargs)

    def rmdir_then_replace_parent(
        *args: object,
        **kwargs: object,
    ) -> object:
        result = real_secure_rmdir(*args, **kwargs)
        assert not post_rmdir.target.exists()
        derivation_events.append("secure_rmdir")
        parent_backup = (
            post_rmdir.runtime_root.parent / "post-rmdir-original-custom-config"
        )
        post_rmdir_parent.rename(parent_backup)
        post_rmdir_parent.mkdir()
        for child in tuple(parent_backup.iterdir()):
            child.rename(post_rmdir_parent / child.name)
        assert path_identity(post_rmdir_parent) != post_rmdir_parent_identity
        events_at_attack.extend(derivation_events)
        attacked_runtime.append(
            _runtime_nonlock_surface_evidence(post_rmdir.runtime_root)
        )
        return result

    with _lease(post_rmdir.session_root) as lease:
        authorization = (
            live_start_session._authorize_nonterminal_apply_recovery_under_lock(
                session_lease=lease,
                expected_recovery_session=post_rmdir.cursor,
                expected_action="retire_owner_target_root",
            )
        )
        with monkeypatch.context() as guarded:
            guarded.setattr(
                runtime_installer,
                "_owner_retirement_prepared_tombstone",
                observe_prepared_before_rmdir,
            )
            guarded.setattr(
                runtime_installer,
                "_owner_retirement_read_bound_file",
                observe_bound_read_before_or_after_rmdir,
            )
            guarded.setattr(
                runtime_installer,
                "_owner_retirement_completed_bytes",
                observe_completed_after_rmdir,
            )
            guarded.setattr(
                runtime_installer,
                "_owner_retirement_external_action",
                observe_external_after_rmdir,
            )
            guarded.setattr(
                runtime_installer,
                "secure_rmdir_verified",
                rmdir_then_replace_parent,
            )
            with pytest.raises(
                ValueError,
                match="^runtime_owner_retirement_target_parent_changed$",
            ):
                live_start_session._execute_apply_recovery_physical_step(
                    recovery_authorization=authorization,
                    action="retire_owner_target_root",
                    physical_action=lambda: root_callback(post_rmdir),
                )

    assert len(attacked_runtime) == 1
    assert derivation_events == events_at_attack
    assert "secure_rmdir" in events_at_attack
    assert "read_journal" not in events_at_attack
    assert "completed_tombstone" not in events_at_attack
    assert "next_external" not in events_at_attack
    assert _runtime_nonlock_surface_evidence(post_rmdir.runtime_root) == (
        attacked_runtime[0]
    )
    assert post_rmdir_session_path.read_bytes() == post_rmdir_session_before


def test_owner_retirement_root_receipt_uses_only_prebound_completed_commitment(
    tmp_path: Path,
    monkeypatch: pytest.MonkeyPatch,
) -> None:
    import hsconfig.live_start_session as live_start_session
    from tests.test_live_start_session import _lease, _seal_literal_document

    session_roots: list[Path] = []
    runtime_root, cursor, target, tombstone_path, old_path, actions = (
        _owner_retirement_runtime_trace(
            tmp_path,
            count=0,
            stop_before_action="retire_owner_target_root",
            session_root_out=session_roots,
        )
    )
    assert len(session_roots) == 1
    assert actions == [
        "materialize_file_action_staging",
        "commit_owner_retirement_prepared",
        "materialize_file_action_staging",
        "initialize_owner_cleanup_journal",
    ]
    recovery = cursor.apply_recovery
    assert isinstance(recovery, Mapping)
    assert recovery["expected_action"] == "retire_owner_target_root"
    assert recovery["external_file_action"] is None
    owner = recovery["owner_retirement"]
    assert isinstance(owner, Mapping)
    assert owner["stage"] == "CLEANING"
    assert owner["cleanup_cursor"] == owner["cleanup_entry_count"] == 0
    assert all(
        owner[field_name] is None
        for field_name in (
            "next_entry_relative_path",
            "next_entry_kind",
            "next_entry_identity",
            "next_entry_parent_identity",
            "next_entry_size",
            "next_entry_sha256",
        )
    )
    assert target.is_dir() and not tuple(target.iterdir())

    layout_identities = {
        "runtime_root": path_identity(runtime_root),
        "custom_config": path_identity(target.parent),
        "transactions": path_identity(old_path.parent),
        "owner_retirements": path_identity(tombstone_path.parent),
    }
    owner_value = runtime_installer._plain_json_value(owner)
    assert isinstance(owner_value, dict)
    prepared_before = tombstone_path.read_bytes()
    prepared_identity = path_identity(tombstone_path)
    prepared = runtime_installer._parse_owner_retirement_tombstone_bytes(
        prepared_before,
        runtime_root=runtime_root,
    )
    assert prepared["state"] == "PREPARED"
    assert prepared_identity == tuple(owner["tombstone_identity"])
    assert runtime_installer._owner_retirement_digest(prepared_before) == owner[
        "tombstone_sha256"
    ]
    journal_before = old_path.read_bytes()
    journal_identity = path_identity(old_path)
    final_v1 = runtime_installer.read_runtime_transaction_journal(old_path)
    assert final_v1.phase is RuntimeTransactionPhase.FINALIZED
    assert final_v1.cleanup_started is True
    assert final_v1.cleanup_cursor == 0
    assert journal_identity == tuple(owner["current_owner_journal_identity"])
    assert runtime_installer._owner_retirement_digest(journal_before) == owner[
        "current_owner_journal_sha256"
    ]

    real_completed_bytes = runtime_installer._owner_retirement_completed_bytes
    completed_before = real_completed_bytes(
        owner=owner,
        runtime_root=runtime_root,
        journal_identity=journal_identity,
        journal_sha256=str(owner["current_owner_journal_sha256"]),
        owner_retirements_parent_identity=layout_identities[
            "owner_retirements"
        ],
    )
    planned_size = owner["planned_completed_tombstone_size"]
    planned_sha256 = owner["planned_completed_tombstone_sha256"]
    assert type(planned_size) is int and planned_size > 0
    assert isinstance(planned_sha256, str)
    assert len(completed_before) == planned_size
    assert runtime_installer._owner_retirement_digest(completed_before) == (
        planned_sha256
    )

    session_path = session_roots[0] / "session.json"
    session_before = (path_identity(session_path), session_path.read_bytes())
    staging_path = tombstone_path.with_name(f"{tombstone_path.name}.staged")
    inner_temp_path = staging_path.with_name(
        f".{staging_path.name}.live-start-atomic.tmp"
    )
    expected_external = _seal_literal_document(
        {
            "schema_version": 1,
            "action_kind": "commit_owner_retirement_completed",
            "action_index": int(recovery["action_index"]) + 1,
            "stage": "PLANNED",
            "final_path": str(tombstone_path),
            "staging_path": str(staging_path),
            "inner_temp_path": str(inner_temp_path),
            "parent_identity": owner_value["tombstone_parent_identity"],
            "predecessor_state": "exact",
            "predecessor_identity": owner_value["tombstone_identity"],
            "predecessor_size": len(prepared_before),
            "predecessor_sha256": owner_value["tombstone_sha256"],
            "planned_successor_size": planned_size,
            "planned_successor_sha256": planned_sha256,
            "staging_identity": None,
            "staging_size": None,
            "staging_sha256": None,
            "commit_mode": "replace_exact",
        }
    )
    expected_root_postcondition = {
        "target_path": owner_value["retired_target_path"],
        "historical_target_identity": owner_value["retired_target_identity"],
        "target_parent_identity": owner_value[
            "retired_target_parent_identity"
        ],
        "prepared_tombstone_path": owner_value["tombstone_path"],
        "prepared_tombstone_identity": owner_value["tombstone_identity"],
        "prepared_tombstone_sha256": owner_value["tombstone_sha256"],
        "final_owner_journal_path": owner_value[
            "initial_owner_journal_path"
        ],
        "final_owner_journal_identity": owner_value[
            "current_owner_journal_identity"
        ],
        "final_owner_journal_sha256": owner_value[
            "current_owner_journal_sha256"
        ],
        "cleanup_manifest_sha256": owner_value["cleanup_manifest_sha256"],
        "cleanup_entry_count": 0,
        "planned_completed_tombstone_size": planned_size,
        "planned_completed_tombstone_sha256": planned_sha256,
        "disposition": "removed",
    }

    def completed_bytes_forbidden_at_root(
        *_args: object,
        **_kwargs: object,
    ) -> bytes:
        raise AssertionError(
            "retire_owner_target_root_must_use_prebound_completed_commitment"
        )

    with _lease(session_roots[0]) as lease:
        authorization = (
            live_start_session._authorize_nonterminal_apply_recovery_under_lock(
                session_lease=lease,
                expected_recovery_session=cursor,
                expected_action="retire_owner_target_root",
            )
        )
        with monkeypatch.context() as root_guard:
            root_guard.setattr(
                runtime_installer,
                "_owner_retirement_completed_bytes",
                completed_bytes_forbidden_at_root,
            )
            receipt = live_start_session._execute_apply_recovery_physical_step(
                recovery_authorization=authorization,
                action="retire_owner_target_root",
                physical_action=lambda: (
                    runtime_installer._owner_retirement_retire_root_action(
                        recovery=recovery,
                        runtime_root=runtime_root,
                        layout_identities=layout_identities,
                    )
                ),
            )

        assert not target.exists()
        assert (path_identity(session_path), session_path.read_bytes()) == (
            session_before
        )
        assert (path_identity(tombstone_path), tombstone_path.read_bytes()) == (
            prepared_identity,
            prepared_before,
        )
        assert (path_identity(old_path), old_path.read_bytes()) == (
            journal_identity,
            journal_before,
        )
        postcondition = receipt._opaque.successor
        assert isinstance(
            postcondition,
            live_start_session.RuntimeApplyRecoveryPhysicalPostcondition,
        )
        assert postcondition.action == "retire_owner_target_root"
        evidence = runtime_installer._plain_json_value(postcondition.evidence)
        assert isinstance(evidence, dict)
        assert set(evidence) == {
            "_owner_object_preexisting",
            "apply_recovery",
            "owner_root_postcondition",
        }
        assert evidence["_owner_object_preexisting"] is True
        assert evidence["owner_root_postcondition"] == (
            expected_root_postcondition
        )
        successor = evidence["apply_recovery"]
        assert isinstance(successor, dict)
        successor_owner = successor["owner_retirement"]
        assert isinstance(successor_owner, dict)
        assert successor_owner["stage"] == "TARGET_RETIRED"
        for field_name, field_value in owner_value.items():
            if field_name not in {"stage", "content_sha256"}:
                assert successor_owner[field_name] == field_value
        assert successor["expected_action"] == "materialize_file_action_staging"
        assert successor["external_file_action"] == expected_external

        target_retired = (
            live_start_session.advance_nonterminal_apply_recovery_under_lock(
                session_lease=lease,
                expected_recovery_session=cursor,
                transition="physical_recovery_advanced",
                recovery_evidence=None,
                recovery_authorization=None,
                physical_step_receipt=receipt,
                runtime_observation_receipt=None,
            )
        )
        target_retired_recovery = target_retired.apply_recovery
        assert isinstance(target_retired_recovery, Mapping)
        assert target_retired_recovery["expected_action"] == (
            "materialize_file_action_staging"
        )
        target_retired_owner = target_retired_recovery["owner_retirement"]
        assert target_retired_owner["stage"] == "TARGET_RETIRED"
        assert runtime_installer._plain_json_value(
            target_retired_recovery["external_file_action"]
        ) == runtime_installer._plain_json_value(expected_external)
        assert (path_identity(tombstone_path), tombstone_path.read_bytes()) == (
            prepared_identity,
            prepared_before,
        )
        assert (path_identity(old_path), old_path.read_bytes()) == (
            journal_identity,
            journal_before,
        )

        completed_derivations: list[bytes] = []

        def observe_completed_bytes(
            *args: object,
            **kwargs: object,
        ) -> bytes:
            raw = real_completed_bytes(*args, **kwargs)
            completed_derivations.append(raw)
            return raw

        session_after_root_cas = (
            path_identity(session_path),
            session_path.read_bytes(),
        )
        materialize_authorization = (
            live_start_session._authorize_nonterminal_apply_recovery_under_lock(
                session_lease=lease,
                expected_recovery_session=target_retired,
                expected_action="materialize_file_action_staging",
            )
        )
        with monkeypatch.context() as materialize_observer:
            materialize_observer.setattr(
                runtime_installer,
                "_owner_retirement_completed_bytes",
                observe_completed_bytes,
            )
            materialize_receipt = (
                live_start_session._execute_apply_recovery_physical_step(
                    recovery_authorization=materialize_authorization,
                    action="materialize_file_action_staging",
                    physical_action=lambda: (
                        runtime_installer._owner_retirement_materialize_action(
                            recovery=target_retired_recovery,
                            runtime_root=runtime_root,
                            layout_identities=layout_identities,
                        )
                    ),
                )
            )

        assert completed_derivations == [completed_before]
        assert staging_path.read_bytes() == completed_before
        completed = runtime_installer._parse_owner_retirement_tombstone_bytes(
            staging_path.read_bytes(),
            runtime_root=runtime_root,
        )
        assert completed["state"] == "COMPLETED"
        assert completed["completed_cleanup_cursor"] == 0
        assert tuple(completed["completed_owner_journal_identity"]) == (
            journal_identity
        )
        assert completed["completed_owner_journal_sha256"] == (
            owner["current_owner_journal_sha256"]
        )
        assert (path_identity(session_path), session_path.read_bytes()) == (
            session_after_root_cas
        )
        assert tombstone_path.read_bytes() == prepared_before
        assert old_path.read_bytes() == journal_before
        materialize_postcondition = materialize_receipt._opaque.successor
        assert materialize_postcondition.action == (
            "materialize_file_action_staging"
        )
        materialize_successor = materialize_postcondition.evidence[
            "apply_recovery"
        ]
        assert materialize_successor["expected_action"] == (
            "commit_owner_retirement_completed"
        )
        bound_external = materialize_successor["external_file_action"]
        assert bound_external["stage"] == "STAGING_BOUND"
        assert bound_external["planned_successor_size"] == planned_size
        assert bound_external["planned_successor_sha256"] == planned_sha256
        assert bound_external["predecessor_identity"] == owner[
            "tombstone_identity"
        ]
        assert bound_external["predecessor_sha256"] == owner[
            "tombstone_sha256"
        ]


@pytest.mark.parametrize(
    "substitution",
    (
        "tombstone_list",
        "final_v1",
        "late_tombstone_list",
        "late_final_v1",
    ),
)
def test_owner_retirement_root_crash_rejects_tombstone_list_or_final_v1_substitution(
    tmp_path: Path,
    monkeypatch: pytest.MonkeyPatch,
    substitution: str,
) -> None:
    import hsconfig.live_start_session as live_start_session
    from tests.test_live_start_session import _lease

    session_roots: list[Path] = []
    runtime_root, cursor, target, tombstone_path, old_path, _actions = (
        _owner_retirement_runtime_trace(
            tmp_path,
            count=1,
            stop_before_action="retire_owner_target_root",
            session_root_out=session_roots,
        )
    )
    assert len(session_roots) == 1
    recovery = cursor.apply_recovery
    assert isinstance(recovery, Mapping)
    assert recovery["expected_action"] == "retire_owner_target_root"
    owner = recovery["owner_retirement"]
    assert isinstance(owner, Mapping)
    assert owner["stage"] == "CLEANING"
    assert owner["cleanup_cursor"] == owner["cleanup_entry_count"] == 1
    assert target.is_dir() and not tuple(target.iterdir())
    layout_identities = {
        "runtime_root": path_identity(runtime_root),
        "custom_config": path_identity(target.parent),
        "transactions": path_identity(old_path.parent),
        "owner_retirements": path_identity(tombstone_path.parent),
    }
    session_path = session_roots[0] / "session.json"
    session_before = (path_identity(session_path), session_path.read_bytes())
    tombstone_before = (path_identity(tombstone_path), tombstone_path.read_bytes())
    journal_before = (path_identity(old_path), old_path.read_bytes())
    substituted_path = (
        tombstone_path if "tombstone_list" in substitution else old_path
    )
    substituted_before = (
        tombstone_before if "tombstone_list" in substitution else journal_before
    )
    replacement_identity: tuple[int, int, int] | None = None
    runtime_after_substitution: tuple[object, ...] | None = None
    real_secure_rmdir = runtime_installer.secure_rmdir_verified
    real_prepared_tombstone = runtime_installer._owner_retirement_prepared_tombstone
    real_read_bound_file = runtime_installer._owner_retirement_read_bound_file
    prepared_tombstone_reads = 0

    def replace_bound_authority() -> None:
        nonlocal replacement_identity, runtime_after_substitution
        assert not target.exists()
        replacement = substituted_path.with_name(
            f"{substituted_path.name}.{substitution}.replacement"
        )
        replacement.write_bytes(substituted_before[1])
        replacement_identity = path_identity(replacement)
        assert replacement_identity != substituted_before[0]
        os.replace(replacement, substituted_path)
        assert path_identity(substituted_path) == replacement_identity
        runtime_after_substitution = _runtime_nonlock_surface_evidence(runtime_root)

    def substitute_after_root_retirement(
        *args: object,
        **kwargs: object,
    ) -> object:
        result = real_secure_rmdir(*args, **kwargs)
        if not substitution.startswith("late_"):
            replace_bound_authority()
        return result

    def substitute_after_final_tombstone_read(
        *args: object,
        **kwargs: object,
    ) -> object:
        nonlocal prepared_tombstone_reads
        result = real_prepared_tombstone(*args, **kwargs)
        prepared_tombstone_reads += 1
        if substitution == "late_tombstone_list" and prepared_tombstone_reads == 2:
            replace_bound_authority()
        return result

    def substitute_after_final_v1_read(
        path: Path,
        *args: object,
        **kwargs: object,
    ) -> bytes:
        result = real_read_bound_file(path, *args, **kwargs)
        if substitution == "late_final_v1" and path == old_path:
            replace_bound_authority()
        return result

    with _lease(session_roots[0]) as lease:
        authorization = (
            live_start_session._authorize_nonterminal_apply_recovery_under_lock(
                session_lease=lease,
                expected_recovery_session=cursor,
                expected_action="retire_owner_target_root",
            )
        )
        with monkeypatch.context() as root_crash:
            root_crash.setattr(
                runtime_installer,
                "secure_rmdir_verified",
                substitute_after_root_retirement,
            )
            root_crash.setattr(
                runtime_installer,
                "_owner_retirement_prepared_tombstone",
                substitute_after_final_tombstone_read,
            )
            root_crash.setattr(
                runtime_installer,
                "_owner_retirement_read_bound_file",
                substitute_after_final_v1_read,
            )
            with pytest.raises(
                ValueError,
                match="^runtime_owner_retirement_authority_changed$",
            ):
                live_start_session._execute_apply_recovery_physical_step(
                    recovery_authorization=authorization,
                    action="retire_owner_target_root",
                    physical_action=lambda: (
                        runtime_installer._owner_retirement_retire_root_action(
                            recovery=recovery,
                            runtime_root=runtime_root,
                            layout_identities=layout_identities,
                        )
                    ),
                )

    assert replacement_identity is not None
    assert runtime_after_substitution is not None
    assert _runtime_nonlock_surface_evidence(runtime_root) == (
        runtime_after_substitution
    )
    assert (path_identity(session_path), session_path.read_bytes()) == session_before
    assert not target.exists()
    assert (path_identity(substituted_path), substituted_path.read_bytes()) == (
        replacement_identity,
        substituted_before[1],
    )
    retained_path, retained_before = (
        (old_path, journal_before)
        if "tombstone_list" in substitution
        else (tombstone_path, tombstone_before)
    )
    assert (path_identity(retained_path), retained_path.read_bytes()) == retained_before
    staging_path = tombstone_path.with_name(f"{tombstone_path.name}.staged")
    assert not staging_path.exists()
    assert not staging_path.with_name(
        f".{staging_path.name}.live-start-atomic.tmp"
    ).exists()


def test_owner_retirement_root_rejects_invalid_completed_commitment_before_mutation(
    tmp_path: Path,
) -> None:
    session_roots: list[Path] = []
    runtime_root, cursor, target, tombstone_path, old_path, _actions = (
        _owner_retirement_runtime_trace(
            tmp_path,
            count=0,
            stop_before_action="retire_owner_target_root",
            session_root_out=session_roots,
        )
    )
    recovery = cursor.apply_recovery
    assert isinstance(recovery, Mapping)
    owner = recovery["owner_retirement"]
    assert isinstance(owner, Mapping)
    changed_owner = runtime_installer._seal_owner_retirement_document(
        owner,
        changes={"planned_completed_tombstone_size": 0},
    )
    changed_recovery = runtime_installer._plain_json_value(recovery)
    assert isinstance(changed_recovery, dict)
    changed_recovery["owner_retirement"] = changed_owner
    layout_identities = {
        "runtime_root": path_identity(runtime_root),
        "custom_config": path_identity(target.parent),
        "transactions": path_identity(old_path.parent),
        "owner_retirements": path_identity(tombstone_path.parent),
    }
    runtime_before = _runtime_nonlock_surface_evidence(runtime_root)
    target_before = (path_identity(target), _filesystem_surface_evidence(target))

    with pytest.raises(ValueError):
        runtime_installer._owner_retirement_retire_root_action(
            recovery=changed_recovery,
            runtime_root=runtime_root,
            layout_identities=layout_identities,
        )

    assert _runtime_nonlock_surface_evidence(runtime_root) == runtime_before
    assert (path_identity(target), _filesystem_surface_evidence(target)) == (
        target_before
    )


