def test_old_success_accepts_exact_owner_retirement_tombstone_after_later_cleanup(
    tmp_path: Path,
) -> None:
    runtime_root, _cursor, target, tombstone_path, old_path, _actions = (
        _owner_retirement_runtime_trace(tmp_path, count=1)
    )
    tombstone = runtime_installer._parse_owner_retirement_tombstone_bytes(
        tombstone_path.read_bytes(), runtime_root=runtime_root
    )
    assert tombstone["state"] == "COMPLETED"
    assert not target.exists()
    assert not old_path.exists()
    old_id = str(tombstone["retired_owner_transaction_id"])
    retention_owner = "c" * 32
    retention_raw = runtime_installer.build_runtime_attempt_retention_bytes(
        runtime_root=runtime_root,
        state="FINALIZED",
        apply_attempt_id=old_id,
        retention_owner_run_id=retention_owner,
        journal_path=old_path,
        journal_identity=tuple(tombstone["initial_owner_journal_identity"]),
        journal_sha256=str(tombstone["initial_owner_journal_sha256"]),
        package_root_sha256="sha256:" + "a" * 64,
        target_path=target,
        target_identity=tuple(tombstone["retired_target_identity"]),
        owns_target=True,
        target_owner_journal_path=old_path,
        target_owner_journal_identity=tuple(
            tombstone["initial_owner_journal_identity"]
        ),
        target_owner_journal_sha256=str(
            tombstone["initial_owner_journal_sha256"]
        ),
        planned_journal_path=old_path,
        planned_journal_size=1,
        planned_journal_sha256=str(tombstone["initial_owner_journal_sha256"]),
        candidate_path=None,
        candidate_parent_identity=None,
        candidate_identity=None,
    )
    retention_path = runtime_installer._runtime_attempt_retention_path(
        runtime_root, old_id
    )
    retention_path.parent.mkdir(parents=True, exist_ok=True)
    retention_path.write_bytes(retention_raw)

    recovered = runtime_installer.recover_runtime_attempt(
        runtime_root,
        transaction_id=old_id,
        expected_retention_owner_run_id=retention_owner,
        expected_package_root_sha256="sha256:" + "a" * 64,
        expected_deck_name="ShadowPriest",
    )

    assert recovered.status == "committed_receipt_pending"
    assert recovered.retained_attempt_record_path == retention_path
    assert recovered.target_owner_journal_path == old_path

    tombstone_path.write_bytes(b"{}\n")
    with pytest.raises(ValueError, match="owner_retirement.*(tombstone|fallback)"):
        runtime_installer.recover_runtime_attempt(
            runtime_root,
            transaction_id=old_id,
            expected_retention_owner_run_id=retention_owner,
            expected_package_root_sha256="sha256:" + "a" * 64,
            expected_deck_name="ShadowPriest",
        )


def _attempt_retention_hard_exit_worker(
    path: Path,
    payload: bytes,
    written_size: int,
) -> None:
    descriptor = os.open(path, os.O_CREAT | os.O_EXCL | os.O_WRONLY, 0o600)
    try:
        written = os.write(descriptor, payload[:written_size])
        if written != written_size:
            os._exit(78)
        os.fsync(descriptor)
    finally:
        os.close(descriptor)
    os._exit(77)


def _create_ntfs_stream_or_skip(path: Path) -> Path:
    if os.name != "nt":
        pytest.skip("NTFS alternate data streams are Windows-specific")
    stream = Path(f"{path}:task9-review")
    try:
        stream.write_bytes(b"foreign-stream")
    except OSError as error:
        pytest.skip(f"test volume does not support NTFS ADS: {error}")
    return stream


def build_rendered_run(root: Path, revision: int) -> RenderedConfigureRun:
    package = assemble_package(compile_package(audited_request(root, "ShadowPriest")))
    return render_configure_run_model(
        create_configure_run_model(
            package=package,
            stage_artifacts={
                "01_manifest/input.json": (f'{{"revision":{revision}}}\n'.encode()),
                "02_source_documents/source.json": b'{"stage":2}\n',
                "03_research/research.json": b'{"stage":3}\n',
            },
        )
    )


def publish_fixture(
    tmp_path: Path,
    *,
    revision: int = 1,
) -> tuple[PublishedOutput, Path, RenderedConfigureRun]:
    rendered = build_rendered_run(tmp_path / f"source-{revision}", revision)
    output_root = tmp_path / "published"
    published = publish_configure_run(rendered, output_root)
    runtime_root = tmp_path / "runtime"
    runtime_root.mkdir()
    return published, runtime_root, rendered


def _seed_prior_owner_runtime(
    *, pipeline: SimpleNamespace, published: PublishedOutput
) -> None:
    seeded_plan = plan_runtime_install(
        published_output=published,
        runtime_root=pipeline.runtime_root,
    )
    logical_name, expected_files, package_digest = expected_runtime_entries(
        published
    )
    assert logical_name == seeded_plan.logical_config_dir
    target = (
        pipeline.runtime_root
        / "CustomConfig"
        / seeded_plan.versioned_config_dir
    )
    target.parent.mkdir(parents=True, exist_ok=True)
    target.mkdir()
    for relative, raw in expected_files.items():
        destination = target / relative
        destination.parent.mkdir(parents=True, exist_ok=True)
        destination.write_bytes(raw)
    ini_path = target.parent / "deck_config.ini"
    ini_path.write_bytes(
        runtime_installer.render_deck_config(
            seeded_plan.ini_snapshot,
            deck_name=seeded_plan.deck_name,
            config_dir=seeded_plan.versioned_config_dir,
        )
    )
    owner_id = "b" * 32
    owner = RuntimeTransactionJournal(
        schema_version=1,
        transaction_id=owner_id,
        deck_name=seeded_plan.deck_name,
        source_manifest_sha256=runtime_installer._source_manifest_sha256(
            seeded_plan
        ),
        state_key=runtime_installer._state_key(seeded_plan.deck_name),
        logical_config_dir=seeded_plan.logical_config_dir,
        package_root_sha256=package_digest,
        candidate_path=f".hsconfig/staging/{owner_id}",
        target_path=f"CustomConfig/{seeded_plan.versioned_config_dir}",
        candidate_identity=path_identity(target),
        target_identity=path_identity(target),
        owns_target=True,
        previous_config_dir=None,
        next_config_dir=seeded_plan.versioned_config_dir,
        previous_ini_sha256=None,
        next_ini_sha256=hashlib.sha256(ini_path.read_bytes()).hexdigest(),
        phase=RuntimeTransactionPhase.FINALIZED,
    )
    owner_path = runtime_transaction_journal_path(
        pipeline.runtime_root, owner_id
    )
    owner_path.parent.mkdir(parents=True, exist_ok=True)
    write_runtime_transaction_journal(owner_path, owner)


def _seed_stale_owned_revision_runtime(
    *, pipeline: SimpleNamespace, published: PublishedOutput
) -> None:
    """Install one distinct, finalized old target as the active INI owner."""

    plan = plan_runtime_install(
        published_output=published,
        runtime_root=pipeline.runtime_root,
    )
    custom_config = pipeline.runtime_root / "CustomConfig"
    custom_config.mkdir(parents=True, exist_ok=True)
    provisional = custom_config / "stale-provisional"
    provisional.mkdir()
    (provisional / "stale-config.json").write_bytes(b'{"stale":true}\n')
    package_digest = runtime_installer._owner_retirement_package_digest(
        runtime_installer._collect_owner_retirement_cleanup_entries(provisional)
    )
    target = custom_config / f"{plan.logical_config_dir}--sha256-{package_digest}"
    provisional.rename(target)
    target_identity = path_identity(target)
    ini_path = custom_config / "deck_config.ini"
    ini_path.write_bytes(
        runtime_installer.render_deck_config(
            plan.ini_snapshot,
            deck_name=plan.deck_name,
            config_dir=target.name,
        )
    )
    owner_id = "c" * 32
    owner = RuntimeTransactionJournal(
        schema_version=1,
        transaction_id=owner_id,
        deck_name=plan.deck_name,
        source_manifest_sha256=runtime_installer._source_manifest_sha256(plan),
        state_key=runtime_installer._state_key(plan.deck_name),
        logical_config_dir=plan.logical_config_dir,
        package_root_sha256=package_digest,
        candidate_path=f".hsconfig/staging/{owner_id}",
        target_path=target.relative_to(pipeline.runtime_root).as_posix(),
        candidate_identity=target_identity,
        target_identity=target_identity,
        owns_target=True,
        previous_config_dir=None,
        next_config_dir=target.name,
        previous_ini_sha256=None,
        next_ini_sha256=hashlib.sha256(ini_path.read_bytes()).hexdigest(),
        phase=RuntimeTransactionPhase.FINALIZED,
    )
    owner_path = runtime_transaction_journal_path(
        pipeline.runtime_root, owner_id
    )
    owner_path.parent.mkdir(parents=True, exist_ok=True)
    write_runtime_transaction_journal(owner_path, owner)


@contextmanager
def _controller_pair_capabilities(
    tmp_path: Path,
    monkeypatch: pytest.MonkeyPatch,
    *,
    seed_prior_owner: bool = False,
    seed_stale_owned_revision: bool = False,
    prepared_pipeline: SimpleNamespace | None = None,
    apply_attempt_id: str = "a" * 32,
    existing_child_precondition: bool = False,
) -> Iterator[SimpleNamespace]:
    import hsconfig.live_start_session as live_start_session
    from hsconfig.current_output import lease_package_input
    from hsconfig.operator_profile import (
        lease_operator_profile,
        load_operator_profile,
    )
    from hsconfig.output_operation_admission import (
        lease_output_operation_admission,
        observe_output_operation_admission_under_lease,
    )
    from hsconfig.runtime_live_admission import (
        build_runtime_live_attempt_admission_bytes,
    )
    from hsconfig.apply_invocation import (
        build_apply_invocation,
        capture_pre_apply_runtime_snapshot,
    )
    from tests.test_configure_prepublication_apply import (
        _drive_pipeline,
        _prepare_pipeline,
    )

    pipeline = (
        _prepare_pipeline(
            tmp_path / "pipeline",
            monkeypatch,
            existing_child_precondition=existing_child_precondition,
        )
        if prepared_pipeline is None
        else prepared_pipeline
    )
    committed = _drive_pipeline(pipeline)
    operation = committed.output_operation_admission_binding
    child = committed.output_child_binding
    publication = committed.publication_binding
    assert operation is not None
    assert child is not None
    assert publication is not None
    state_root = pipeline.local_app_data / "HSConfig"
    with lease_package_input(Path(str(child["output_child_path"]))) as seed_lease:
        seed_publication = seed_lease.publication
        assert seed_publication is not None
        seed_published = PublishedOutput(
            output_root=seed_lease.output_root,
            revision_root=seed_lease.package_root.parent,
            package_root=seed_lease.package_root,
            content_root_sha256=seed_publication.content_root_sha256,
            reused_existing_revision=True,
        )
        if seed_prior_owner:
            _seed_prior_owner_runtime(
                pipeline=pipeline,
                published=seed_published,
            )
        if seed_stale_owned_revision:
            _seed_stale_owned_revision_runtime(
                pipeline=pipeline,
                published=seed_published,
            )
    snapshot_profile = load_operator_profile()
    with lease_operator_profile(
        expected_profile=snapshot_profile
    ) as snapshot_profile_lease:
        snapshot = capture_pre_apply_runtime_snapshot(
            runtime_root=pipeline.runtime_root,
            expected_runtime_root_identity=path_identity(pipeline.runtime_root),
            deck_name="ShadowPriest",
            state_key=runtime_installer._state_key("ShadowPriest"),
            profile_lease=snapshot_profile_lease,
        )
    invocation = build_apply_invocation(
        apply_attempt_id=apply_attempt_id,
        run_id=committed.run_id,
        pre_apply_runtime_snapshot=snapshot,
        runtime_root=pipeline.runtime_root,
        runtime_root_identity=path_identity(pipeline.runtime_root),
        output_operation_admission_path=Path(str(operation["admission_path"])),
        output_operation_admission_identity=tuple(operation["admission_identity"]),
        output_operation_admission_sha256=str(operation["admission_sha256"]),
        output_child_binding_sha256=str(child["content_sha256"]),
        output_child_path=Path(str(child["output_child_path"])),
        output_child_identity=tuple(child["output_child_identity"]),
        operator_profile_sha256=pipeline.profile.content_sha256,
        publication_revision=str(publication["revision"]),
        publication_content_root_sha256=str(publication["content_root_sha256"]),
    )
    admission_path = state_root / "live-start-active-attempt.json"
    admission_staging = state_root / (
        ".live-start-active-attempt."
        f"{committed.run_id}.{invocation.apply_attempt_id}.staged"
    )
    admission_inner = admission_staging.with_name(
        f".{admission_staging.name}.live-start-atomic.tmp"
    )
    admission_raw = build_runtime_live_attempt_admission_bytes(
        run_id=committed.run_id,
        apply_attempt_id=invocation.apply_attempt_id,
        retention_owner_run_id=committed.run_id,
        session_root=pipeline.session_root,
        session_root_identity=path_identity(pipeline.session_root),
        operator_profile_sha256=pipeline.profile.content_sha256,
        state_root_identity=path_identity(state_root),
        runtime_root=pipeline.runtime_root,
        runtime_root_identity=path_identity(pipeline.runtime_root),
        output_base_root=pipeline.profile.output_base_root,
        output_base_root_identity=(
            pipeline.profile.output_base_root_identity
        ),
        output_root=Path(str(child["output_child_path"])),
        output_root_identity=tuple(child["output_child_identity"]),
        output_operation_admission_path=Path(
            str(operation["admission_path"])
        ),
        output_operation_admission_identity=tuple(
            operation["admission_identity"]
        ),
        output_operation_admission_sha256=str(
            operation["admission_sha256"]
        ),
        output_child_binding_sha256=str(child["content_sha256"]),
        publication_revision=str(publication["revision"]),
        publication_content_root_sha256=str(
            publication["content_root_sha256"]
        ),
        package_root_sha256=str(publication["content_root_sha256"]),
        pre_apply_runtime_snapshot_sha256=(
            invocation.pre_apply_runtime_snapshot.content_sha256
        ),
        apply_invocation_sha256=invocation.content_sha256,
        retention_fence_path=(
            pipeline.runtime_root
            / ".hsconfig"
            / "attempt-retention"
            / f"{invocation.apply_attempt_id}.json"
        ),
    )
    admission_sha256 = "sha256:" + hashlib.sha256(admission_raw).hexdigest()
    session_context = live_start_session.lease_live_start_session(
        pipeline.session_root,
        local_app_data_root=pipeline.local_app_data,
    )
    with session_context as session_lease:
        current = live_start_session.load_live_start_session_under_lock(
            session_lease=session_lease
        )
        assert current.canonical_json == committed.canonical_json
        prepared_session = live_start_session.prepare_apply_attempt_under_lock(
            session_lease=session_lease,
            expected_session=current,
            invocation=invocation,
            planned_admission_path=admission_path,
            planned_admission_staging_path=admission_staging,
            planned_admission_staging_inner_temp_path=admission_inner,
            planned_admission_parent_identity=path_identity(state_root),
            planned_admission_document_size=len(admission_raw),
            planned_admission_document_sha256=admission_sha256,
        )
        profile = load_operator_profile()
        profile_context = lease_operator_profile(expected_profile=profile)
        with profile_context as profile_lease:
            operation_context = lease_output_operation_admission()
            with operation_context as operation_lease:
                operation_evidence = observe_output_operation_admission_under_lease(
                    operation_lease
                )
                assert operation_evidence is not None
                package_context = lease_package_input(
                    Path(str(child["output_child_path"]))
                )
                with package_context as package_lease:
                    yield SimpleNamespace(
                        pipeline=pipeline,
                        invocation=invocation,
                        prepared_session=prepared_session,
                        session_lease=session_lease,
                        profile_lease=profile_lease,
                        operation_lease=operation_lease,
                        operation_evidence=operation_evidence,
                        package_lease=package_lease,
                        state_root=state_root,
                        admission_path=admission_path,
                        admission_staging_path=admission_staging,
                        admission_inner_temp_path=admission_inner,
                        admission_raw=admission_raw,
                        admission_sha256=admission_sha256,
                        session_context=session_context,
                        profile_context=profile_context,
                        operation_context=operation_context,
                        package_context=package_context,
                    )


def _pair_arguments(
    capabilities: SimpleNamespace,
    *,
    expected_session: object | None = None,
    runtime_admission: object | None = None,
) -> dict[str, Any]:
    return {
        "package_lease": capabilities.package_lease,
        "session_lease": capabilities.session_lease,
        "expected_session": (
            capabilities.prepared_session
            if expected_session is None
            else expected_session
        ),
        "profile_lease": capabilities.profile_lease,
        "output_operation_lease": capabilities.operation_lease,
        "output_operation_admission": capabilities.operation_evidence,
        "runtime_admission": runtime_admission,
        "runtime_root": capabilities.pipeline.runtime_root,
        "expected_root_identity": path_identity(capabilities.pipeline.runtime_root),
    }


