        runtime_internal=capabilities.pipeline.runtime_root / ".hsconfig",
        apply_lock=(
            capabilities.pipeline.runtime_root / ".hsconfig" / "apply.lock"
        ),
        state_root=capabilities.state_root,
        local_app_data=capabilities.pipeline.local_app_data,
        output_base_root=capabilities.profile_lease.profile.output_base_root,
        output_root=capabilities.operation_evidence.output_child_path,
        output_operation_path=capabilities.operation_evidence.admission_path,
        admission_path=capabilities.admission_path,
        admission_staging_path=capabilities.admission_staging_path,
        admission_inner_temp_path=capabilities.admission_inner_temp_path,
        admission_raw=capabilities.admission_raw,
