def _legacy_runtime_gate_layout(
    tmp_path: Path,
    monkeypatch: pytest.MonkeyPatch,
) -> SimpleNamespace:
    from hsconfig.output_operation_admission import (
        output_operation_admission_path,
        output_operation_admission_reserved_temp_path,
        output_operation_admission_staging_path,
    )
    from tests.test_output_operation_admission import (
        _admission_document,
        _enabled_layout,
    )

    local_app_data, runtime_root, output_base_root, profile = _enabled_layout(
        tmp_path,
        monkeypatch,
    )
    operation_document, operation_raw = _admission_document(
        local_app_data=local_app_data,
        output_base_root=output_base_root,
        profile=profile,
    )
    return SimpleNamespace(
        local_app_data=local_app_data,
        state_root=local_app_data / "HSConfig",
        runtime_root=runtime_root,
        output_base_root=output_base_root,
        output_root=Path(str(operation_document["output_child_path"])),
        profile=profile,
        operation_document=operation_document,
        operation_raw=operation_raw,
        operation_path=output_operation_admission_path(),
        operation_staging_path=output_operation_admission_staging_path(),
        operation_temp_path=output_operation_admission_reserved_temp_path(),
    )


def _clear_output_operation_surfaces(layout: SimpleNamespace) -> None:
    for path in (
        layout.operation_path,
        layout.operation_staging_path,
        layout.operation_temp_path,
    ):
        Path(path).unlink(missing_ok=True)


def _set_output_operation_surface(
    layout: SimpleNamespace,
    state: str,
) -> None:
    _clear_output_operation_surfaces(layout)
    if state == "valid":
        layout.operation_path.write_bytes(layout.operation_raw)
    elif state == "replaced":
        layout.operation_path.write_bytes(layout.operation_raw)
        old_identity = path_identity(layout.operation_path)
        layout.operation_path.unlink()
        layout.operation_path.write_bytes(layout.operation_raw)
        assert path_identity(layout.operation_path) != old_identity
    elif state == "malformed":
        layout.operation_path.write_bytes(b'{"malformed":true}\n')
    elif state == "staging":
        layout.operation_staging_path.write_bytes(b"unbound staging\n")
    elif state == "reserved_temp":
        layout.operation_temp_path.write_bytes(b"reserved temp\n")
    elif state != "absent":
        raise AssertionError(state)


def _build_runtime_admission_raw(
    *,
    tmp_path: Path,
    state_root: Path,
    runtime_root: Path,
    output_root: Path,
    run_id: str,
    apply_attempt_id: str,
) -> bytes:
    from hsconfig.runtime_live_admission import (
        build_runtime_live_attempt_admission_bytes,
    )

    session_root = tmp_path / f"session-{run_id}"
    session_root.mkdir(parents=True, exist_ok=True)
    output_base_root = output_root.parent
    output_base_root.mkdir(parents=True, exist_ok=True)
    output_root.mkdir(parents=True, exist_ok=True)
    operation_path = state_root / "output-operation-admission.json"
    operation_path.write_bytes(f"historical:{run_id}\n".encode())
    operation_identity = path_identity(operation_path)
    raw = build_runtime_live_attempt_admission_bytes(
        run_id=run_id,
        apply_attempt_id=apply_attempt_id,
        retention_owner_run_id=run_id,
        session_root=session_root,
        session_root_identity=path_identity(session_root),
        operator_profile_sha256="sha256:" + "1" * 64,
        state_root_identity=path_identity(state_root),
        runtime_root=runtime_root,
        runtime_root_identity=path_identity(runtime_root),
        output_base_root=output_base_root,
        output_base_root_identity=path_identity(output_base_root),
        output_root=output_root,
        output_root_identity=path_identity(output_root),
        output_operation_admission_path=operation_path,
        output_operation_admission_identity=operation_identity,
        output_operation_admission_sha256="sha256:" + "2" * 64,
        output_child_binding_sha256="sha256:" + "3" * 64,
        publication_revision="revisions/sha256-" + "4" * 64,
        publication_content_root_sha256="sha256:" + "4" * 64,
        package_root_sha256="sha256:" + "5" * 64,
        pre_apply_runtime_snapshot_sha256="sha256:" + "6" * 64,
        apply_invocation_sha256="sha256:" + "7" * 64,
        retention_fence_path=(
            runtime_root
            / ".hsconfig"
            / "attempt-retention"
            / f"{apply_attempt_id}.json"
        ),
    )
    operation_path.unlink()
    return raw


def _set_runtime_admission_surface(
    state_root: Path,
    raw: bytes,
    state: str,
) -> Path:
    final = state_root / "live-start-active-attempt.json"
    final.unlink(missing_ok=True)
    if state == "valid":
        final.write_bytes(raw)
    elif state == "replaced":
        final.write_bytes(raw)
        old_identity = path_identity(final)
        final.unlink()
        final.write_bytes(raw)
        assert path_identity(final) != old_identity
    elif state == "malformed":
        final.write_bytes(b'{"malformed":true}\n')
    elif state != "absent":
        raise AssertionError(state)
    return final


def _trace_runtime_semantic_mutators(
    monkeypatch: pytest.MonkeyPatch,
) -> list[str]:
    calls: list[str] = []

    def traced(name: str, implementation: Any) -> Any:
        def invoke(*args: object, **kwargs: object) -> object:
            calls.append(name)
            return implementation(*args, **kwargs)

        return invoke

    for name in (
        "_create_or_confirm_runtime_metadata",
        "_ensure_runtime_layout",
        "_recover_locked",
        "_install_locked",
        "_write_journal",
    ):
        implementation = getattr(runtime_installer, name)
        monkeypatch.setattr(
            runtime_installer,
            name,
            traced(name, implementation),
        )
    return calls


def test_different_attempt_is_rejected_by_admission_before_fence_journal_or_runtime_write(
    tmp_path: Path,
    monkeypatch: pytest.MonkeyPatch,
) -> None:
    fixture = _public_runtime_plan_fixture(tmp_path, monkeypatch)
    active_attempt_id = "a" * 32
    requested_attempt_id = "b" * 32
    admission_raw = _build_runtime_admission_raw(
        tmp_path=tmp_path,
        state_root=fixture.state_root,
        runtime_root=fixture.runtime_root,
        output_root=fixture.output_root,
        run_id="c" * 32,
        apply_attempt_id=active_attempt_id,
    )
    admission_path = _set_runtime_admission_surface(
        fixture.state_root,
        admission_raw,
        "valid",
    )
    before = {
        "state": _filesystem_surface_evidence(fixture.state_root),
        "runtime": _filesystem_surface_evidence(fixture.runtime_root),
        "output": _filesystem_surface_evidence(fixture.output_root),
    }
    semantic_calls = _trace_runtime_semantic_mutators(monkeypatch)

    with pytest.raises(ValueError, match="runtime_live_admission"):
        install_runtime_package(
            fixture.plan,
            transaction_id=requested_attempt_id,
        )

    assert semantic_calls == []
    assert admission_path.read_bytes() == admission_raw
    assert {
        "state": _filesystem_surface_evidence(fixture.state_root),
        "runtime": _filesystem_surface_evidence(fixture.runtime_root),
        "output": _filesystem_surface_evidence(fixture.output_root),
    } == before
    assert not (
        fixture.runtime_root
        / ".hsconfig"
        / "attempt-retention"
        / f"{active_attempt_id}.json"
    ).exists()
    assert not (
        fixture.runtime_root
        / ".hsconfig"
        / "transactions"
        / f"{requested_attempt_id}.json"
    ).exists()
    assert not (fixture.runtime_root / ".hsconfig").exists()


