def test_legacy_runtime_lock_order_is_output_operation_then_runtime(
    tmp_path: Path,
    monkeypatch: pytest.MonkeyPatch,
) -> None:
    layout = _legacy_runtime_gate_layout(tmp_path, monkeypatch)
    _clear_output_operation_surfaces(layout)
    _set_runtime_admission_surface(layout.state_root, b"", "absent")
    events: list[str] = []
    real_output_lease = runtime_installer.lease_output_operation_admission
    real_runtime_lease = runtime_installer._lease_runtime_apply_after_gates

    @contextmanager
    def trace_output_lease() -> Iterator[object]:
        events.append("output_enter")
        with real_output_lease() as lease:
            events.append("output_held")
            try:
                yield lease
            finally:
                events.append("output_releasing")
        events.append("output_exit")

    @contextmanager
    def trace_runtime_lease(**kwargs: object) -> Iterator[object]:
        events.append("runtime_enter")
        with real_runtime_lease(**kwargs) as lease:
            events.append("runtime_held")
            try:
                yield lease
            finally:
                events.append("runtime_releasing")
        events.append("runtime_exit")

    monkeypatch.setattr(
        runtime_installer,
        "lease_output_operation_admission",
        trace_output_lease,
    )
    monkeypatch.setattr(
        runtime_installer,
        "_lease_runtime_apply_after_gates",
        trace_runtime_lease,
    )

    assert recover_runtime_state(layout.runtime_root) is None
    assert events == [
        "output_enter",
        "output_held",
        "runtime_enter",
        "runtime_held",
        "runtime_releasing",
        "runtime_exit",
        "output_releasing",
        "output_exit",
    ]


