def test_public_installer_never_acquires_output_operation_while_holding_package(
    tmp_path: Path,
    monkeypatch: pytest.MonkeyPatch,
) -> None:
    fixture = _public_runtime_plan_fixture(tmp_path, monkeypatch)
    depths = {"output": 0, "package": 0}
    entries: list[str] = []
    real_output_lease = runtime_installer.lease_output_operation_admission
    real_package_lease = runtime_installer.lease_package_input

    @contextmanager
    def trace_output_lease() -> Iterator[object]:
        entries.append("output")
        assert depths["package"] == 0
        with real_output_lease() as lease:
            depths["output"] += 1
            try:
                assert depths == {"output": 1, "package": 0}
                yield lease
            finally:
                assert depths["package"] == 0
                depths["output"] -= 1

    @contextmanager
    def trace_package_lease(package_input: Path) -> Iterator[object]:
        entries.append("package")
        assert depths == {"output": 1, "package": 0}
        with real_package_lease(package_input) as lease:
            depths["package"] += 1
            try:
                yield lease
            finally:
                depths["package"] -= 1

    monkeypatch.setattr(
        runtime_installer,
        "lease_output_operation_admission",
        trace_output_lease,
    )
    monkeypatch.setattr(
        runtime_installer,
        "lease_package_input",
        trace_package_lease,
    )

    result = install_runtime_package(
        fixture.plan,
        transaction_id="f" * 32,
    )

    assert result.status == "applied"
    assert entries == ["output", "package"]
    assert depths == {"output": 0, "package": 0}


def test_already_gated_runtime_helper_never_reacquires_output_operation(
    tmp_path: Path,
    monkeypatch: pytest.MonkeyPatch,
) -> None:
    layout = _legacy_runtime_gate_layout(tmp_path, monkeypatch)
    _clear_output_operation_surfaces(layout)
    _set_runtime_admission_surface(layout.state_root, b"", "absent")
    real_output_lease = runtime_installer.lease_output_operation_admission
    nested_entries: list[str] = []

    @contextmanager
    def trace_nested_output_lease() -> Iterator[object]:
        nested_entries.append("nested_output")
        with real_output_lease() as lease:
            yield lease

    with real_output_lease() as operation_lease:
        monkeypatch.setattr(
            runtime_installer,
            "lease_output_operation_admission",
            trace_nested_output_lease,
        )
        with runtime_installer._lease_runtime_apply_under_output_operation(
            output_operation_lease=operation_lease,
            runtime_root=layout.runtime_root,
            expected_root_identity=path_identity(layout.runtime_root),
        ) as runtime_lease:
            runtime_installer._require_active_runtime_apply_lease(runtime_lease)
        runtime_installer.require_output_operation_allows_runtime_mutation(
            lease=operation_lease
        )

    assert nested_entries == []


