def test_existing_exact_transaction_requires_recovery_without_install(
    tmp_path: Path,
    monkeypatch: pytest.MonkeyPatch,
) -> None:
    published, runtime_root, _rendered = publish_fixture(tmp_path)
    plan = plan_runtime_install(
        published_output=published,
        runtime_root=runtime_root,
    )
    transaction_id = "b" * 32
    install_runtime_package(plan, transaction_id=transaction_id)
    before = {
        path.relative_to(runtime_root).as_posix(): (
            None if path.is_dir() else path.read_bytes()
        )
        for path in runtime_root.rglob("*")
    }
    recovery_calls: list[Path] = []

    def unexpected_recovery(root: Path) -> runtime_installer._RecoveryOutcome:
        recovery_calls.append(root)
        raise AssertionError("existing caller-owned attempt was recovered implicitly")

    monkeypatch.setattr(runtime_installer, "_recover_locked", unexpected_recovery)

    with pytest.raises(
        RuntimeError,
        match="runtime_transaction_recovery_required",
    ) as caught:
        install_runtime_package(plan, transaction_id=transaction_id)

    assert type(caught.value) is runtime_installer.RuntimeInstallRecoveryRequiredError
    assert recovery_calls == []
    assert {
        path.relative_to(runtime_root).as_posix(): (
            None if path.is_dir() else path.read_bytes()
        )
        for path in runtime_root.rglob("*")
    } == before


def _write_task9_attempt_retention(
    runtime_root: Path,
    *,
    transaction_id: str,
    retention_owner_run_id: str,
    state: str,
    journal: RuntimeTransactionJournal | None = None,
    journal_is_bound: bool = False,
    candidate: Path | None = None,
) -> tuple[Path, bytes]:
    retention_path = (
        runtime_root
        / ".hsconfig"
        / "attempt-retention"
        / f"{transaction_id}.json"
    )
    retention_path.parent.mkdir(parents=True, exist_ok=True)
    journal_path = runtime_transaction_journal_path(runtime_root, transaction_id)
    journal_raw = (
        runtime_installer.runtime_transaction_journal_bytes(journal)
        if journal is not None
        else None
    )
    journal_digest = (
        "sha256:" + hashlib.sha256(journal_raw).hexdigest()
        if journal_raw is not None
        else None
    )
    effective_candidate = candidate
    if effective_candidate is None and state.startswith("CANDIDATE_"):
        effective_candidate = (
            runtime_root / ".hsconfig" / "staging" / transaction_id
        )
    raw = runtime_installer.build_runtime_attempt_retention_bytes(
        runtime_root=runtime_root,
        state=state,
        apply_attempt_id=transaction_id,
        retention_owner_run_id=retention_owner_run_id,
        journal_path=(journal_path if journal_is_bound else None),
        journal_identity=(
            path_identity(journal_path) if journal_is_bound else None
        ),
        journal_sha256=(journal_digest if journal_is_bound else None),
        package_root_sha256=(
            "sha256:" + journal.package_root_sha256
            if journal is not None
            else None
        ),
        target_path=None,
        target_identity=None,
        owns_target=(False if journal is not None else None),
        target_owner_journal_path=None,
        target_owner_journal_identity=None,
        target_owner_journal_sha256=None,
        planned_journal_path=(journal_path if journal is not None else None),
        planned_journal_size=(len(journal_raw) if journal_raw is not None else None),
        planned_journal_sha256=journal_digest,
        candidate_path=effective_candidate,
        candidate_parent_identity=(
            path_identity(effective_candidate.parent)
            if effective_candidate is not None
            else None
        ),
        candidate_identity=(
            path_identity(effective_candidate)
            if effective_candidate is not None and journal_is_bound
            else None
        ),
    )
    retention_path.write_bytes(raw)
    return retention_path, raw


def _write_task9_finalized_retention(
    runtime_root: Path,
    *,
    transaction_id: str,
    retention_owner_run_id: str,
    journal: RuntimeTransactionJournal,
    target: Path,
    owner: RuntimeTransactionJournal,
) -> tuple[Path, bytes]:
    journal_path = runtime_transaction_journal_path(runtime_root, transaction_id)
    owner_path = runtime_transaction_journal_path(
        runtime_root,
        owner.transaction_id,
    )
    journal_raw = journal_path.read_bytes()
    owner_raw = owner_path.read_bytes()
    journal_sha256 = "sha256:" + hashlib.sha256(journal_raw).hexdigest()
    raw = runtime_installer.build_runtime_attempt_retention_bytes(
        runtime_root=runtime_root,
        state="FINALIZED",
        apply_attempt_id=transaction_id,
        retention_owner_run_id=retention_owner_run_id,
        journal_path=journal_path,
        journal_identity=path_identity(journal_path),
        journal_sha256=journal_sha256,
        package_root_sha256="sha256:" + journal.package_root_sha256,
        target_path=target,
        target_identity=path_identity(target),
        owns_target=journal.owns_target,
        target_owner_journal_path=owner_path,
        target_owner_journal_identity=path_identity(owner_path),
        target_owner_journal_sha256=(
            "sha256:" + hashlib.sha256(owner_raw).hexdigest()
        ),
        planned_journal_path=journal_path,
        planned_journal_size=len(journal_raw),
        planned_journal_sha256=journal_sha256,
        candidate_path=None,
        candidate_parent_identity=None,
        candidate_identity=None,
    )
    retention_path = (
        runtime_root
        / ".hsconfig"
        / "attempt-retention"
        / f"{transaction_id}.json"
    )
    retention_path.parent.mkdir(parents=True, exist_ok=True)
    retention_path.write_bytes(raw)
    return retention_path, raw


def _task9_finalized_journal(
    *,
    transaction_id: str,
    logical_config_dir: str,
    package_root_sha256: str,
    target_identity: tuple[int, int, int],
    owns_target: bool,
    previous_config_dir: str | None,
    next_ini_sha256: str,
) -> RuntimeTransactionJournal:
    next_config_dir = (
        f"{logical_config_dir}--sha256-{package_root_sha256}"
    )
    return RuntimeTransactionJournal(
        schema_version=1,
        transaction_id=transaction_id,
        deck_name="Deck",
        source_manifest_sha256="9" * 64,
        state_key=state_key_for_test("Deck"),
        logical_config_dir=logical_config_dir,
        package_root_sha256=package_root_sha256,
        candidate_path=f".hsconfig/staging/{transaction_id}",
        target_path=f"CustomConfig/{next_config_dir}",
        candidate_identity=(target_identity if owns_target else None),
        target_identity=target_identity,
        owns_target=owns_target,
        previous_config_dir=previous_config_dir,
        next_config_dir=next_config_dir,
        previous_ini_sha256=None,
        next_ini_sha256=next_ini_sha256,
        phase=RuntimeTransactionPhase.FINALIZED,
    )


def _seed_task9_protected_target(runtime_root: Path) -> SimpleNamespace:
    runtime_installer._ensure_runtime_layout(runtime_root)
    content = b'{"protected":true}\n'
    package_records = (
        f"Card.json\0{len(content)}\0{hashlib.sha256(content).hexdigest()}\n"
    ).encode("utf-8")
    package_root_sha256 = hashlib.sha256(package_records).hexdigest()
    target_name = f"Deck--sha256-{package_root_sha256}"
    target = runtime_root / "CustomConfig" / target_name
    target.mkdir()
    card = target / "Card.json"
    card.write_bytes(content)

    owner = _task9_finalized_journal(
        transaction_id="b" * 32,
        logical_config_dir="Deck",
        package_root_sha256=package_root_sha256,
        target_identity=path_identity(target),
        owns_target=True,
        previous_config_dir=None,
        next_ini_sha256="1" * 64,
    )
    controller = _task9_finalized_journal(
        transaction_id="c" * 32,
        logical_config_dir="Deck",
        package_root_sha256=package_root_sha256,
        target_identity=path_identity(target),
        owns_target=False,
        previous_config_dir=None,
        next_ini_sha256="1" * 64,
    )
    owner_path = runtime_transaction_journal_path(runtime_root, owner.transaction_id)
    controller_path = runtime_transaction_journal_path(
        runtime_root,
        controller.transaction_id,
    )
    write_runtime_transaction_journal(owner_path, owner)
    write_runtime_transaction_journal(controller_path, controller)
    retention_path, _retention_raw = _write_task9_finalized_retention(
        runtime_root,
        transaction_id=controller.transaction_id,
        retention_owner_run_id="d" * 32,
        journal=controller,
        target=target,
        owner=owner,
    )
    return SimpleNamespace(
        package_root_sha256=package_root_sha256,
        target_name=target_name,
        target=target,
        card=card,
        owner=owner,
        owner_path=owner_path,
        controller=controller,
        controller_path=controller_path,
        retention_path=retention_path,
    )


def _task9_protected_surface_snapshot(
    fixture: SimpleNamespace,
    *,
    extra_files: tuple[Path, ...] = (),
) -> dict[Path, tuple[tuple[int, int, int], bytes | None]]:
    paths = (
        fixture.target,
        fixture.card,
        fixture.owner_path,
        fixture.controller_path,
        fixture.retention_path,
        *extra_files,
    )
    return {
        path: (
            path_identity(path),
            None if path == fixture.target else path.read_bytes(),
        )
        for path in paths
    }


def test_recover_runtime_attempt_inspects_only_the_exact_transaction(
    tmp_path: Path,
    monkeypatch: pytest.MonkeyPatch,
) -> None:
    runtime_root = tmp_path / "runtime"
    runtime_root.mkdir()
    runtime_installer._ensure_runtime_layout(runtime_root)
    transaction_id = "7" * 32
    owner_run_id = "8" * 32
    retention_path, retention_raw = _write_task9_attempt_retention(
        runtime_root,
        transaction_id=transaction_id,
        retention_owner_run_id=owner_run_id,
        state="ACTIVE",
    )
    unrelated = runtime_transaction_journal_path(runtime_root, "9" * 32)
    unrelated.write_bytes(b'{"unrelated":"malformed"}\n')
    unrelated_retention = retention_path.with_name(f"{'9' * 32}.json")
    unrelated_retention.write_bytes(b'{"unrelated":"malformed"}\n')

    def forbidden_broad_recovery(*_args: object, **_kwargs: object) -> object:
        raise AssertionError("exact-attempt recovery entered broad recovery")

    def forbidden_uuid_generation() -> object:
        raise AssertionError("exact-attempt recovery generated an ID")

    monkeypatch.setattr(
        runtime_installer,
        "load_runtime_transaction_journals",
        forbidden_broad_recovery,
    )
    monkeypatch.setattr(runtime_installer, "_recover_locked", forbidden_broad_recovery)
    monkeypatch.setattr(
        runtime_installer,
        "uuid",
        SimpleNamespace(uuid4=forbidden_uuid_generation),
    )

    recovered = runtime_installer.recover_runtime_attempt(
        runtime_root,
        transaction_id=transaction_id,
        expected_retention_owner_run_id=owner_run_id,
        expected_package_root_sha256="sha256:" + "a" * 64,
        expected_deck_name="Deck",
    )

    assert recovered.status == "not_committed"
    assert recovered.transaction_id == transaction_id
    assert recovered.package_root_sha256 is None
    assert recovered.receipt_path is None
    assert recovered.retained_attempt_record_path == retention_path
    assert recovered.retained_attempt_record_identity == path_identity(retention_path)
    assert recovered.retained_attempt_record_sha256 == (
        "sha256:" + hashlib.sha256(retention_raw).hexdigest()
    )
    assert recovered.retained_journal_path is None
    assert recovered.target_owner_journal_path is None
    assert recovered.runtime_admission is None
    assert recovered.observation_family is None
    assert recovered.initial_apply_recovery_evidence is None
    assert recovered.initial_terminal_resolution_evidence is None
    assert recovered.runtime_observation_receipt is None
    assert recovered.apply_recovery_step_receipt is None
    assert recovered.terminal_resolution_step_receipt is None
    assert unrelated.read_bytes() == b'{"unrelated":"malformed"}\n'
    assert unrelated_retention.read_bytes() == b'{"unrelated":"malformed"}\n'


