def test_attempt_retention_reserved_temp_hard_kills_reconcile_before_enumeration(
    tmp_path: Path,
    monkeypatch: pytest.MonkeyPatch,
) -> None:
    real_loader = runtime_installer.load_runtime_transaction_journals
    for mode, written_size in (("partial", 17), ("full", None)):
        runtime_root = tmp_path / mode / "runtime"
        runtime_root.mkdir(parents=True)
        runtime_installer._ensure_runtime_layout(runtime_root)
        transaction_id = ("d" if mode == "partial" else "e") * 32
        journal = _unit_journal(transaction_id=transaction_id)
        journal_path = runtime_transaction_journal_path(runtime_root, transaction_id)
        write_runtime_transaction_journal(journal_path, journal)
        retention_path, retention_raw = _write_task9_attempt_retention(
            runtime_root,
            transaction_id=transaction_id,
            retention_owner_run_id="f" * 32,
            state="CANDIDATE_PLANNED",
            journal=journal,
        )
        staging = retention_path.with_name(f"{retention_path.name}.staged")
        staging.write_bytes(retention_raw)
        reserved = staging.with_name(
            f".{staging.name}.live-start-atomic.tmp"
        )
        receipt = runtime_root / ".hsconfig" / "receipts" / "sentinel.json"
        receipt.write_bytes(b"receipt\n")
        state = runtime_root / ".hsconfig" / "state.json"
        state.write_bytes(b"state\n")
        process = multiprocessing.get_context("spawn").Process(
            target=_attempt_retention_hard_exit_worker,
            args=(
                reserved,
                retention_raw,
                len(retention_raw) if written_size is None else written_size,
            ),
        )
        process.start()
        process.join(timeout=15)
        assert not process.is_alive()
        assert process.exitcode == 77
        assert reserved.is_file()
        before = {
            path: (path_identity(path), path.read_bytes())
            for path in (retention_path, staging, journal_path, receipt, state)
        }
        enumerated: list[Path] = []

        def guarded_loader(root: Path, **kwargs: object) -> object:
            assert not reserved.exists()
            enumerated.append(root)
            return real_loader(root, **kwargs)

        monkeypatch.setattr(
            runtime_installer,
            "load_runtime_transaction_journals",
            guarded_loader,
        )
        with pytest.raises(ValueError, match="retention_store_invalid"):
            runtime_installer._recover_locked(runtime_root)

        assert enumerated == []
        assert not reserved.exists()
        assert {
            path: (path_identity(path), path.read_bytes())
            for path in (retention_path, staging, journal_path, receipt, state)
        } == before


def test_broad_recovery_preservation_index_blocks_nested_old_revision_cleanup(
    tmp_path: Path,
    monkeypatch: pytest.MonkeyPatch,
) -> None:
    runtime_root = tmp_path / "runtime"
    runtime_root.mkdir()
    runtime_installer._ensure_runtime_layout(runtime_root)
    custom_config = runtime_root / "CustomConfig"

    old_digest = "b" * 64
    new_digest = "a" * 64
    old_name = f"Deck--sha256-{old_digest}"
    new_name = f"Deck--sha256-{new_digest}"
    old_target = custom_config / old_name
    new_target = custom_config / new_name
    old_target.mkdir()
    new_target.mkdir()
    old_card = old_target / "Card.json"
    old_card.write_bytes(b'{"protected":true}\n')

    old_owner = _task9_finalized_journal(
        transaction_id="b" * 32,
        logical_config_dir="Deck",
        package_root_sha256=old_digest,
        target_identity=path_identity(old_target),
        owns_target=True,
        previous_config_dir=None,
        next_ini_sha256="1" * 64,
    )
    controller_attempt = _task9_finalized_journal(
        transaction_id="c" * 32,
        logical_config_dir="Deck",
        package_root_sha256=old_digest,
        target_identity=path_identity(old_target),
        owns_target=False,
        previous_config_dir=None,
        next_ini_sha256="1" * 64,
    )
    current = _task9_finalized_journal(
        transaction_id="a" * 32,
        logical_config_dir="Deck",
        package_root_sha256=new_digest,
        target_identity=path_identity(new_target),
        owns_target=True,
        previous_config_dir=old_name,
        next_ini_sha256="2" * 64,
    )
    old_owner_path = runtime_transaction_journal_path(
        runtime_root,
        old_owner.transaction_id,
    )
    controller_path = runtime_transaction_journal_path(
        runtime_root,
        controller_attempt.transaction_id,
    )
    current_path = runtime_transaction_journal_path(
        runtime_root,
        current.transaction_id,
    )
    write_runtime_transaction_journal(old_owner_path, old_owner)
    write_runtime_transaction_journal(controller_path, controller_attempt)
    write_runtime_transaction_journal(current_path, current)
    retention_path, _retention_raw = _write_task9_finalized_retention(
        runtime_root,
        transaction_id=controller_attempt.transaction_id,
        retention_owner_run_id="d" * 32,
        journal=controller_attempt,
        target=old_target,
        owner=old_owner,
    )
    protected_files = (retention_path, controller_path, old_owner_path, old_card)
    before_files = {
        path: (path_identity(path), path.read_bytes()) for path in protected_files
    }
    old_target_identity = path_identity(old_target)

    selected_ini = runtime_installer.DeckConfigSnapshot(
        custom_config / "deck_config.ini",
        True,
        b"selected\n",
        current.next_ini_sha256,
        current.next_config_dir,
    )
    expected_receipt = runtime_installer._receipt_bytes(
        runtime_installer._receipt_payload(current, current.next_ini_sha256)
    )
    monkeypatch.setattr(
        runtime_installer,
        "read_deck_config",
        lambda *_args, **_kwargs: selected_ini,
    )
    monkeypatch.setattr(
        runtime_installer,
        "_verify_runtime_tree_digest",
        lambda *_args: None,
    )
    monkeypatch.setattr(runtime_installer, "read_runtime_state", lambda _root: None)
    monkeypatch.setattr(
        runtime_installer,
        "_write_selected_state",
        lambda *_args: None,
    )
    monkeypatch.setattr(
        runtime_installer,
        "_plain_file_bytes_or_none",
        lambda _path: expected_receipt,
    )
    monkeypatch.setattr(runtime_installer, "_active_config_dirs", lambda _root: set())
    monkeypatch.setattr(
        runtime_installer,
        "_verify_active_state_targets",
        lambda *_args: None,
    )

    runtime_installer._recover_locked(runtime_root)

    assert old_target.is_dir()
    assert path_identity(old_target) == old_target_identity
    assert all(path.exists() for path in protected_files)
    assert {
        path: (path_identity(path), path.read_bytes()) for path in protected_files
    } == before_files
    assert (
        runtime_installer.read_runtime_transaction_journal(old_owner_path).cleanup_started
        is False
    )


