def test_exact_retained_journal_observation_parses_the_identity_bound_read_once(
    tmp_path: Path,
    monkeypatch: pytest.MonkeyPatch,
) -> None:
    runtime_root = tmp_path / "runtime"
    transactions = runtime_root / ".hsconfig" / "transactions"
    transactions.mkdir(parents=True)
    transaction_id = "6" * 32
    first = _unit_journal(transaction_id=transaction_id)
    second = replace(first, source_manifest_sha256="d" * 64)
    journal_path = runtime_transaction_journal_path(runtime_root, transaction_id)
    write_runtime_transaction_journal(journal_path, first)
    first_raw = journal_path.read_bytes()
    first_identity = path_identity(journal_path)
    authority_reads: list[Path] = []
    real_reader = runtime_installer.read_runtime_transaction_journal

    def replace_then_read(path: Path) -> RuntimeTransactionJournal:
        authority_reads.append(path)
        write_runtime_transaction_journal(path, second)
        return real_reader(path)

    monkeypatch.setattr(
        runtime_installer,
        "read_runtime_transaction_journal",
        replace_then_read,
    )
    observed, identity, digest = runtime_installer._observe_retained_transaction(
        journal_path,
        expected_transaction_id=transaction_id,
        expected_identity=first_identity,
        expected_size=len(first_raw),
        expected_sha256="sha256:" + hashlib.sha256(first_raw).hexdigest(),
    )

    assert authority_reads == []
    assert observed == first
    assert identity == first_identity
    assert digest == "sha256:" + hashlib.sha256(first_raw).hexdigest()
    assert journal_path.read_bytes() == first_raw


