@pytest.mark.parametrize("surface", ("journal", "candidate", "target", "owner"))
def test_exact_recovery_rejects_ads_on_journal_candidate_target_or_owner(
    tmp_path: Path,
    surface: str,
) -> None:
    runtime_root = tmp_path / "runtime"
    runtime_root.mkdir()
    runtime_installer._ensure_runtime_layout(runtime_root)
    transaction_id = "9" * 32

    protected_files: list[Path]
    if surface in {"journal", "candidate"}:
        candidate = runtime_root / ".hsconfig" / "staging" / transaction_id
        if surface == "candidate":
            candidate.mkdir()
        journal = _unit_journal(
            transaction_id=transaction_id,
            candidate_identity=(
                path_identity(candidate) if surface == "candidate" else None
            ),
        )
        journal_path = runtime_transaction_journal_path(runtime_root, transaction_id)
