def _task9_runtime_handoff_fixture(
    tmp_path: Path,
) -> tuple[
    dict[str, object],
    dict[str, object],
    dict[str, object],
    dict[str, object],
    dict[str, object],
]:
    output_child = tmp_path / "output" / "ShadowPriest"
    operation = tmp_path / "state" / "output-operation-admission.json"
    output_child.mkdir(parents=True)
    operation.parent.mkdir(parents=True)
    operation_raw = b"operation\n"
    operation.write_bytes(operation_raw)

    def digest(value: str) -> str:
        return "sha256:" + value * 64

    operation_sha256 = "sha256:" + hashlib.sha256(operation_raw).hexdigest()
    invocation = {
        "output_operation_admission_path": operation,
        "output_operation_admission_identity": path_identity(operation),
        "output_operation_admission_sha256": operation_sha256,
        "output_child_binding_sha256": digest("2"),
        "output_child_path": output_child,
        "output_child_identity": path_identity(output_child),
        "publication_revision": "revisions/sha256-" + "3" * 64,
        "publication_content_root_sha256": digest("3"),
    }
    admission = dict(invocation)
    output_operation = {
        "admission_path": operation,
        "admission_identity": path_identity(operation),
        "admission_sha256": operation_sha256,
    }
    output_child_binding = {
        "content_sha256": digest("2"),
        "output_child_path": output_child,
        "output_child_identity": path_identity(output_child),
    }
    publication = {
        "revision": "revisions/sha256-" + "3" * 64,
        "content_root_sha256": digest("3"),
    }
    return (
        invocation,
        admission,
        output_operation,
        output_child_binding,
        publication,
    )


def test_same_attempt_journal_delta_rejects_fence_journal_or_pair_substitution(
    tmp_path: Path,
    monkeypatch: pytest.MonkeyPatch,
) -> None:
    from hsconfig.apply_invocation import require_same_attempt_pre_apply_snapshot

    with pytest.raises((TypeError, ValueError), match="pair"):
        runtime_installer.validate_same_attempt_journal_delta_from_pair(
            lease_pair=object(),
            runtime_admission=object(),
            apply_attempt_id="a" * 32,
            expected_attempt_record_path=tmp_path / "attempt.json",
            expected_attempt_record_identity=(1, 2, 3),
            expected_attempt_record_sha256="sha256:" + "4" * 64,
            expected_journal_path=tmp_path / "journal.json",
            expected_journal_identity=(4, 5, 6),
            expected_journal_sha256="sha256:" + "5" * 64,
            expected_journal_phase="PREPARED",
        )
    with _genuine_same_attempt_delta_fixture(
        tmp_path / "genuine", monkeypatch
    ) as fixture:
        for overrides, message in (
            (
                {
                    "expected_attempt_record_path": tmp_path
                    / "foreign-attempt.json"
                },
                "cursor_changed|path_changed",
            ),
            (
                {"expected_attempt_record_identity": (1, 2, 3)},
                "cursor_changed",
            ),
            (
                {
                    "expected_attempt_record_sha256": (
                        "sha256:" + "2" * 64
                    )
                },
                "cursor_changed",
            ),
            ({"expected_journal_identity": (1, 2, 3)}, "cursor_changed"),
            (
                {"expected_journal_sha256": "sha256:" + "1" * 64},
                "cursor_changed",
            ),
            (
                {"expected_journal_path": tmp_path / "foreign.json"},
                "cursor_changed|path_changed",
            ),
            ({"expected_journal_phase": "FINALIZED"}, "pair_changed"),
        ):
            with pytest.raises(ValueError, match=message):
                fixture.mint(**overrides)
        bearer = fixture.mint()
        require_same_attempt_pre_apply_snapshot(
            sealed=fixture.sealed,
            current=fixture.current,
            apply_attempt_id=fixture.apply_attempt_id,
            validated_delta=bearer,
        )


def test_runtime_admission_binds_exact_output_child_path_identity_and_binding_digest(
    tmp_path: Path,
) -> None:
    with pytest.raises(ValueError, match="handoff|output"):
        runtime_installer._validate_runtime_admission_handoff_bindings(
            invocation={},
            runtime_admission={},
            output_operation_admission={},
            output_child_binding={},
            publication_binding={},
        )
    invocation, admission, operation, child, publication = (
        _task9_runtime_handoff_fixture(tmp_path)
    )
    runtime_installer._validate_runtime_admission_handoff_bindings(
        invocation=invocation,
        runtime_admission=admission,
        output_operation_admission=operation,
        output_child_binding=child,
        publication_binding=publication,
        observe_filesystem=True,
    )
    for field in (
        "output_child_path",
        "output_child_identity",
        "output_child_binding_sha256",
    ):
        changed = dict(admission)
        changed[field] = (
            tmp_path
            if field.endswith("path")
            else ((9, 9, 9) if field.endswith("identity") else "sha256:" + "9" * 64)
        )
        with pytest.raises(ValueError, match="output_child"):
            runtime_installer._validate_runtime_admission_handoff_bindings(
                invocation=invocation,
                runtime_admission=changed,
                output_operation_admission=operation,
                output_child_binding=child,
                publication_binding=publication,
            )
    for field, value in (
        ("output_child_path", tmp_path / "invocation-other-child"),
        ("output_child_identity", (6, 6, 6)),
        ("output_child_binding_sha256", "sha256:" + "6" * 64),
    ):
        changed_invocation = dict(invocation)
        changed_invocation[field] = value
        with pytest.raises(ValueError, match="output_child"):
            runtime_installer._validate_runtime_admission_handoff_bindings(
                invocation=changed_invocation,
                runtime_admission=admission,
                output_operation_admission=operation,
                output_child_binding=child,
                publication_binding=publication,
            )
    for field, value in (
        ("output_child_path", tmp_path / "other-child"),
        ("output_child_identity", (7, 7, 7)),
        ("content_sha256", "sha256:" + "7" * 64),
    ):
        changed_child = dict(child)
        changed_child[field] = value
        with pytest.raises(ValueError, match="output_child"):
            runtime_installer._validate_runtime_admission_handoff_bindings(
                invocation=invocation,
                runtime_admission=admission,
                output_operation_admission=operation,
                output_child_binding=changed_child,
                publication_binding=publication,
            )


