def test_controller_pair_entry_rejects_forged_stale_cross_thread_or_wrong_cursor_before_runtime_bootstrap(
    tmp_path: Path,
    monkeypatch: pytest.MonkeyPatch,
) -> None:
    from queue import Queue
    from threading import Thread

    with _controller_pair_capabilities(tmp_path, monkeypatch) as capabilities:
        arguments = _pair_arguments(capabilities)
        runtime_root = capabilities.pipeline.runtime_root
        wrong_cursor = replace(
            capabilities.prepared_session,
            content_sha256="sha256:" + "0" * 64,
        )
        with pytest.raises(ValueError, match="session_cursor"):
            with runtime_installer.lease_controller_apply_pair(
                **{**arguments, "expected_session": wrong_cursor}
            ):
                raise AssertionError("wrong cursor yielded pair")
        assert not (runtime_root / ".hsconfig").exists()

        with pytest.raises(TypeError, match="not_constructible"):
            runtime_installer.ControllerApplyLeasePairToken()
        with runtime_installer.lease_controller_apply_pair(**arguments) as pair:
            forged_token = object.__new__(
                runtime_installer.ControllerApplyLeasePairToken
            )
            forged = runtime_installer.ControllerApplyLeasePair(
                package_lease=pair.package_lease,
                runtime_lease=pair.runtime_lease,
                pair_token=forged_token,
            )
            reconstructed = runtime_installer.ControllerApplyLeasePair(
                package_lease=pair.package_lease,
                runtime_lease=pair.runtime_lease,
                pair_token=pair.pair_token,
            )
            for candidate in (forged, reconstructed):
                with pytest.raises(ValueError, match="pair"):
                    runtime_installer._require_active_controller_apply_pair(candidate)

            result: Queue[BaseException | None] = Queue()

            def consume_cross_thread() -> None:
                try:
                    runtime_installer._require_active_controller_apply_pair(pair)
                except BaseException as error:  # pragma: no branch
                    result.put(error)
                else:  # pragma: no cover - security assertion
                    result.put(None)

            thread = Thread(target=consume_cross_thread)
            thread.start()
            thread.join(10)
            assert not thread.is_alive()
            cross_thread_error = result.get_nowait()
            assert isinstance(cross_thread_error, ValueError)
            assert "thread" in str(cross_thread_error)

        with pytest.raises(ValueError, match="inactive|forged"):
            runtime_installer._require_active_controller_apply_pair(pair)


