def test_controller_pair_rejects_in_place_mixed_active_leases(
    tmp_path: Path,
    monkeypatch: pytest.MonkeyPatch,
) -> None:
    from hsconfig.current_output import lease_package_input

    observer_calls: list[str] = []

    def forbidden_observer(*_args: object, **_kwargs: object) -> object:
        observer_calls.append("output_operation")
        raise AssertionError("mixed pair reached output-operation observer")

    with _controller_pair_capabilities(tmp_path, monkeypatch) as capabilities:
        with runtime_installer.lease_controller_apply_pair(
            **_pair_arguments(capabilities)
        ) as pair:
            original_package = pair.package_lease
            independent_package_root = tmp_path / "independent-package"
            independent_package_root.mkdir()
            with lease_package_input(independent_package_root) as mixed_package:
                object.__setattr__(pair, "package_lease", mixed_package)
                monkeypatch.setattr(
                    runtime_installer,
                    "observe_output_operation_admission_under_lease",
                    forbidden_observer,
                )
                try:
                    with pytest.raises(ValueError, match="pair|package"):
                        runtime_installer._require_active_controller_apply_pair(pair)
                finally:
                    object.__setattr__(pair, "package_lease", original_package)
                assert observer_calls == []

            mixed_runtime_root = tmp_path / "independent-runtime"
            mixed_runtime_root.mkdir()
            mixed_runtime_identity = path_identity(mixed_runtime_root)
            with runtime_installer._lease_runtime_apply_after_gates(
                runtime_root=mixed_runtime_root,
                expected_root_identity=mixed_runtime_identity,
                require_gates=lambda: None,
            ) as mixed_runtime:
                original_runtime = pair.runtime_lease
                before = tuple(
                    path.relative_to(mixed_runtime_root).as_posix()
                    for path in mixed_runtime_root.rglob("*")
                )
                object.__setattr__(pair, "runtime_lease", mixed_runtime)
                try:
                    with pytest.raises(ValueError, match="pair|runtime"):
                        runtime_installer._require_active_controller_apply_pair(pair)
                finally:
                    object.__setattr__(pair, "runtime_lease", original_runtime)
                assert observer_calls == []
                assert tuple(
                    path.relative_to(mixed_runtime_root).as_posix()
                    for path in mixed_runtime_root.rglob("*")
                ) == before


def test_controller_pair_rejects_expired_session_profile_or_output_operation_lease(
    tmp_path: Path,
    monkeypatch: pytest.MonkeyPatch,
) -> None:
    import hsconfig.live_start_session as live_start_session

    for expired_capability, context_name in (
        ("session", "session_context"),
        ("profile", "profile_context"),
        ("output_operation", "operation_context"),
    ):
        with _controller_pair_capabilities(
            tmp_path / expired_capability,
            monkeypatch,
        ) as capabilities:
            with runtime_installer.lease_controller_apply_pair(
                **_pair_arguments(capabilities)
            ) as pair:
                runtime_root = capabilities.pipeline.runtime_root
                before = tuple(
                    path.relative_to(runtime_root).as_posix()
                    for path in runtime_root.rglob("*")
                )
                context = getattr(capabilities, context_name)
                assert context.__exit__(None, None, None) is False

                runtime_observer_calls: list[str] = []

                def forbidden_runtime_observer(*_args: object, **_kwargs: object) -> object:
                    runtime_observer_calls.append(expired_capability)
                    raise AssertionError(
                        "expired outer lease reached Runtime observer"
                    )

                with monkeypatch.context() as action_patch:
                    action_patch.setattr(
                        runtime_installer,
                        "_require_active_runtime_apply_lease",
                        forbidden_runtime_observer,
                    )
                    with pytest.raises(
                        (live_start_session.SessionCapabilityError, ValueError)
                    ):
                        runtime_installer._require_active_controller_apply_pair(pair)
                assert runtime_observer_calls == []
                assert tuple(
                    path.relative_to(runtime_root).as_posix()
                    for path in runtime_root.rglob("*")
                ) == before


def test_controller_pair_token_accepts_only_persisted_same_lease_cursor_descendants(
    tmp_path: Path,
    monkeypatch: pytest.MonkeyPatch,
) -> None:
    import copy
    import pickle
    import hsconfig.live_start_session as live_start_session

    with _controller_pair_capabilities(tmp_path, monkeypatch) as capabilities:
        arguments = _pair_arguments(capabilities)
        with runtime_installer.lease_controller_apply_pair(**arguments) as pair:
            assert (
                runtime_installer._require_active_controller_apply_pair(
                    pair
                ).expected_session.canonical_json
                == capabilities.prepared_session.canonical_json
            )
            descendant = live_start_session.transition_live_start_session_under_lock(
                session_lease=capabilities.session_lease,
                expected_session=capabilities.prepared_session,
                event="same_phase_cas",
                changes={},
            )
            assert descendant.canonical_json == capabilities.prepared_session.canonical_json
            assert descendant.session_identity != (
                capabilities.prepared_session.session_identity
            )

            action_calls: list[tuple[int, int, int] | None] = []

            def validate_then_act(
                cursor: object,
                *,
                session_lease: object = capabilities.session_lease,
            ) -> object:
                binding = runtime_installer._require_controller_pair_session_cursor(
                    lease_pair=pair,
                    session_lease=session_lease,
                    expected_session=cursor,
                )
                action_calls.append(cursor.session_identity)
                return binding

            assert validate_then_act(descendant).pair is pair
            assert action_calls == [descendant.session_identity]
            assert runtime_installer._require_active_controller_apply_pair(pair).pair is pair

            current = live_start_session.transition_live_start_session_under_lock(
                session_lease=capabilities.session_lease,
                expected_session=descendant,
                event="same_phase_cas",
                changes={},
            )
            resealed = live_start_session._seal_session_value(
                current.to_value(),
                session_identity=None,
            )
            constructed = replace(
                current,
                content_sha256="sha256:" + "0" * 64,
            )
            wrong_lease = replace(capabilities.session_lease)
            for invalid_cursor, invalid_lease in (
                (capabilities.prepared_session, capabilities.session_lease),
                (descendant, capabilities.session_lease),
                (resealed, capabilities.session_lease),
                (constructed, capabilities.session_lease),
                (current, wrong_lease),
            ):
                before = list(action_calls)
                with pytest.raises((TypeError, ValueError), match="pair|session|cursor"):
                    validate_then_act(
                        invalid_cursor,
                        session_lease=invalid_lease,
                    )
                assert action_calls == before

            assert validate_then_act(current).pair is pair
            for operation in (copy.copy, copy.deepcopy, pickle.dumps):
                with pytest.raises(TypeError):
                    operation(pair.pair_token)
            reconstructed = runtime_installer.ControllerApplyLeasePair(
                package_lease=pair.package_lease,
                runtime_lease=pair.runtime_lease,
                pair_token=pair.pair_token,
            )
            with pytest.raises(ValueError, match="pair"):
                runtime_installer._require_active_controller_apply_pair(reconstructed)
        with pytest.raises(ValueError, match="inactive|forged"):
            runtime_installer._require_active_controller_apply_pair(pair)


def _replace_output_operation_with_foreign(
    fixture: SimpleNamespace,
    *,
    run_id: str = "f" * 32,
    expected_session_sha256: str = "sha256:" + "e" * 64,
) -> tuple[bytes, tuple[int, int, int]]:
    from hsconfig.operator_profile import load_operator_profile
    from hsconfig.output_operation_admission import (
        build_output_operation_admission_bytes,
    )

    historical = fixture.historical_output_operation
    profile = load_operator_profile()
    historical.admission_path.unlink()
    foreign_raw = build_output_operation_admission_bytes(
        run_id=run_id,
        session_root=historical.session_root,
        session_root_identity=historical.session_root_identity,
        expected_session_sha256=expected_session_sha256,
        operator_profile=profile,
        operator_profile_path=historical.operator_profile_path,
        operator_profile_parent_identity=(
            historical.operator_profile_parent_identity
        ),
        operator_profile_identity=historical.operator_profile_identity,
        state_root_identity=historical.state_root_identity,
        output_base_root=historical.output_base_root,
        output_base_root_identity=historical.output_base_root_identity,
        output_child_path=historical.output_child_path,
        output_child_predecessor_state=(
            historical.output_child_predecessor_state
        ),
        output_child_predecessor_identity=(
            historical.output_child_predecessor_identity
        ),
        output_bootstrap_lock_path=historical.output_bootstrap_lock_path,
        output_bootstrap_lock_identity=(
            historical.output_bootstrap_lock_identity
        ),
        output_claim_path=historical.output_claim_path,
    )
    historical.admission_path.write_bytes(foreign_raw)
    return foreign_raw, path_identity(historical.admission_path)


@pytest.mark.parametrize(
    ("physical_disposition", "expected_entry_mode"),
    (
        ("exact_old", "POST_HANDOFF_RELEASE_ONLY"),
        ("absent", "POST_HANDOFF_READY"),
        ("valid_foreign", "POST_HANDOFF_READY"),
    ),
)
def test_controller_pair_reentry_after_runtime_handoff_accepts_old_exact_absent_or_valid_foreign_output_record(
    tmp_path: Path,
    monkeypatch: pytest.MonkeyPatch,
    physical_disposition: str,
    expected_entry_mode: str,
) -> None:
    fixture = _controller_pair_post_handoff_fixture(tmp_path, monkeypatch)
    historical = fixture.historical_output_operation
    foreign_evidence: tuple[bytes, tuple[int, int, int]] | None = None
    if physical_disposition == "absent":
        historical.admission_path.unlink()
    elif physical_disposition == "valid_foreign":
        foreign_evidence = _replace_output_operation_with_foreign(fixture)

    with _controller_pair_reentry_capabilities(fixture) as capabilities:
        arguments = {
            **_pair_arguments(capabilities),
            "runtime_admission": fixture.runtime_admission,
        }
        with runtime_installer.lease_controller_apply_pair(**arguments) as pair:
            binding = runtime_installer._require_active_controller_apply_pair(pair)
            assert binding.entry_mode == expected_entry_mode
            assert binding.reentry_output_disposition == physical_disposition

    if foreign_evidence is not None:
        foreign_raw, foreign_identity = foreign_evidence
        assert historical.admission_path.read_bytes() == foreign_raw
        assert path_identity(historical.admission_path) == foreign_identity


@pytest.mark.parametrize(
    "invalid_authority",
    (
        "missing_argument",
        "missing_physical",
        "same_byte_runtime_replacement",
        "dishonest_runtime_evidence_subclass",
        "persisted_wrong_runtime_handoff",
    ),
)
def test_controller_pair_reentry_requires_exact_release_authorized_session_and_runtime_admission(
    tmp_path: Path,
    monkeypatch: pytest.MonkeyPatch,
    invalid_authority: str,
) -> None:
    fixture = _controller_pair_post_handoff_fixture(tmp_path, monkeypatch)
    runtime_admission = fixture.runtime_admission
    expected_session = fixture.apply_started
    if invalid_authority == "missing_argument":
        runtime_admission = None
    elif invalid_authority == "missing_physical":
        fixture.runtime_admission.admission_path.unlink()
    elif invalid_authority == "same_byte_runtime_replacement":
        raw = fixture.runtime_admission.admission_path.read_bytes()
        fixture.runtime_admission.admission_path.unlink()
        fixture.runtime_admission.admission_path.write_bytes(raw)
    elif invalid_authority == "dishonest_runtime_evidence_subclass":
        evidence_type = type(runtime_admission)

        class DishonestRuntimeEvidence(evidence_type):  # type: ignore[misc, valid-type]
            def __eq__(self, other: object) -> bool:
                del other
                return True

            def __ne__(self, other: object) -> bool:
                del other
                return False

        runtime_admission = DishonestRuntimeEvidence(
            **{
                name: getattr(runtime_admission, name)
                for name in runtime_admission.__dataclass_fields__
            }
        )
    else:
        expected_session = _persist_wrong_controller_pair_runtime_handoff(
            fixture
        )

    metadata_calls: list[Path] = []

    def forbidden_metadata(*args: object, **kwargs: object) -> object:
        del args, kwargs
        metadata_calls.append(fixture.pipeline.runtime_root)
        raise AssertionError("invalid reentry reached runtime bootstrap")

    monkeypatch.setattr(
        runtime_installer,
        "_create_or_confirm_runtime_metadata",
        forbidden_metadata,
    )
    with _controller_pair_reentry_capabilities(fixture) as capabilities:
        with pytest.raises((TypeError, ValueError), match="pair|session|runtime|admission"):
            with runtime_installer.lease_controller_apply_pair(
                **{
                    **_pair_arguments(capabilities),
                    "expected_session": expected_session,
                    "runtime_admission": runtime_admission,
                }
            ):
                raise AssertionError("invalid reentry yielded pair")
    assert metadata_calls == []


@pytest.mark.parametrize(
    "invalid_surface",
    (
        "active_absence",
        "same_byte_output_replacement",
        "same_run_output_replacement",
        "output_staging",
        "output_reserved_temp",
        "dishonest_output_evidence_subclass",
        "historical_output_self_digest",
        "historical_output_state",
        "foreign_runtime_admission",
    ),
)
def test_controller_pair_reentry_rejects_active_absence_same_byte_replacement_staging_or_foreign_runtime_admission(
    tmp_path: Path,
    monkeypatch: pytest.MonkeyPatch,
    invalid_surface: str,
) -> None:
    if invalid_surface == "active_absence":
        with _controller_pair_capabilities(tmp_path, monkeypatch) as capabilities:
            capabilities.operation_evidence.admission_path.unlink()
            with pytest.raises(ValueError, match="output_operation|pair"):
                with runtime_installer.lease_controller_apply_pair(
                    **_pair_arguments(capabilities)
                ):
                    raise AssertionError("active absence yielded pair")
            assert not (capabilities.pipeline.runtime_root / ".hsconfig").exists()
        return

    from hsconfig.output_operation_admission import (
        OUTPUT_OPERATION_ADMISSION_RESERVED_TEMP_NAME,
        OUTPUT_OPERATION_ADMISSION_STAGING_NAME,
    )
    from hsconfig.runtime_live_admission import (
        build_runtime_live_attempt_admission_bytes,
    )

    fixture = _controller_pair_post_handoff_fixture(tmp_path, monkeypatch)
    historical = fixture.historical_output_operation
    historical_argument = historical
    if invalid_surface == "same_byte_output_replacement":
        historical.admission_path.unlink()
        historical.admission_path.write_bytes(fixture.output_operation_raw)
    elif invalid_surface == "same_run_output_replacement":
        _replace_output_operation_with_foreign(
            fixture,
            run_id=historical.run_id,
            expected_session_sha256="sha256:" + "d" * 64,
        )
    elif invalid_surface == "output_staging":
        staging = historical.admission_path.with_name(
            OUTPUT_OPERATION_ADMISSION_STAGING_NAME
        )
        staging.write_bytes(b"uncommitted-output-operation\n")
    elif invalid_surface == "output_reserved_temp":
        reserved_temp = historical.admission_path.with_name(
            OUTPUT_OPERATION_ADMISSION_RESERVED_TEMP_NAME
        )
        reserved_temp.write_bytes(b"unfinished-output-operation\n")
    elif invalid_surface == "dishonest_output_evidence_subclass":
        historical.admission_path.unlink()
        evidence_type = type(historical)

        class DishonestOutputEvidence(evidence_type):  # type: ignore[misc, valid-type]
            def __eq__(self, other: object) -> bool:
                del other
                return True

            def __ne__(self, other: object) -> bool:
                del other
                return False

        historical_argument = DishonestOutputEvidence(
            **{
                name: getattr(historical, name)
                for name in historical.__dataclass_fields__
            }
        )
    elif invalid_surface == "historical_output_self_digest":
        historical.admission_path.unlink()
        historical_argument = replace(
            historical,
            admission_sha256="sha256:" + "0" * 64,
        )
    elif invalid_surface == "historical_output_state":
        historical.admission_path.unlink()
        historical_argument = replace(historical, state="BROKEN")
    else:
        old = fixture.runtime_admission
        foreign_raw = build_runtime_live_attempt_admission_bytes(
            run_id="f" * 32,
            apply_attempt_id=old.apply_attempt_id,
            retention_owner_run_id="f" * 32,
            session_root=old.session_root,
            session_root_identity=old.session_root_identity,
            operator_profile_sha256=old.operator_profile_sha256,
            state_root_identity=old.state_root_identity,
            runtime_root=old.runtime_root,
            runtime_root_identity=old.runtime_root_identity,
            output_base_root=old.output_base_root,
            output_base_root_identity=old.output_base_root_identity,
            output_root=old.output_root,
            output_root_identity=old.output_root_identity,
            output_operation_admission_path=(
                old.output_operation_admission_path
            ),
            output_operation_admission_identity=(
                old.output_operation_admission_identity
            ),
            output_operation_admission_sha256=(
                old.output_operation_admission_sha256
            ),
            output_child_binding_sha256=old.output_child_binding_sha256,
            publication_revision=old.publication_revision,
            publication_content_root_sha256=(
                old.publication_content_root_sha256
            ),
            package_root_sha256=old.package_root_sha256,
            pre_apply_runtime_snapshot_sha256=(
                old.pre_apply_runtime_snapshot_sha256
            ),
            apply_invocation_sha256=old.apply_invocation_sha256,
            retention_fence_path=old.retention_fence_path,
        )
        old.admission_path.unlink()
        old.admission_path.write_bytes(foreign_raw)

    metadata_calls: list[Path] = []

    def forbidden_metadata(*args: object, **kwargs: object) -> object:
        del args, kwargs
        metadata_calls.append(fixture.pipeline.runtime_root)
        raise AssertionError("invalid surface reached runtime bootstrap")

    monkeypatch.setattr(
        runtime_installer,
        "_create_or_confirm_runtime_metadata",
        forbidden_metadata,
    )
    with _controller_pair_reentry_capabilities(fixture) as capabilities:
        with pytest.raises(
            (TypeError, ValueError),
            match="pair|output|runtime|admission|residue",
        ):
            with runtime_installer.lease_controller_apply_pair(
                **{
                    **_pair_arguments(capabilities),
                    "output_operation_admission": historical_argument,
                    "runtime_admission": fixture.runtime_admission,
                }
            ):
                raise AssertionError("invalid reentry surface yielded pair")
    assert metadata_calls == []


def test_runtime_apply_lease_token_is_nonforgeable_thread_bound_and_expires(
    tmp_path: Path,
    monkeypatch: pytest.MonkeyPatch,
) -> None:
    import copy
    import pickle
    from queue import Queue
    from threading import Thread

    runtime_root = tmp_path / "runtime"
    runtime_root.mkdir()
    expected_root_identity = path_identity(runtime_root)
    gate_calls: list[tuple[Path, tuple[int, int, int]]] = []

    def allow_runtime_mutation(
        *,
        runtime_root: Path,
        runtime_root_identity: tuple[int, int, int],
    ) -> None:
        gate_calls.append((runtime_root, runtime_root_identity))

    monkeypatch.setattr(
        runtime_installer,
        "require_live_admission_allows_runtime_mutation",
        allow_runtime_mutation,
    )
    cross_thread: Queue[BaseException | None] = Queue()

    with runtime_installer.lease_runtime_apply(
        runtime_root,
        expected_root_identity=expected_root_identity,
    ) as lease:
        runtime_installer._require_active_runtime_apply_lease(
            lease,
            runtime_root=runtime_root,
            expected_root_identity=expected_root_identity,
        )
        assert lease.runtime_root == runtime_root
        assert lease.runtime_root_identity == expected_root_identity
        assert lease.apply_lock_path == runtime_root / ".hsconfig" / "apply.lock"
        assert lease.apply_lock_identity == path_identity(lease.apply_lock_path)
        assert lease.apply_lock_path.stat().st_size == 0

        with pytest.raises(TypeError, match="not_constructible"):
            runtime_installer.RuntimeApplyLockToken()
        with pytest.raises(TypeError, match="not_copyable"):
            copy.copy(lease.lock_token)
        with pytest.raises(TypeError, match="not_copyable"):
            copy.deepcopy(lease.lock_token)
        with pytest.raises(TypeError, match="not_serializable"):
            pickle.dumps(lease.lock_token)

        forged_token = object.__new__(runtime_installer.RuntimeApplyLockToken)
        forged = replace(lease, lock_token=forged_token)
        with pytest.raises(ValueError, match="lease_(?:invalid|inactive)"):
            runtime_installer._require_active_runtime_apply_lease(forged)

        reconstructed = runtime_installer.RuntimeApplyLease(
            runtime_root=lease.runtime_root,
            runtime_root_identity=lease.runtime_root_identity,
            apply_lock_path=lease.apply_lock_path,
            apply_lock_identity=lease.apply_lock_identity,
            lock_token=lease.lock_token,
        )
        with pytest.raises(ValueError, match="lease_invalid"):
            runtime_installer._require_active_runtime_apply_lease(reconstructed)

        def consume_on_other_thread() -> None:
            try:
                runtime_installer._require_active_runtime_apply_lease(lease)
            except BaseException as error:
                cross_thread.put(error)
            else:
                cross_thread.put(None)

        thread = Thread(target=consume_on_other_thread)
        thread.start()
        thread.join(timeout=5)
        assert not thread.is_alive()
        assert isinstance(cross_thread.get_nowait(), ValueError)

    with pytest.raises(ValueError, match="lease_inactive"):
        runtime_installer._require_active_runtime_apply_lease(lease)

    assert gate_calls == [
        (runtime_root, expected_root_identity),
        (runtime_root, expected_root_identity),
    ]
    assert tuple(
        path.relative_to(runtime_root).as_posix() for path in runtime_root.rglob("*")
    ) == (".hsconfig", ".hsconfig/apply.lock")


def test_runtime_lease_consumer_rejects_forged_expired_or_wrong_root_token(
    tmp_path: Path,
    monkeypatch: pytest.MonkeyPatch,
) -> None:
    from hsconfig.output_operation_admission import (
        lease_output_operation_admission,
        require_output_operation_allows_runtime_mutation,
    )

    runtime_root = tmp_path / "runtime"
    other_root = tmp_path / "other-runtime"
    runtime_root.mkdir()
    other_root.mkdir()
    runtime_root_identity = path_identity(runtime_root)
    other_root_identity = path_identity(other_root)
    monkeypatch.setattr(
        runtime_installer,
        "require_live_admission_allows_runtime_mutation",
        lambda **_kwargs: None,
    )

    with runtime_installer.lease_runtime_apply(
        runtime_root,
        expected_root_identity=runtime_root_identity,
    ) as lease:
        with pytest.raises(ValueError, match="runtime_root_mismatch"):
            runtime_installer._require_active_runtime_apply_lease(
                lease,
                runtime_root=other_root,
                expected_root_identity=runtime_root_identity,
            )
        with pytest.raises(ValueError, match="runtime_root_identity_mismatch"):
            runtime_installer._require_active_runtime_apply_lease(
                lease,
                runtime_root=runtime_root,
                expected_root_identity=other_root_identity,
            )
        forged_root = replace(lease, runtime_root=other_root)
        with pytest.raises(ValueError, match="lease_invalid"):
            runtime_installer._require_active_runtime_apply_lease(forged_root)
    with pytest.raises(ValueError, match="lease_inactive"):
        runtime_installer._require_active_runtime_apply_lease(lease)

    admission_blocked_root = tmp_path / "admission-blocked"
    admission_blocked_root.mkdir()

    def block_live_admission(**_kwargs: object) -> None:
        assert not (admission_blocked_root / ".hsconfig").exists()
        raise ValueError("runtime_live_admission_blocks_runtime_mutation")

    monkeypatch.setattr(
        runtime_installer,
        "require_live_admission_allows_runtime_mutation",
        block_live_admission,
    )
    with pytest.raises(ValueError, match="runtime_live_admission_blocks"):
        with runtime_installer.lease_runtime_apply(
            admission_blocked_root,
            expected_root_identity=path_identity(admission_blocked_root),
        ):
            pass
    assert tuple(admission_blocked_root.iterdir()) == ()

    local_app_data = tmp_path / "local-app-data"
    locks_root = local_app_data / "HSConfig" / "locks"
    locks_root.mkdir(parents=True)
    (locks_root / "output-operation.lock").write_bytes(b"")
    monkeypatch.setenv("LOCALAPPDATA", str(local_app_data))
    output_blocked_root = tmp_path / "output-blocked"
    output_blocked_root.mkdir()

    def block_output_operation(*, lease: object) -> None:
        del lease
        assert not (output_blocked_root / ".hsconfig").exists()
        raise ValueError("output_operation_admission_blocks_runtime_mutation")

    monkeypatch.setattr(
        runtime_installer,
        "require_output_operation_allows_runtime_mutation",
        block_output_operation,
    )
    with lease_output_operation_admission() as operation_lease:
        with pytest.raises(ValueError, match="output_operation_admission_blocks"):
            with runtime_installer._lease_runtime_apply_under_output_operation(
                output_operation_lease=operation_lease,
                runtime_root=output_blocked_root,
                expected_root_identity=path_identity(output_blocked_root),
            ):
                pass
        assert tuple(output_blocked_root.iterdir()) == ()

        monkeypatch.setattr(
            runtime_installer,
            "require_output_operation_allows_runtime_mutation",
            require_output_operation_allows_runtime_mutation,
        )
        monkeypatch.setattr(
            runtime_installer,
            "require_live_admission_allows_runtime_mutation",
            lambda **_kwargs: None,
        )
        forged_operation_lease = replace(operation_lease)
        forged_output_root = tmp_path / "forged-output-operation"
        forged_output_root.mkdir()
        with pytest.raises(
            ValueError, match="output_operation_admission_lease_invalid"
        ):
            with runtime_installer._lease_runtime_apply_under_output_operation(
                output_operation_lease=forged_operation_lease,
                runtime_root=forged_output_root,
                expected_root_identity=path_identity(forged_output_root),
            ):
                pass
        assert tuple(forged_output_root.iterdir()) == ()

        with runtime_installer._lease_runtime_apply_under_output_operation(
            output_operation_lease=operation_lease,
            runtime_root=output_blocked_root,
            expected_root_identity=path_identity(output_blocked_root),
        ) as paired_lease:
            runtime_installer._require_active_runtime_apply_lease(paired_lease)

    assert tuple(
        path.relative_to(output_blocked_root).as_posix()
        for path in output_blocked_root.rglob("*")
    ) == (".hsconfig", ".hsconfig/apply.lock")


def test_runtime_admission_requires_staging_bound_before_final(
    tmp_path: Path,
    monkeypatch: pytest.MonkeyPatch,
) -> None:
    import hsconfig.live_start_session as live_start_session

    with _controller_pair_capabilities(tmp_path, monkeypatch) as capabilities:
        capabilities.admission_path.write_bytes(capabilities.admission_raw)
        direct_final_identity = path_identity(capabilities.admission_path)
        with pytest.raises(ValueError, match="runtime_admission"):
            with runtime_installer.lease_controller_apply_pair(
                **_pair_arguments(capabilities)
            ):
                raise AssertionError("PREPARED direct final yielded a pair")
        assert path_identity(capabilities.admission_path) == direct_final_identity
        capabilities.admission_path.unlink()

        with runtime_installer.lease_controller_apply_pair(
            **_pair_arguments(capabilities)
        ) as pair:
            with pytest.raises(
                live_start_session.SessionConflictError,
                match="action_mismatch",
            ):
                live_start_session._authorize_runtime_admission_under_lock(
                    session_lease=capabilities.session_lease,
                    expected_admission_session=capabilities.prepared_session,
                    action="commit_bound_runtime_admission",
                )
            primary_applied, admission = _drive_runtime_admission_with_pair(
                capabilities=capabilities,
                pair=pair,
            )

        pending = primary_applied.pending_transition
        assert pending is not None
        assert pending["stage"] == "PRIMARY_APPLIED"
        assert pending["external_file_action"] is None
        assert primary_applied.runtime_layout_bootstrap is None
        assert tuple(pending["runtime_admission_identity"]) == (
            admission.admission_identity
        )
        assert pending["runtime_admission_sha256"] == admission.admission_sha256
        assert not capabilities.admission_staging_path.exists()
        assert not capabilities.admission_inner_temp_path.exists()


def test_runtime_file_actions_use_planned_staging_bound_commit_matrix(
    tmp_path: Path,
    monkeypatch: pytest.MonkeyPatch,
) -> None:
    import hsconfig.live_start_session as live_start_session
    from hsconfig.atomic_io import atomic_materialize_staging_bytes

    with _controller_pair_capabilities(tmp_path, monkeypatch) as capabilities:
        residue = atomic_materialize_staging_bytes(
            staging_path=capabilities.admission_staging_path,
            inner_temp_path=capabilities.admission_inner_temp_path,
            payload=capabilities.admission_raw,
            expected_parent_identity=path_identity(capabilities.state_root),
            maximum_size=len(capabilities.admission_raw),
        )
        with runtime_installer.lease_controller_apply_pair(
            **_pair_arguments(capabilities)
        ) as pair:
            retire = live_start_session._authorize_runtime_admission_under_lock(
                session_lease=capabilities.session_lease,
                expected_admission_session=capabilities.prepared_session,
                action="retire_unbound_runtime_admission_staging",
            )
            retire_receipt = (
                runtime_installer._execute_runtime_admission_file_action_from_pair(
                    lease_pair=pair,
                    session_lease=capabilities.session_lease,
                    expected_session=capabilities.prepared_session,
                    admission_authorization=retire,
                    payload=capabilities.admission_raw,
                )
            )
            cleaned = live_start_session.advance_runtime_admission_under_lock(
                session_lease=capabilities.session_lease,
                expected_admission_session=capabilities.prepared_session,
                transition="unbound_staging_retired",
                physical_step_receipt=retire_receipt,
            )
            assert not residue.path.exists()
            assert not capabilities.admission_inner_temp_path.exists()
            cleaned_external = cleaned.pending_transition["external_file_action"]
            assert cleaned_external["stage"] == "PLANNED"
            assert cleaned_external["action_kind"] == (
                "materialize_runtime_admission_staging"
            )
            assert cleaned_external["action_index"] == 1

            materialize = (
                live_start_session._authorize_runtime_admission_under_lock(
                    session_lease=capabilities.session_lease,
                    expected_admission_session=cleaned,
                    action="materialize_runtime_admission_staging",
                )
            )
            staging_receipt = (
                runtime_installer._execute_runtime_admission_file_action_from_pair(
                    lease_pair=pair,
                    session_lease=capabilities.session_lease,
                    expected_session=cleaned,
                    admission_authorization=materialize,
                    payload=capabilities.admission_raw,
                )
            )
            staging_bound = live_start_session.advance_runtime_admission_under_lock(
                session_lease=capabilities.session_lease,
                expected_admission_session=cleaned,
                transition="staging_bound",
                physical_step_receipt=staging_receipt,
            )
            bound_identity = tuple(
                staging_bound.pending_transition[
                    "runtime_admission_staging_identity"
                ]
            )
            replacement = capabilities.admission_staging_path.with_name(
                "replacement.staged"
            )
            replacement.write_bytes(capabilities.admission_raw)
            os.replace(replacement, capabilities.admission_staging_path)
            replacement_identity = path_identity(
                capabilities.admission_staging_path
            )
            if replacement_identity == bound_identity:
                pytest.skip("filesystem reused the replaced staging identity")
            commit = live_start_session._authorize_runtime_admission_under_lock(
                session_lease=capabilities.session_lease,
                expected_admission_session=staging_bound,
                action="commit_bound_runtime_admission",
            )
            with pytest.raises((RuntimeError, ValueError), match="bound|changed"):
                runtime_installer._execute_runtime_admission_file_action_from_pair(
                    lease_pair=pair,
                    session_lease=capabilities.session_lease,
                    expected_session=staging_bound,
                    admission_authorization=commit,
                    payload=capabilities.admission_raw,
                )
            assert not capabilities.admission_path.exists()
            assert path_identity(capabilities.admission_staging_path) == (
                replacement_identity
            )


def test_invocation_receipt_uses_apply_start_capability_and_bound_staging(
    tmp_path: Path,
    monkeypatch: pytest.MonkeyPatch,
) -> None:
    import hsconfig.live_start_session as live_start_session
    from tests.test_live_start_session import _task9_complete_runtime_layout

    with _controller_pair_capabilities(tmp_path, monkeypatch) as capabilities:
        context = _runtime_admission_test_context(capabilities)
        with runtime_installer.lease_controller_apply_pair(
            **_pair_arguments(capabilities)
        ) as admission_pair:
            primary_applied, runtime_admission = (
                _drive_runtime_admission_with_pair(
                    capabilities=capabilities,
                    pair=admission_pair,
                )
            )
        context.runtime_admission = runtime_admission
        with pytest.raises(
            live_start_session.SessionConflictError,
            match="file_action_missing",
        ):
            live_start_session._authorize_runtime_admission_under_lock(
                session_lease=capabilities.session_lease,
                expected_admission_session=primary_applied,
                action="materialize_invocation_receipt_staging",
            )
        layout_complete = _task9_complete_runtime_layout(
            context=context,
            lease=capabilities.session_lease,
            admission_committed=primary_applied,
        )

        with runtime_installer.lease_controller_apply_pair(
            **_pair_arguments(
                capabilities,
                expected_session=layout_complete,
                runtime_admission=runtime_admission,
            )
        ) as receipt_pair:
            with pytest.raises((TypeError, ValueError), match="capability|pair"):
                runtime_installer._execute_runtime_admission_file_action_from_pair(
                    lease_pair=receipt_pair,
                    session_lease=capabilities.session_lease,
                    expected_session=layout_complete,
                    admission_authorization=object(),
                    payload=capabilities.invocation.canonical_json,
                )
            assert not context.receipt_staging_path.exists()

            with pytest.raises(
                live_start_session.SessionConflictError,
                match="action_mismatch",
            ):
                live_start_session._authorize_runtime_admission_under_lock(
                    session_lease=capabilities.session_lease,
                    expected_admission_session=layout_complete,
                    action="commit_bound_invocation_receipt",
                )
            materialize = (
                live_start_session._authorize_runtime_admission_under_lock(
                    session_lease=capabilities.session_lease,
                    expected_admission_session=layout_complete,
                    action="materialize_invocation_receipt_staging",
                )
            )
            staging_receipt = (
                runtime_installer._execute_runtime_admission_file_action_from_pair(
                    lease_pair=receipt_pair,
                    session_lease=capabilities.session_lease,
                    expected_session=layout_complete,
                    admission_authorization=materialize,
                    payload=capabilities.invocation.canonical_json,
                )
            )
            staging_bound = live_start_session.advance_runtime_admission_under_lock(
                session_lease=capabilities.session_lease,
                expected_admission_session=layout_complete,
                transition="invocation_receipt_staging_bound",
                physical_step_receipt=staging_receipt,
            )
            external = staging_bound.pending_transition["external_file_action"]
            assert external["stage"] == "STAGING_BOUND"
            commit = live_start_session._authorize_runtime_admission_under_lock(
                session_lease=capabilities.session_lease,
                expected_admission_session=staging_bound,
                action="commit_bound_invocation_receipt",
            )
            commit_receipt = (
                runtime_installer._execute_runtime_admission_file_action_from_pair(
                    lease_pair=receipt_pair,
                    session_lease=capabilities.session_lease,
                    expected_session=staging_bound,
                    admission_authorization=commit,
                    payload=capabilities.invocation.canonical_json,
                )
            )
            receipt_committed = (
                live_start_session.advance_runtime_admission_under_lock(
                    session_lease=capabilities.session_lease,
                    expected_admission_session=staging_bound,
                    transition="invocation_receipt_committed",
                    physical_step_receipt=commit_receipt,
                )
            )

        assert context.receipt_path.read_bytes() == (
            capabilities.invocation.canonical_json
        )
        assert receipt_committed.phase.value == "PUBLICATION_COMMITTED"
        assert receipt_committed.runtime_layout_bootstrap["stage"] == "COMPLETE"
        assert receipt_committed.pending_transition["stage"] == "PRIMARY_APPLIED"
        assert receipt_committed.pending_transition["next_action_index"] == 1
        assert receipt_committed.pending_transition["external_file_action"] is None


def test_runtime_apply_recovery_matrix_covers_external_file_action_and_every_legacy_row(
    tmp_path: Path,
) -> None:
    import hsconfig.live_start_session as live_start_session
    from hsconfig.runtime_live_admission import (
        RuntimeLiveAttemptAdmissionEvidence,
    )

    matrix = runtime_installer._RUNTIME_APPLY_RECOVERY_ACTION_MATRIX
    assert frozenset(matrix) == frozenset(
        live_start_session.RUNTIME_APPLY_RECOVERY_ACTIONS
    )
    assert matrix["materialize_file_action_staging"] == "external_materialize"
    assert matrix["retire_unbound_file_action_staging"] == "external_retire"
    assert matrix["advance_controller_transaction_journal_write"] == (
        "external_commit"
    )
    assert matrix["promote_legacy_uuid_transaction_temp"] == "legacy_promote"
    assert matrix["retire_legacy_uuid_transaction_temp"] == "legacy_retire"
    assert runtime_installer._LEGACY_UUID_TEMP_ACTION_BY_CLASSIFICATION == {
        "legacy_complete_valid": "promote_legacy_uuid_transaction_temp",
        "legacy_monotone_successor": (
            "promote_legacy_uuid_transaction_temp"
        ),
        "legacy_redundant_equal": "retire_legacy_uuid_transaction_temp",
        "legacy_partial_invalid": "retire_legacy_uuid_transaction_temp",
    }

    identity = (1, 2, 3)
    runtime_root = tmp_path / "runtime"
    runtime_admission = RuntimeLiveAttemptAdmissionEvidence(
        admission_path=tmp_path / "live-start-active-attempt.json",
        admission_parent_identity=identity,
        admission_identity=identity,
        admission_sha256="sha256:" + "1" * 64,
        run_id="1" * 32,
        apply_attempt_id="2" * 32,
        retention_owner_run_id="3" * 32,
        session_root=tmp_path / "session",
        session_root_identity=identity,
        operator_profile_sha256="sha256:" + "4" * 64,
        state_root_identity=identity,
        runtime_root=runtime_root,
        runtime_root_identity=identity,
        output_base_root=tmp_path / "output",
        output_base_root_identity=identity,
        output_root=tmp_path / "output" / "run",
        output_root_identity=identity,
        output_operation_admission_path=(
            tmp_path / "output-operation-admission.json"
        ),
        output_operation_admission_identity=identity,
        output_operation_admission_sha256="sha256:" + "5" * 64,
        output_child_binding_sha256="sha256:" + "6" * 64,
        publication_revision="revisions/sha256-" + "7" * 64,
        publication_content_root_sha256="sha256:" + "7" * 64,
        package_root_sha256="sha256:" + "8" * 64,
        pre_apply_runtime_snapshot_sha256="sha256:" + "9" * 64,
        apply_invocation_sha256="sha256:" + "a" * 64,
        retention_fence_path=(
            runtime_root
            / ".hsconfig"
            / "attempt-retention"
            / f"{'2' * 32}.json"
        ),
    )
    common: dict[str, Any] = {
        "lease_pair": object(),
        "transaction_id": runtime_admission.apply_attempt_id,
        "expected_retention_owner_run_id": (
            runtime_admission.retention_owner_run_id
        ),
        "expected_package_root_sha256": (
            runtime_admission.package_root_sha256
        ),
        "expected_deck_name": "ShadowPriest",
        "runtime_admission": runtime_admission,
    }
    for authority_field in (
        "nonterminal_recovery_authorization",
        "terminal_authorization",
    ):
        with pytest.raises(ValueError, match="carrier_matrix_invalid"):
            runtime_installer.recover_runtime_attempt_from_pair(
                **common,
                **{authority_field: object()},
            )


def test_null_authority_runtime_observer_never_promotes_or_deletes_uuid_temps(
    tmp_path: Path,
) -> None:
    runtime_root = tmp_path / "runtime"
    runtime_root.mkdir()
    runtime_installer._ensure_runtime_layout(runtime_root)
    transaction_id = "d" * 32
    journal = _unit_journal(transaction_id=transaction_id)
    raw = runtime_installer.runtime_transaction_journal_bytes(journal)
    temp_path = (
        runtime_root
        / ".hsconfig"
        / "transactions"
        / f".{transaction_id}.json.{'e' * 32}.tmp"
    )
    temp_path.write_bytes(raw)
    before = (path_identity(temp_path), temp_path.read_bytes())

    observed = runtime_installer._observe_exact_runtime_transaction_store(
        runtime_root,
        transaction_id=transaction_id,
        external_file_action=None,
    )

    assert observed.journal is None
    assert observed.legacy_temp_path == temp_path
    assert observed.legacy_temp_identity == before[0]
    assert observed.legacy_temp_size == len(raw)
    assert observed.legacy_temp_sha256 == (
        "sha256:" + hashlib.sha256(raw).hexdigest()
    )
    assert observed.legacy_temp_classification == "legacy_complete_valid"
    assert observed.legacy_temp_origin == "legacy_uuid"
    assert path_identity(temp_path) == before[0]
    assert temp_path.read_bytes() == before[1]
    assert not runtime_transaction_journal_path(
        runtime_root, transaction_id
    ).exists()


def test_recovery_legacy_temp_actions_mutate_exactly_one_bound_temp_per_receipt(
    tmp_path: Path,
) -> None:
    import hsconfig.live_start_session as live_start_session
    from tests.test_live_start_session import (
        _apply_recovery_cursor_for_action,
        _lease,
    )

    transactions = tmp_path / "transactions"
    transactions.mkdir()
    transaction_id = "f" * 32
    journal = _unit_journal(transaction_id=transaction_id)
    raw = runtime_installer.runtime_transaction_journal_bytes(journal)
    final_path = transactions / f"{transaction_id}.json"
    temp_path = transactions / f".{transaction_id}.json.{'1' * 32}.tmp"
    ambiguous_path = transactions / f".{transaction_id}.json.{'2' * 32}.tmp"
    unrelated_transaction_id = "0" * 32
    unrelated_path = transactions / (
        f".{unrelated_transaction_id}.json.{'3' * 32}.tmp"
    )
    temp_path.write_bytes(raw)
    ambiguous_path.write_bytes(raw)
    unrelated_path.write_bytes(b"unrelated-invalid-temp\n")
    parent_identity = path_identity(transactions)
    temp_identity = path_identity(temp_path)
    temp_sha256 = "sha256:" + hashlib.sha256(raw).hexdigest()
    root, cursor, predecessor = _apply_recovery_cursor_for_action(
        tmp_path / "session",
        action="promote_legacy_uuid_transaction_temp",
        recovery_changes={
            "predecessor_transaction_temp_path": str(temp_path.absolute()),
            "predecessor_transaction_temp_parent_identity": parent_identity,
            "predecessor_transaction_temp_identity": temp_identity,
            "predecessor_transaction_temp_size": len(raw),
            "predecessor_transaction_temp_sha256": temp_sha256,
            "predecessor_transaction_temp_classification": (
                "legacy_complete_valid"
            ),
            "predecessor_transaction_temp_origin": "legacy_uuid",
        },
    )
    unrelated_before = (
        path_identity(unrelated_path),
        unrelated_path.read_bytes(),
    )

    with _lease(root) as lease:
        ambiguous_authorization = (
            live_start_session._authorize_nonterminal_apply_recovery_under_lock(
                session_lease=lease,
                expected_recovery_session=cursor,
                expected_action="promote_legacy_uuid_transaction_temp",
            )
        )
        with pytest.raises(ValueError, match="ambiguous"):
            live_start_session._execute_apply_recovery_physical_step(
                recovery_authorization=ambiguous_authorization,
                action="promote_legacy_uuid_transaction_temp",
                physical_action=lambda: (
                    runtime_installer._execute_bound_legacy_uuid_temp_action(
                        recovery=predecessor,
                        action="promote_legacy_uuid_transaction_temp",
                    )
                ),
            )
        assert path_identity(temp_path) == temp_identity
        assert temp_path.read_bytes() == raw
        assert ambiguous_path.read_bytes() == raw
        assert not final_path.exists()
        ambiguous_path.unlink()

        authorization = (
            live_start_session._authorize_nonterminal_apply_recovery_under_lock(
                session_lease=lease,
                expected_recovery_session=cursor,
                expected_action="promote_legacy_uuid_transaction_temp",
            )
        )
        receipt = live_start_session._execute_apply_recovery_physical_step(
            recovery_authorization=authorization,
            action="promote_legacy_uuid_transaction_temp",
            physical_action=lambda: (
                runtime_installer._execute_bound_legacy_uuid_temp_action(
                    recovery=predecessor,
                    action="promote_legacy_uuid_transaction_temp",
                )
            ),
        )

    assert isinstance(receipt, live_start_session.ApplyRecoveryStepReceipt)
    assert final_path.read_bytes() == raw
    assert not temp_path.exists()
    assert path_identity(final_path) == temp_identity
    assert path_identity(unrelated_path) == unrelated_before[0]
    assert unrelated_path.read_bytes() == unrelated_before[1]


