def test_controller_journal_commit_requires_staging_bound_identity(
    tmp_path: Path,
) -> None:
    import hsconfig.live_start_session as live_start_session

    transactions = tmp_path / "transactions"
    transactions.mkdir()
    transaction_id = "5" * 32
    journal = _unit_journal(transaction_id=transaction_id)
    raw = runtime_installer.runtime_transaction_journal_bytes(journal)
    final_path = transactions / f"{transaction_id}.json"
    staging_path = final_path.with_name(f"{final_path.name}.staged")
    inner_temp_path = staging_path.with_name(
        f".{staging_path.name}.live-start-atomic.tmp"
    )
    staging_path.write_bytes(raw)
    planned = live_start_session._build_external_file_action(
        action_kind="advance_controller_transaction_journal_write",
        action_index=9,
        final_path=final_path,
        staging_path=staging_path,
        inner_temp_path=inner_temp_path,
        parent_identity=path_identity(transactions),
        predecessor_identity=None,
        predecessor_size=None,
        predecessor_sha256=None,
        planned_successor_size=len(raw),
        planned_successor_sha256=(
            "sha256:" + hashlib.sha256(raw).hexdigest()
        ),
        commit_mode="create_no_replace",
    )
    with pytest.raises(ValueError, match="staging_bound"):
        runtime_installer._execute_bound_controller_journal_action(
            external_file_action=planned,
            transaction_id=transaction_id,
        )
    assert not final_path.exists()

    bound = dict(planned)
    bound.pop("content_sha256")
    bound.update(
        {
            "stage": "STAGING_BOUND",
            "staging_identity": path_identity(staging_path),
            "staging_size": len(raw),
            "staging_sha256": (
                "sha256:" + hashlib.sha256(raw).hexdigest()
            ),
        }
    )
    bound = live_start_session.seal_embedded_document(
        "external_file_action",
        bound,
    )
    replacement = staging_path.with_name("replacement.staged")
    replacement.write_bytes(raw)
    os.replace(replacement, staging_path)
    with pytest.raises((RuntimeError, ValueError), match="bound|identity"):
        runtime_installer._execute_bound_controller_journal_action(
            external_file_action=bound,
            transaction_id=transaction_id,
        )
    assert not final_path.exists()


def test_controller_journal_posix_link_crash_accepts_only_same_bound_identity(
    tmp_path: Path,
) -> None:
    if os.name == "nt":
        pytest.skip("POSIX hard-link crash state is not used on Windows")
    import hsconfig.live_start_session as live_start_session

    transactions = tmp_path / "transactions"
    transactions.mkdir()
    transaction_id = "6" * 32
    journal = _unit_journal(transaction_id=transaction_id)
    raw = runtime_installer.runtime_transaction_journal_bytes(journal)
    final_path = transactions / f"{transaction_id}.json"
    staging_path = final_path.with_name(f"{final_path.name}.staged")
    inner_temp_path = staging_path.with_name(
        f".{staging_path.name}.live-start-atomic.tmp"
    )
    staging_path.write_bytes(raw)
    bound_identity = path_identity(staging_path)
    os.link(staging_path, final_path)
    external = live_start_session._build_external_file_action(
        action_kind="advance_controller_transaction_journal_write",
        action_index=10,
        final_path=final_path,
        staging_path=staging_path,
        inner_temp_path=inner_temp_path,
        parent_identity=path_identity(transactions),
        predecessor_identity=None,
        predecessor_size=None,
        predecessor_sha256=None,
        planned_successor_size=len(raw),
        planned_successor_sha256=(
            "sha256:" + hashlib.sha256(raw).hexdigest()
        ),
        commit_mode="create_no_replace",
    )
    external_value = dict(external)
    external_value.pop("content_sha256")
    external_value.update(
        {
            "stage": "STAGING_BOUND",
            "staging_identity": bound_identity,
            "staging_size": len(raw),
            "staging_sha256": (
                "sha256:" + hashlib.sha256(raw).hexdigest()
            ),
        }
    )
    bound = live_start_session.seal_embedded_document(
        "external_file_action",
        external_value,
    )

    committed = runtime_installer._execute_bound_controller_journal_action(
        external_file_action=bound,
        transaction_id=transaction_id,
    )

    assert committed.journal_identity == bound_identity
    assert final_path.read_bytes() == raw
    assert not staging_path.exists()


def test_terminal_and_nonterminal_legacy_temp_evidence_bind_origin_classification_path_parent_identity_size_and_digest(
    tmp_path: Path,
) -> None:
    runtime_root = tmp_path / "runtime"
    runtime_root.mkdir()
    runtime_installer._ensure_runtime_layout(runtime_root)
    transaction_id = "7" * 32
    journal = _unit_journal(transaction_id=transaction_id)
    raw = runtime_installer.runtime_transaction_journal_bytes(journal)
    final_path = runtime_transaction_journal_path(runtime_root, transaction_id)
    final_path.write_bytes(raw)
    temp_path = final_path.with_name(
        f".{transaction_id}.json.{'8' * 32}.tmp"
    )
    temp_path.write_bytes(raw)
    observed = runtime_installer._observe_exact_runtime_transaction_store(
        runtime_root,
        transaction_id=transaction_id,
        external_file_action=None,
    )

    nonterminal = runtime_installer._legacy_uuid_temp_evidence(
        observation=observed,
        family="nonterminal_apply",
    )
    terminal = runtime_installer._legacy_uuid_temp_evidence(
        observation=observed,
        family="terminal_resolution",
    )

    assert terminal == nonterminal == {
        "predecessor_transaction_temp_path": str(temp_path),
        "predecessor_transaction_temp_parent_identity": path_identity(
            temp_path.parent
        ),
        "predecessor_transaction_temp_identity": path_identity(temp_path),
        "predecessor_transaction_temp_size": len(raw),
        "predecessor_transaction_temp_sha256": (
            "sha256:" + hashlib.sha256(raw).hexdigest()
        ),
        "predecessor_transaction_temp_classification": (
            "legacy_redundant_equal"
        ),
        "predecessor_transaction_temp_origin": "legacy_uuid",
    }


def test_owner_retirement_reserved_temp_hard_kills_reconcile_before_enumeration(
    tmp_path: Path,
    monkeypatch: pytest.MonkeyPatch,
) -> None:
    import hsconfig.live_start_session as live_start_session
    from tests.test_live_start_session import (
        _apply_recovery_cursor_for_action,
        _lease,
        _owner_scenario,
        _seal_literal_document,
    )

    real_collector = runtime_installer._collect_owner_retirement_cleanup_entries

    for residue_kind in ("partial_inner_temp", "complete_inner_temp"):
        case_root = tmp_path / residue_kind
        owner_scenario = _owner_scenario(
            case_root / "owner",
            stage="PREPARED_PLANNED",
            count=1,
            cursor=0,
        )
        target = Path(owner_scenario["target"])
        runtime_root = target.parent.parent
        inventory = real_collector(target)
        target_identity = path_identity(target)
        tree_sha256 = runtime_installer._owner_retirement_tree_sha256(
            target_identity=target_identity,
            entries=inventory,
        )
        owner = live_start_session._thaw(owner_scenario["owner"])
        owner.pop("content_sha256", None)
        owner.update(
            {
                "retired_target_tree_sha256": tree_sha256,
                "cleanup_entry_count": len(inventory),
                "cleanup_cursor": 0,
                "next_entry_relative_path": inventory[0]["relative_path"],
                "next_entry_kind": inventory[0]["entry_kind"],
                "next_entry_identity": list(inventory[0]["identity"]),
                "next_entry_parent_identity": list(
                    inventory[0]["expected_parent_identity"]
                ),
                "next_entry_size": inventory[0]["size"],
                "next_entry_sha256": inventory[0]["sha256"],
            }
        )
        prepared_raw = runtime_installer._build_owner_retirement_tombstone_bytes(
            state="PREPARED",
            retired_owner_transaction_id=str(
                owner["retired_owner_transaction_id"]
            ),
            initial_owner_journal_path=Path(
                str(owner["initial_owner_journal_path"])
            ),
            initial_owner_journal_identity=tuple(
                owner["initial_owner_journal_identity"]
            ),
            initial_owner_journal_sha256=str(
                owner["initial_owner_journal_sha256"]
            ),
            retired_target_path=target,
            retired_target_parent_identity=tuple(
                owner["retired_target_parent_identity"]
            ),
            retired_target_identity=tuple(owner["retired_target_identity"]),
            retired_target_tree_sha256=tree_sha256,
            successor_transaction_id=str(owner["successor_transaction_id"]),
            successor_package_root_sha256=str(
                owner["successor_package_root_sha256"]
            ),
            successor_owner_journal_path=Path(
                str(owner["successor_owner_journal_path"])
            ),
            successor_owner_journal_identity=tuple(
                owner["successor_owner_journal_identity"]
            ),
            successor_owner_journal_sha256=str(
                owner["successor_owner_journal_sha256"]
            ),
            cleanup_entries=inventory,
            completed_cleanup_cursor=None,
            completed_owner_journal_identity=None,
            completed_owner_journal_sha256=None,
        )
        parsed_prepared = (
            runtime_installer._parse_owner_retirement_tombstone_bytes(
                prepared_raw,
                runtime_root=runtime_root,
            )
        )
        owner.update(
            {
                "tombstone_sha256": (
                    "sha256:" + hashlib.sha256(prepared_raw).hexdigest()
                ),
                "cleanup_manifest_sha256": parsed_prepared[
                    "cleanup_manifest_sha256"
                ],
            }
        )
        sealed_owner = _seal_literal_document(owner)
        tombstone_path = Path(str(owner["tombstone_path"]))
        staging_path = tombstone_path.with_name(
            f"{tombstone_path.name}.staged"
        )
        inner_temp_path = staging_path.with_name(
            f".{staging_path.name}.live-start-atomic.tmp"
        )
        external = live_start_session._build_external_file_action(
            action_kind="commit_owner_retirement_prepared",
            action_index=10,
            final_path=tombstone_path,
            staging_path=staging_path,
            inner_temp_path=inner_temp_path,
            parent_identity=path_identity(tombstone_path.parent),
            predecessor_identity=None,
            predecessor_size=None,
            predecessor_sha256=None,
            planned_successor_size=len(prepared_raw),
            planned_successor_sha256=(
                "sha256:" + hashlib.sha256(prepared_raw).hexdigest()
            ),
            commit_mode="create_no_replace",
        )
        root, cursor, recovery = _apply_recovery_cursor_for_action(
            case_root / "session",
            action="materialize_file_action_staging",
            recovery_changes={
                "external_file_action": live_start_session._thaw(external),
                "owner_retirement": sealed_owner,
            },
        )
        session_path = root / "session.json"
        session_before = session_path.read_bytes()
        owner_before = live_start_session._thaw(
            recovery["owner_retirement"]
        )
        owner_before_raw = live_start_session._canonical_json(owner_before)
        layout_identities = {
            "runtime_root": path_identity(runtime_root),
            "custom_config": path_identity(runtime_root / "CustomConfig"),
            "transactions": path_identity(
                runtime_root / ".hsconfig" / "transactions"
            ),
            "owner_retirements": path_identity(tombstone_path.parent),
        }
        residue = (
            prepared_raw
            if residue_kind == "complete_inner_temp"
            else prepared_raw[: max(1, len(prepared_raw) // 2)]
        )
        inner_temp_path.write_bytes(residue)
        unrelated_path = tombstone_path.parent / "unrelated.keep"
        unrelated_path.write_bytes(b"must-remain\n")
        before_direct = _runtime_nonlock_surface_evidence(runtime_root)
        collector_observations: list[tuple[Path, bool, bool]] = []

        def observed_collector(
            observed_target: Path,
        ) -> tuple[Mapping[str, object], ...]:
            collector_observations.append(
                (
                    observed_target,
                    staging_path.exists(),
                    inner_temp_path.exists(),
                )
            )
            return real_collector(observed_target)

        with monkeypatch.context() as case_patch:
            case_patch.setattr(
                runtime_installer,
                "_collect_owner_retirement_cleanup_entries",
                observed_collector,
            )
            with pytest.raises(
                ValueError,
                match=(
                    "runtime_owner_retirement_"
                    "staging_reconciliation_required"
                ),
            ):
                runtime_installer._owner_retirement_materialize_action(
                    recovery=recovery,
                    runtime_root=runtime_root,
                    layout_identities=layout_identities,
                )

            assert collector_observations == []
            assert _runtime_nonlock_surface_evidence(runtime_root) == before_direct
            assert session_path.read_bytes() == session_before

            with _lease(root) as lease:
                persisted = (
                    live_start_session.load_live_start_session_under_lock(
                        session_lease=lease
                    )
                )
                assert persisted.canonical_json == cursor.canonical_json
                assert live_start_session._thaw(
                    persisted.apply_recovery["owner_retirement"]
                ) == owner_before
                retirement_authorization = (
                    live_start_session._authorize_nonterminal_apply_recovery_under_lock(
                        session_lease=lease,
                        expected_recovery_session=persisted,
                        expected_action=(
                            "retire_unbound_file_action_staging"
                        ),
                    )
                )
                retirement_receipt = (
                    live_start_session._execute_apply_recovery_physical_step(
                        recovery_authorization=retirement_authorization,
                        action="retire_unbound_file_action_staging",
                        physical_action=lambda: (
                            runtime_installer._retire_unbound_recovery_external_file_action(
                                recovery=recovery
                            )
                        ),
                    )
                )
                assert session_path.read_bytes() == session_before
                before_cas = (
                    live_start_session.load_live_start_session_under_lock(
                        session_lease=lease
                    )
                )
                assert before_cas.canonical_json == cursor.canonical_json
                assert live_start_session._thaw(
                    before_cas.apply_recovery["owner_retirement"]
                ) == owner_before
                advanced = (
                    live_start_session.advance_nonterminal_apply_recovery_under_lock(
                        session_lease=lease,
                        expected_recovery_session=cursor,
                        transition="physical_recovery_advanced",
                        recovery_evidence=None,
                        recovery_authorization=None,
                        physical_step_receipt=retirement_receipt,
                        runtime_observation_receipt=None,
                    )
                )

            assert not tombstone_path.exists()
            assert not staging_path.exists()
            assert not inner_temp_path.exists()
            assert session_path.read_bytes() == advanced.canonical_json
            assert session_path.read_bytes() != session_before
            relative_inner = inner_temp_path.relative_to(runtime_root).as_posix()
            expected_rows = tuple(
                row
                for row in before_direct[3]
                if row[0] != relative_inner
            )
            assert _runtime_nonlock_surface_evidence(runtime_root) == (
                before_direct[0],
                before_direct[1],
                before_direct[2],
                expected_rows,
            )
            assert unrelated_path.read_bytes() == b"must-remain\n"
            assert advanced.apply_recovery is not None
            advanced_recovery = advanced.apply_recovery
            assert advanced_recovery["expected_action"] == (
                "materialize_file_action_staging"
            )
            assert live_start_session._thaw(
                advanced_recovery["owner_retirement"]
            ) == owner_before
            assert live_start_session._canonical_json(
                live_start_session._thaw(
                    advanced_recovery["owner_retirement"]
                )
            ) == owner_before_raw
            advanced_external = advanced_recovery["external_file_action"]
            assert advanced_external["stage"] == "PLANNED"
            assert advanced_external["action_kind"] == (
                "commit_owner_retirement_prepared"
            )
            assert advanced_external["action_index"] == (
                external["action_index"] + 1
            )
            assert collector_observations == []

            with _lease(root) as lease:
                materialize_authorization = (
                    live_start_session._authorize_nonterminal_apply_recovery_under_lock(
                        session_lease=lease,
                        expected_recovery_session=advanced,
                        expected_action="materialize_file_action_staging",
                    )
                )
                materialize_receipt = (
                    live_start_session._execute_apply_recovery_physical_step(
                        recovery_authorization=materialize_authorization,
                        action="materialize_file_action_staging",
                        physical_action=lambda: (
                            runtime_installer._owner_retirement_materialize_action(
                                recovery=advanced_recovery,
                                runtime_root=runtime_root,
                                layout_identities=layout_identities,
                            )
                        ),
                    )
                )
                materialized = (
                    live_start_session.advance_nonterminal_apply_recovery_under_lock(
                        session_lease=lease,
                        expected_recovery_session=advanced,
                        transition="physical_recovery_advanced",
                        recovery_evidence=None,
                        recovery_authorization=None,
                        physical_step_receipt=materialize_receipt,
                        runtime_observation_receipt=None,
                    )
                )

        assert collector_observations == [(target, False, False)]
        assert not inner_temp_path.exists()
        assert staging_path.read_bytes() == prepared_raw
        assert materialized.apply_recovery is not None
        assert materialized.apply_recovery["expected_action"] == (
            "commit_owner_retirement_prepared"
        )
        assert live_start_session._thaw(
            materialized.apply_recovery["owner_retirement"]
        ) == owner_before
        assert live_start_session._canonical_json(
            live_start_session._thaw(
                materialized.apply_recovery["owner_retirement"]
            )
        ) == owner_before_raw


