def _inject_prepared_owner_reconstruction_replacement(
    fixture: SimpleNamespace,
    *,
    case: str,
) -> None:
    if case == "same_byte_file":
        old_identity = path_identity(fixture.config_path)
        raw = fixture.config_path.read_bytes()
        replacement = fixture.target / "same-byte-replacement.tmp"
        replacement.write_bytes(raw)
        os.replace(replacement, fixture.config_path)
        assert path_identity(fixture.config_path) != old_identity
        assert fixture.config_path.read_bytes() == raw
        return
    if case == "empty_directory_added":
        (fixture.target / "late-empty").mkdir()
        return
    if case == "empty_directory_replaced":
        old_identity = path_identity(fixture.empty_directory)
        backup = fixture.runtime_root.parent / "original-empty"
        fixture.empty_directory.rename(backup)
        fixture.empty_directory.mkdir()
        assert path_identity(fixture.empty_directory) != old_identity
        return
    if case == "target_root_replaced":
        old_identity = path_identity(fixture.target)
        backup = fixture.runtime_root.parent / "original-target"
        fixture.target.rename(backup)
        shutil.copytree(backup, fixture.target)
        assert path_identity(fixture.target) != old_identity
        return
    if case == "custom_config_parent_replaced":
        old_identity = path_identity(fixture.custom_config)
        backup = fixture.runtime_root.parent / "original-custom-config"
        fixture.custom_config.rename(backup)
        fixture.custom_config.mkdir()
        for child in tuple(backup.iterdir()):
            child.rename(fixture.custom_config / child.name)
        assert path_identity(fixture.custom_config) != old_identity
        return
    if case == "runtime_root_replaced":
        old_identity = path_identity(fixture.runtime_root)
        backup = fixture.runtime_root.parent / "original-runtime-root"
        fixture.runtime_root.rename(backup)
        fixture.runtime_root.mkdir()
        for child in tuple(backup.iterdir()):
            child.rename(fixture.runtime_root / child.name)
        assert path_identity(fixture.runtime_root) != old_identity
        return
    raise AssertionError(case)


def test_owner_retirement_prepared_reconstruction_rejects_same_byte_file_empty_directory_parent_or_root_replacement(
    tmp_path: Path,
    monkeypatch: pytest.MonkeyPatch,
) -> None:
    import hsconfig.live_start_session as live_start_session
    from tests.test_live_start_session import _lease

    real_collector = runtime_installer._collect_owner_retirement_cleanup_entries
    stable_error = (
        r"^runtime_owner_retirement_"
        r"(?:runtime_root|target_parent|parent|target|target_tree|inventory|authority)_"
        r"(?:changed|invalid)$"
    )
    before_collector_cases = (
        "same_byte_file",
        "empty_directory_added",
        "empty_directory_replaced",
    )
    for case in before_collector_cases:
        fixture = _prepared_owner_reconstruction_fixture(tmp_path / case)
        session_path = fixture.session_root / "session.json"
        session_before = session_path.read_bytes()
        _inject_prepared_owner_reconstruction_replacement(
            fixture,
            case=case,
        )
        runtime_after_attack = _runtime_nonlock_surface_evidence(
            fixture.runtime_root
        )

        with pytest.raises(ValueError, match=stable_error):
            runtime_installer._owner_retirement_materialize_action(
                recovery=fixture.recovery,
                runtime_root=fixture.runtime_root,
                layout_identities=fixture.layout_identities,
            )

        assert _runtime_nonlock_surface_evidence(fixture.runtime_root) == (
            runtime_after_attack
        )
        assert session_path.read_bytes() == session_before

    after_collector_cases = (
        "target_root_replaced",
        "custom_config_parent_replaced",
    )
    for case in after_collector_cases:
        fixture = _prepared_owner_reconstruction_fixture(tmp_path / case)
        session_path = fixture.session_root / "session.json"
        session_before = session_path.read_bytes()
        post_attack_runtime: list[tuple[object, ...]] = []

        def collect_then_replace(
            observed_target: Path,
        ) -> tuple[Mapping[str, object], ...]:
            assert not post_attack_runtime
            inventory = real_collector(observed_target)
            _inject_prepared_owner_reconstruction_replacement(
                fixture,
                case=case,
            )
            post_attack_runtime.append(
                _runtime_nonlock_surface_evidence(fixture.runtime_root)
            )
            return inventory

        with monkeypatch.context() as case_patch:
            case_patch.setattr(
                runtime_installer,
                "_collect_owner_retirement_cleanup_entries",
                collect_then_replace,
            )
            with pytest.raises(ValueError, match=stable_error):
                runtime_installer._owner_retirement_materialize_action(
                    recovery=fixture.recovery,
                    runtime_root=fixture.runtime_root,
                    layout_identities=fixture.layout_identities,
                )

        assert len(post_attack_runtime) == 1
        assert _runtime_nonlock_surface_evidence(fixture.runtime_root) == (
            post_attack_runtime[0]
        )
        assert session_path.read_bytes() == session_before

    fixture = _prepared_owner_reconstruction_fixture(
        tmp_path / "custom-config-parent-after-parse"
    )
    session_path = fixture.session_root / "session.json"
    session_before = session_path.read_bytes()
    post_parse_runtime: list[tuple[object, ...]] = []
    real_parse = runtime_installer._parse_owner_retirement_tombstone_bytes

    def parse_then_replace_parent(
        raw: bytes,
        *,
        runtime_root: Path,
    ) -> Mapping[str, object]:
        assert not post_parse_runtime
        parsed = real_parse(raw, runtime_root=runtime_root)
        _inject_prepared_owner_reconstruction_replacement(
            fixture,
            case="custom_config_parent_replaced",
        )
        post_parse_runtime.append(
            _runtime_nonlock_surface_evidence(fixture.runtime_root)
        )
        return parsed

    with monkeypatch.context() as parse_patch:
        parse_patch.setattr(
            runtime_installer,
            "_parse_owner_retirement_tombstone_bytes",
            parse_then_replace_parent,
        )
        with pytest.raises(ValueError, match=stable_error):
            runtime_installer._owner_retirement_materialize_action(
                recovery=fixture.recovery,
                runtime_root=fixture.runtime_root,
                layout_identities=fixture.layout_identities,
            )

    assert len(post_parse_runtime) == 1
    assert _runtime_nonlock_surface_evidence(fixture.runtime_root) == (
        post_parse_runtime[0]
    )
    assert session_path.read_bytes() == session_before

    fixture = _prepared_owner_reconstruction_fixture(
        tmp_path / "runtime-root-before-materialize"
    )
    session_path = fixture.session_root / "session.json"
    session_before = session_path.read_bytes()
    _inject_prepared_owner_reconstruction_replacement(
        fixture,
        case="runtime_root_replaced",
    )
    runtime_after_attack = _runtime_nonlock_surface_evidence(
        fixture.runtime_root
    )
    with pytest.raises(ValueError, match=stable_error):
        runtime_installer._owner_retirement_materialize_action(
            recovery=fixture.recovery,
            runtime_root=fixture.runtime_root,
            layout_identities=fixture.layout_identities,
        )
    assert _runtime_nonlock_surface_evidence(fixture.runtime_root) == (
        runtime_after_attack
    )
    assert session_path.read_bytes() == session_before

    fixture = _prepared_owner_reconstruction_fixture(
        tmp_path / "between-materialize-and-commit"
    )
    materialized = _advance_prepared_owner_reconstruction_action(
        fixture,
        cursor=fixture.cursor,
        action="materialize_file_action_staging",
    )
    assert materialized.apply_recovery is not None
    session_path = fixture.session_root / "session.json"
    session_after_materialize = session_path.read_bytes()
    recovery = materialized.apply_recovery
    with _lease(fixture.session_root) as lease:
        authorization = (
            live_start_session._authorize_nonterminal_apply_recovery_under_lock(
                session_lease=lease,
                expected_recovery_session=materialized,
                expected_action="commit_owner_retirement_prepared",
            )
        )
        _inject_prepared_owner_reconstruction_replacement(
            fixture,
            case="runtime_root_replaced",
        )
        runtime_after_attack = _runtime_nonlock_surface_evidence(
            fixture.runtime_root
        )
        with pytest.raises(ValueError, match=stable_error):
            live_start_session._execute_apply_recovery_physical_step(
                recovery_authorization=authorization,
                action="commit_owner_retirement_prepared",
                physical_action=lambda: (
                    runtime_installer._owner_retirement_commit_prepared_action(
                        recovery=recovery,
                        runtime_root=fixture.runtime_root,
                        layout_identities=fixture.layout_identities,
                    )
                ),
            )

    assert _runtime_nonlock_surface_evidence(fixture.runtime_root) == (
        runtime_after_attack
    )
    assert session_path.read_bytes() == session_after_materialize


@pytest.mark.parametrize(
    "case",
    (
        "exact",
        "prepared_direct_final",
        "same_bytes_different_identity",
        "wrong_identity",
        "residual_staging",
        "residual_inner_temp",
    ),
)
def test_runtime_admission_bound_commit_action_before_cas_reenters_exactly(
    tmp_path: Path,
    monkeypatch: pytest.MonkeyPatch,
    case: str,
) -> None:
    import hsconfig.live_start_session as live_start_session
    from hsconfig.runtime_live_admission import (
        load_runtime_live_attempt_admission,
    )

    with _controller_pair_capabilities(tmp_path, monkeypatch) as capabilities:
        if case == "prepared_direct_final":
            capabilities.admission_path.write_bytes(
                capabilities.admission_raw
            )
            runtime_admission = load_runtime_live_attempt_admission()
            assert runtime_admission is not None
            session_path = (
                capabilities.session_lease.session_root / "session.json"
            )
            final_before = (
                path_identity(capabilities.admission_path),
                capabilities.admission_path.read_bytes(),
            )
            session_before = (
                path_identity(session_path),
                session_path.read_bytes(),
            )
            with pytest.raises(ValueError, match="session|runtime_admission"):
                with runtime_installer.lease_controller_apply_pair(
                    **_pair_arguments(
                        capabilities,
                        runtime_admission=runtime_admission,
                    )
                ):
                    raise AssertionError("PREPARED direct final yielded pair")
            assert (
                path_identity(capabilities.admission_path),
                capabilities.admission_path.read_bytes(),
            ) == final_before
            assert (
                path_identity(session_path),
                session_path.read_bytes(),
            ) == session_before
            return

        with runtime_installer.lease_controller_apply_pair(
            **_pair_arguments(capabilities)
        ) as first_pair:
            materialize = (
                live_start_session._authorize_runtime_admission_under_lock(
                    session_lease=capabilities.session_lease,
                    expected_admission_session=capabilities.prepared_session,
                    action="materialize_runtime_admission_staging",
                )
            )
            staging_receipt = (
                runtime_installer._execute_runtime_admission_file_action_from_pair(
                    lease_pair=first_pair,
                    session_lease=capabilities.session_lease,
                    expected_session=capabilities.prepared_session,
                    admission_authorization=materialize,
                    payload=capabilities.admission_raw,
                )
            )
            staging_bound = (
                live_start_session.advance_runtime_admission_under_lock(
                    session_lease=capabilities.session_lease,
                    expected_admission_session=(
                        capabilities.prepared_session
                    ),
                    transition="staging_bound",
                    physical_step_receipt=staging_receipt,
                )
            )
            commit = (
                live_start_session._authorize_runtime_admission_under_lock(
                    session_lease=capabilities.session_lease,
                    expected_admission_session=staging_bound,
                    action="commit_bound_runtime_admission",
                )
            )
            first_commit_receipt = (
                runtime_installer._execute_runtime_admission_file_action_from_pair(
                    lease_pair=first_pair,
                    session_lease=capabilities.session_lease,
                    expected_session=staging_bound,
                    admission_authorization=commit,
                    payload=capabilities.admission_raw,
                )
            )
            assert isinstance(
                first_commit_receipt,
                live_start_session.RuntimeAdmissionStepReceipt,
            )

        runtime_admission = load_runtime_live_attempt_admission()
        assert runtime_admission is not None
        bound_identity = tuple(
            staging_bound.pending_transition[
                "runtime_admission_staging_identity"
            ]
        )
        assert runtime_admission.admission_identity == bound_identity
        assert not capabilities.admission_staging_path.exists()
        assert not capabilities.admission_inner_temp_path.exists()

        runtime_admission_argument = runtime_admission
        if case == "same_bytes_different_identity":
            replacement = capabilities.admission_path.with_name(
                "same-byte-replacement.json"
            )
            replacement.write_bytes(capabilities.admission_raw)
            os.replace(replacement, capabilities.admission_path)
            if path_identity(capabilities.admission_path) == bound_identity:
                pytest.skip("filesystem reused the committed admission identity")
        elif case == "wrong_identity":
            runtime_admission_argument = replace(
                runtime_admission,
                admission_identity=(
                    runtime_admission.admission_identity[0] + 1,
                    runtime_admission.admission_identity[1] + 1,
                    runtime_admission.admission_identity[2],
                ),
            )
        elif case == "residual_staging":
            capabilities.admission_staging_path.write_bytes(
                capabilities.admission_raw
            )
        elif case == "residual_inner_temp":
            capabilities.admission_inner_temp_path.write_bytes(
                b"incomplete-commit\n"
            )

        observed_paths = (
            capabilities.admission_path,
            capabilities.admission_staging_path,
            capabilities.admission_inner_temp_path,
            capabilities.session_lease.session_root / "session.json",
        )

        def snapshot() -> dict[Path, tuple[object, ...]]:
            result: dict[Path, tuple[object, ...]] = {}
            for path in observed_paths:
                if path.exists():
                    result[path] = (
                        True,
                        path_identity(path),
                        path.read_bytes(),
                    )
                else:
                    result[path] = (False,)
            return result

        before = snapshot()
        pair_arguments = _pair_arguments(
            capabilities,
            expected_session=staging_bound,
            runtime_admission=runtime_admission_argument,
        )
        if case != "exact":
            with pytest.raises(
                ValueError,
                match="session|runtime_admission",
            ):
                with runtime_installer.lease_controller_apply_pair(
                    **pair_arguments
                ):
                    raise AssertionError("invalid bound commit yielded pair")
            assert snapshot() == before
            return

        with runtime_installer.lease_controller_apply_pair(
            **pair_arguments
        ) as resumed_pair:
            resumed_commit = (
                live_start_session._authorize_runtime_admission_under_lock(
                    session_lease=capabilities.session_lease,
                    expected_admission_session=staging_bound,
                    action="commit_bound_runtime_admission",
                )
            )
            resumed_receipt = (
                runtime_installer._execute_runtime_admission_file_action_from_pair(
                    lease_pair=resumed_pair,
                    session_lease=capabilities.session_lease,
                    expected_session=staging_bound,
                    admission_authorization=resumed_commit,
                    payload=capabilities.admission_raw,
                )
            )
            primary_applied = (
                live_start_session.advance_runtime_admission_under_lock(
                    session_lease=capabilities.session_lease,
                    expected_admission_session=staging_bound,
                    transition="admission_primary_applied",
                    physical_step_receipt=resumed_receipt,
                )
            )
            session_path = (
                capabilities.session_lease.session_root / "session.json"
            )
            primary_bytes = session_path.read_bytes()
            with pytest.raises(live_start_session.SessionCapabilityError):
                live_start_session.advance_runtime_admission_under_lock(
                    session_lease=capabilities.session_lease,
                    expected_admission_session=staging_bound,
                    transition="admission_primary_applied",
                    physical_step_receipt=resumed_receipt,
                )
            assert session_path.read_bytes() == primary_bytes

        pending = primary_applied.pending_transition
        assert pending["stage"] == "PRIMARY_APPLIED"
        assert pending["external_file_action"] is None
        assert tuple(pending["runtime_admission_identity"]) == bound_identity
        assert path_identity(capabilities.admission_path) == bound_identity
        assert not capabilities.admission_staging_path.exists()
        assert not capabilities.admission_inner_temp_path.exists()


def test_paired_recovery_rejects_evidence_or_authority_subclasses_before_observer_or_mutator(
    tmp_path: Path,
    monkeypatch: pytest.MonkeyPatch,
) -> None:
    import hsconfig.live_start_session as live_start_session
    from hsconfig.runtime_live_admission import (
        RuntimeLiveAttemptAdmissionEvidence,
    )

    identity = (1, 2, 3)
    runtime_root = (tmp_path / "runtime").absolute()
    exact_admission = RuntimeLiveAttemptAdmissionEvidence(
        admission_path=(
            tmp_path / "state" / "live-start-active-attempt.json"
        ).absolute(),
        admission_parent_identity=identity,
        admission_identity=identity,
        admission_sha256="sha256:" + "1" * 64,
        run_id="1" * 32,
        apply_attempt_id="2" * 32,
        retention_owner_run_id="3" * 32,
        session_root=(tmp_path / "session").absolute(),
        session_root_identity=identity,
        operator_profile_sha256="sha256:" + "4" * 64,
        state_root_identity=identity,
        runtime_root=runtime_root,
        runtime_root_identity=identity,
        output_base_root=(tmp_path / "output").absolute(),
        output_base_root_identity=identity,
        output_root=(tmp_path / "output" / "run").absolute(),
        output_root_identity=identity,
        output_operation_admission_path=(
            tmp_path / "state" / "output-operation-admission.json"
        ).absolute(),
        output_operation_admission_identity=identity,
        output_operation_admission_sha256="sha256:" + "5" * 64,
        output_child_binding_sha256="sha256:" + "6" * 64,
        publication_revision="revisions/sha256-" + "7" * 64,
        publication_content_root_sha256="sha256:" + "7" * 64,
        package_root_sha256="sha256:" + "8" * 64,
        pre_apply_runtime_snapshot_sha256="sha256:" + "9" * 64,
        apply_invocation_sha256="sha256:" + "a" * 64,
        retention_fence_path=(
            runtime_root
            / ".hsconfig"
            / "attempt-retention"
            / f"{'2' * 32}.json"
        ),
    )

    class DishonestAdmission(RuntimeLiveAttemptAdmissionEvidence):
        def __eq__(self, other: object) -> bool:
            del other
            return True

    dishonest_admission = DishonestAdmission(
        **{
            name: getattr(exact_admission, name)
            for name in exact_admission.__dataclass_fields__
        }
    )

    class DishonestRecoveryAuthorization(
        live_start_session.RuntimeAttemptRecoveryAuthorization
    ):
        pass

    class DishonestObservationAuthorization(
        live_start_session.RuntimeObservationAuthorization
    ):
        pass

    class DishonestTerminalAuthorization(
        live_start_session.TerminalRetirementAuthorization
    ):
        pass

    exact_recovery_authorization = object.__new__(
        live_start_session.RuntimeAttemptRecoveryAuthorization
    )
    invalid_calls: tuple[
        tuple[RuntimeLiveAttemptAdmissionEvidence, dict[str, object]], ...
    ] = (
        (
            dishonest_admission,
            {
                "nonterminal_recovery_authorization": (
                    exact_recovery_authorization
                )
            },
        ),
        (
            exact_admission,
            {
                "nonterminal_recovery_authorization": object.__new__(
                    DishonestRecoveryAuthorization
                )
            },
        ),
        (
            exact_admission,
            {
                "observation_family": "nonterminal_apply",
                "runtime_observation_authorization": object.__new__(
                    DishonestObservationAuthorization
                ),
            },
        ),
        (
            exact_admission,
            {
                "terminal_authorization": object.__new__(
                    DishonestTerminalAuthorization
                )
            },
        ),
    )
    forbidden_calls: list[str] = []

    def forbidden(name: str):
        def fail(*_args: object, **_kwargs: object) -> object:
            forbidden_calls.append(name)
            raise AssertionError(f"invalid carrier reached {name}")

        return fail

    monkeypatch.setattr(
        runtime_installer,
        "_require_active_controller_apply_pair",
        forbidden("pair"),
    )
    for symbol in (
        "_observe_exact_paired_runtime_attempt",
        "_execute_bound_legacy_uuid_temp_action",
        "_execute_bound_controller_journal_action",
        "_retire_unbound_recovery_external_file_action",
    ):
        monkeypatch.setattr(runtime_installer, symbol, forbidden(symbol))

    for admission, carrier_arguments in invalid_calls:
        with pytest.raises(ValueError, match="carrier_matrix_invalid"):
            runtime_installer.recover_runtime_attempt_from_pair(
                lease_pair=object(),
                transaction_id=admission.apply_attempt_id,
                expected_retention_owner_run_id=(
                    admission.retention_owner_run_id
                ),
                expected_package_root_sha256=(
                    admission.package_root_sha256
                ),
                expected_deck_name="ShadowPriest",
                runtime_admission=admission,
                **carrier_arguments,
            )
    assert forbidden_calls == []

    class DishonestObservationReceipt(
        live_start_session.RuntimeObservationReceipt
    ):
        pass

    class DishonestApplyReceipt(
        live_start_session.ApplyRecoveryStepReceipt
    ):
        pass

    class DishonestTerminalReceipt(
        live_start_session.TerminalResolutionStepReceipt
    ):
        pass

    exact_observation_receipt = object.__new__(
        live_start_session.RuntimeObservationReceipt
    )
    result_rows: tuple[dict[str, object], ...] = (
        {
            "runtime_admission": dishonest_admission,
            "observation_family": "nonterminal_apply",
            "runtime_observation_receipt": exact_observation_receipt,
        },
        {
            "runtime_admission": exact_admission,
            "observation_family": "nonterminal_apply",
            "runtime_observation_receipt": object.__new__(
                DishonestObservationReceipt
            ),
        },
        {
            "runtime_admission": exact_admission,
            "observation_family": None,
            "apply_recovery_step_receipt": object.__new__(
                DishonestApplyReceipt
            ),
        },
        {
            "runtime_admission": exact_admission,
            "observation_family": None,
            "terminal_resolution_step_receipt": object.__new__(
                DishonestTerminalReceipt
            ),
        },
    )
    for changes in result_rows:
        values: dict[str, object] = {
            "transaction_id": exact_admission.apply_attempt_id,
            "status": "not_committed",
            "package_root_sha256": exact_admission.package_root_sha256,
            "receipt_path": None,
            "retained_attempt_record_path": None,
            "retained_attempt_record_identity": None,
            "retained_attempt_record_sha256": None,
            "retained_journal_path": None,
            "retained_journal_identity": None,
            "retained_journal_sha256": None,
            "target_owner_journal_path": None,
            "target_owner_journal_identity": None,
            "target_owner_journal_sha256": None,
            "runtime_admission": exact_admission,
            "observation_family": None,
            "initial_apply_recovery_evidence": None,
            "initial_terminal_resolution_evidence": None,
            "runtime_observation_receipt": None,
            "apply_recovery_step_receipt": None,
            "terminal_resolution_step_receipt": None,
            **changes,
        }
        with pytest.raises(ValueError, match="family_nullability_invalid"):
            runtime_installer.RuntimeAttemptRecovery(**values)


@pytest.mark.parametrize(
    "case",
    ("directory_ads", "parent_replacement", "parent_reparse"),
)
def test_raw_transaction_observer_rejects_transactions_parent_ads_or_replacement(
    tmp_path: Path,
    monkeypatch: pytest.MonkeyPatch,
    case: str,
) -> None:
    runtime_root = (tmp_path / "runtime").absolute()
    transactions = runtime_root / ".hsconfig" / "transactions"
    transactions.mkdir(parents=True)
    transaction_id = "d" * 32

    if case == "directory_ads":
        _create_ntfs_stream_or_skip(transactions)
    elif case == "parent_replacement":
        original_scandir = os.scandir
        replaced = False

        def replace_parent_before_empty_enumeration(
            path: object,
        ) -> os.ScandirIterator[str]:
            nonlocal replaced
            candidate = Path(path)  # type: ignore[arg-type]
            if candidate == transactions and not replaced:
                replaced = True
                transactions.rename(
                    transactions.with_name("transactions-replaced")
                )
                transactions.mkdir()
            return original_scandir(path)  # type: ignore[arg-type]

        monkeypatch.setattr(
            runtime_installer.os,
            "scandir",
            replace_parent_before_empty_enumeration,
        )
    else:
        external = tmp_path / "external-transactions"
        external.mkdir()
        transactions.rmdir()
        try:
            transactions.symlink_to(external, target_is_directory=True)
        except OSError as error:
            pytest.skip(f"directory links unavailable: {error}")

    with pytest.raises(
        ValueError,
        match="transaction_store|filesystem|directory|ancestor",
    ):
        runtime_installer._observe_exact_runtime_transaction_store(
            runtime_root,
            transaction_id=transaction_id,
            external_file_action=None,
        )


def _task9_runtime_layout_paths(
    capabilities: SimpleNamespace,
    *,
    state_key: str,
) -> tuple[Path, ...]:
    internal = capabilities.pipeline.runtime_root / ".hsconfig"
    return (
        capabilities.pipeline.runtime_root / "CustomConfig",
        internal / "transactions",
        internal / "staging",
        internal / "receipts",
        internal / "receipts" / state_key,
        internal / "attempt-retention",
        internal / "owner-retirements",
    )


def _task9_bind_runtime_layout_row(
    *,
    capabilities: SimpleNamespace,
    pair: object,
    cursor: object,
    runtime_admission: object,
) -> object:
    import hsconfig.live_start_session as live_start_session

    authorization = (
        live_start_session._authorize_runtime_layout_bootstrap_under_lock(
            session_lease=capabilities.session_lease,
            expected_layout_session=cursor,
            action="create_or_confirm_runtime_layout_directory",
        )
    )
    receipt = runtime_installer.bootstrap_runtime_layout_directory_from_pair(
        lease_pair=pair,
        session_lease=capabilities.session_lease,
        expected_layout_session=cursor,
        profile_lease=capabilities.profile_lease,
        output_operation_lease=capabilities.operation_lease,
        output_operation_admission=capabilities.operation_evidence,
        runtime_admission=runtime_admission,
        layout_authorization=authorization,
    )
    return live_start_session.advance_runtime_layout_bootstrap_under_lock(
        session_lease=capabilities.session_lease,
        expected_layout_session=cursor,
        transition="directory_bound",
        physical_step_receipt=receipt,
    )


def test_runtime_layout_bootstrap_fixed_order_and_existing_missing_rows(
    tmp_path: Path,
    monkeypatch: pytest.MonkeyPatch,
) -> None:
    import hsconfig.live_start_session as live_start_session

    with _controller_pair_capabilities(tmp_path, monkeypatch) as capabilities:
        with runtime_installer.lease_controller_apply_pair(
            **_pair_arguments(capabilities)
        ) as admission_pair:
            primary, runtime_admission = _drive_runtime_admission_with_pair(
                capabilities=capabilities,
                pair=admission_pair,
            )

        state_key = runtime_installer._state_key(primary.deck_name)
        paths = _task9_runtime_layout_paths(
            capabilities,
            state_key=state_key,
        )
        paths[0].mkdir()
        (paths[0] / "existing-card.json").write_bytes(b"{}\n")
        paths[1].mkdir()
        paths[3].mkdir()
        paths[4].mkdir()
        (paths[4] / "existing-receipt.json").write_bytes(b"{}\n")

        with runtime_installer.lease_controller_apply_pair(
            **_pair_arguments(
                capabilities,
                expected_session=primary,
                runtime_admission=runtime_admission,
            )
        ) as pair:
            before_invalid = {
                path.relative_to(capabilities.pipeline.runtime_root).as_posix()
                for path in capabilities.pipeline.runtime_root.rglob("*")
            }
            invalid_rows = (
                {
                    "transaction_id": "b" * 32,
                    "retention_owner_run_id": primary.run_id,
                    "runtime_admission": runtime_admission,
                    "state_key": state_key,
                },
                {
                    "transaction_id": runtime_admission.apply_attempt_id,
                    "retention_owner_run_id": "c" * 32,
                    "runtime_admission": runtime_admission,
                    "state_key": state_key,
                },
                {
                    "transaction_id": runtime_admission.apply_attempt_id,
                    "retention_owner_run_id": primary.run_id,
                    "runtime_admission": runtime_admission,
                    "state_key": "wrong-state-key",
                },
                {
                    "transaction_id": runtime_admission.apply_attempt_id,
                    "retention_owner_run_id": primary.run_id,
                    "runtime_admission": replace(
                        runtime_admission,
                        apply_attempt_id="d" * 32,
                    ),
                    "state_key": state_key,
                },
            )
            for invalid in invalid_rows:
                with pytest.raises((TypeError, ValueError)):
                    runtime_installer.observe_runtime_layout_bootstrap_from_pair(
                        lease_pair=pair,
                        **invalid,
                    )
                assert {
                    path.relative_to(
                        capabilities.pipeline.runtime_root
                    ).as_posix()
                    for path in capabilities.pipeline.runtime_root.rglob("*")
                } == before_invalid

            evidence = (
                runtime_installer.observe_runtime_layout_bootstrap_from_pair(
                    lease_pair=pair,
                    transaction_id=runtime_admission.apply_attempt_id,
                    retention_owner_run_id=primary.run_id,
                    runtime_admission=runtime_admission,
                    state_key=state_key,
                )
            )
            rows = evidence.value["directories"]
            assert tuple(row["role"] for row in rows) == (
                live_start_session.RUNTIME_LAYOUT_DIRECTORY_ROLES
            )
            assert tuple(Path(str(row["path"])) for row in rows) == paths
            assert tuple(row["predecessor_state"] for row in rows) == (
                "existing",
                "existing",
                "absent",
                "existing",
                "existing",
                "absent",
                "absent",
            )
            assert tuple(
                row["predecessor_identity"] for row in rows
            ) == tuple(
                path_identity(path) if path.exists() else None
                for path in paths
            )

            cursor = live_start_session.prepare_runtime_layout_bootstrap_under_lock(
                session_lease=capabilities.session_lease,
                expected_admission_committed_session=primary,
                layout_evidence=evidence,
            )
            for index, path in enumerate(paths):
                cursor = _task9_bind_runtime_layout_row(
                    capabilities=capabilities,
                    pair=pair,
                    cursor=cursor,
                    runtime_admission=runtime_admission,
                )
                assert cursor.runtime_layout_bootstrap is not None
                assert tuple(
                    cursor.runtime_layout_bootstrap["directories"][index][
                        "successor_identity"
                    ]
                ) == path_identity(path)

        assert cursor.runtime_layout_bootstrap is not None
        assert cursor.runtime_layout_bootstrap["stage"] == "COMPLETE"
        assert cursor.pending_transition is not None
        action = cursor.pending_transition["external_file_action"]
        assert action["planned_successor_size"] == (
            cursor.pending_transition["apply_invocation_document_size"]
        )
        assert action["planned_successor_sha256"] == (
            cursor.pending_transition["successor_artifact_bindings"][
                "receipts/apply_invocation.json"
            ]
        )


def test_runtime_layout_bootstrap_crash_after_each_directory_create_resumes_without_authority_file(
    tmp_path: Path,
    monkeypatch: pytest.MonkeyPatch,
) -> None:
    import hsconfig.live_start_session as live_start_session

    with _controller_pair_capabilities(tmp_path, monkeypatch) as capabilities:
        with runtime_installer.lease_controller_apply_pair(
            **_pair_arguments(capabilities)
        ) as admission_pair:
            primary, runtime_admission = _drive_runtime_admission_with_pair(
                capabilities=capabilities,
                pair=admission_pair,
            )
        state_key = runtime_installer._state_key(primary.deck_name)
        paths = _task9_runtime_layout_paths(
            capabilities,
            state_key=state_key,
        )
        with runtime_installer.lease_controller_apply_pair(
            **_pair_arguments(
                capabilities,
                expected_session=primary,
                runtime_admission=runtime_admission,
            )
        ) as pair:
            evidence = (
                runtime_installer.observe_runtime_layout_bootstrap_from_pair(
                    lease_pair=pair,
                    transaction_id=runtime_admission.apply_attempt_id,
                    retention_owner_run_id=primary.run_id,
                    runtime_admission=runtime_admission,
                    state_key=state_key,
                )
            )
            cursor = live_start_session.prepare_runtime_layout_bootstrap_under_lock(
                session_lease=capabilities.session_lease,
                expected_admission_committed_session=primary,
                layout_evidence=evidence,
            )
            for index, path in enumerate(paths):
                first_authorization = (
                    live_start_session._authorize_runtime_layout_bootstrap_under_lock(
                        session_lease=capabilities.session_lease,
                        expected_layout_session=cursor,
                        action=(
                            "create_or_confirm_runtime_layout_directory"
                        ),
                    )
                )
                runtime_installer.bootstrap_runtime_layout_directory_from_pair(
                    lease_pair=pair,
                    session_lease=capabilities.session_lease,
                    expected_layout_session=cursor,
                    profile_lease=capabilities.profile_lease,
                    output_operation_lease=capabilities.operation_lease,
                    output_operation_admission=capabilities.operation_evidence,
                    runtime_admission=runtime_admission,
                    layout_authorization=first_authorization,
                )
                assert path.is_dir()
                persisted = (
                    live_start_session.load_live_start_session_under_lock(
                        session_lease=capabilities.session_lease
                    )
                )
                assert persisted.content_sha256 == cursor.content_sha256
                assert not any(
                    candidate.name.endswith("layout-authority.json")
                    for candidate in capabilities.pipeline.runtime_root.rglob(
                        "*"
                    )
                )

                cursor = _task9_bind_runtime_layout_row(
                    capabilities=capabilities,
                    pair=pair,
                    cursor=cursor,
                    runtime_admission=runtime_admission,
                )
                assert cursor.runtime_layout_bootstrap is not None
                assert cursor.runtime_layout_bootstrap[
                    "next_directory_index"
                ] == index + 1
        assert all(path.is_dir() for path in paths)
        assert not any(
            candidate.suffix == ".json"
            for candidate in capabilities.pipeline.runtime_root.rglob("*")
            if candidate.is_file()
        )


@pytest.mark.parametrize(
    "case",
    ("parent_replacement", "reparse", "ads", "nonempty_created_child"),
)
def test_runtime_layout_bootstrap_rejects_parent_replacement_reparse_ads_and_nonempty_created_child(
    tmp_path: Path,
    monkeypatch: pytest.MonkeyPatch,
    case: str,
) -> None:
    import hsconfig.live_start_session as live_start_session

    with _controller_pair_capabilities(tmp_path, monkeypatch) as capabilities:
        with runtime_installer.lease_controller_apply_pair(
            **_pair_arguments(capabilities)
        ) as admission_pair:
            primary, runtime_admission = _drive_runtime_admission_with_pair(
                capabilities=capabilities,
                pair=admission_pair,
            )
        state_key = runtime_installer._state_key(primary.deck_name)
        paths = _task9_runtime_layout_paths(
            capabilities,
            state_key=state_key,
        )
        with runtime_installer.lease_controller_apply_pair(
            **_pair_arguments(
                capabilities,
                expected_session=primary,
                runtime_admission=runtime_admission,
            )
        ) as pair:
            evidence = (
                runtime_installer.observe_runtime_layout_bootstrap_from_pair(
                    lease_pair=pair,
                    transaction_id=runtime_admission.apply_attempt_id,
                    retention_owner_run_id=primary.run_id,
                    runtime_admission=runtime_admission,
                    state_key=state_key,
                )
            )
            cursor = live_start_session.prepare_runtime_layout_bootstrap_under_lock(
                session_lease=capabilities.session_lease,
                expected_admission_committed_session=primary,
                layout_evidence=evidence,
            )
            if case == "parent_replacement":
                for _index in range(4):
                    cursor = _task9_bind_runtime_layout_row(
                        capabilities=capabilities,
                        pair=pair,
                        cursor=cursor,
                        runtime_admission=runtime_admission,
                    )
                receipts = paths[3]
                held = receipts.with_name("receipts-held")
                receipts.rename(held)
                receipts.mkdir()
                attacked_path = paths[4]
            elif case == "reparse":
                external = (tmp_path / "external-layout-row").absolute()
                external.mkdir()
                attacked_path = paths[0]
                try:
                    attacked_path.symlink_to(
                        external,
                        target_is_directory=True,
                    )
                except OSError as error:
                    pytest.skip(f"directory links unavailable: {error}")
            elif case == "ads":
                attacked_path = paths[0]
                attacked_path.mkdir()
                _create_ntfs_stream_or_skip(attacked_path)
            else:
                attacked_path = paths[0]
                attacked_path.mkdir()
                (attacked_path / "foreign.txt").write_bytes(b"foreign\n")

            before = {
                path.relative_to(capabilities.pipeline.runtime_root).as_posix()
                for path in capabilities.pipeline.runtime_root.rglob("*")
            }
            authorization = (
                live_start_session._authorize_runtime_layout_bootstrap_under_lock(
                    session_lease=capabilities.session_lease,
                    expected_layout_session=cursor,
                    action="create_or_confirm_runtime_layout_directory",
                )
            )
            with pytest.raises(
                (OSError, RuntimeError, ValueError),
                match="layout|directory|parent|filesystem|stream|reparse|unsafe",
            ):
                runtime_installer.bootstrap_runtime_layout_directory_from_pair(
                    lease_pair=pair,
                    session_lease=capabilities.session_lease,
                    expected_layout_session=cursor,
                    profile_lease=capabilities.profile_lease,
                    output_operation_lease=capabilities.operation_lease,
                    output_operation_admission=capabilities.operation_evidence,
                    runtime_admission=runtime_admission,
                    layout_authorization=authorization,
                )
            if case == "parent_replacement":
                assert receipts.exists()
                assert held.exists()
                assert not attacked_path.exists()
            else:
                assert attacked_path.exists() or attacked_path.is_symlink()
            assert {
                path.relative_to(capabilities.pipeline.runtime_root).as_posix()
                for path in capabilities.pipeline.runtime_root.rglob("*")
            } == before
            persisted = live_start_session.load_live_start_session_under_lock(
                session_lease=capabilities.session_lease
            )
            assert persisted.content_sha256 == cursor.content_sha256


def test_initial_active_and_route_fence_commits_are_distinct_staged_rows(
    tmp_path: Path,
    monkeypatch: pytest.MonkeyPatch,
) -> None:
    import hsconfig.live_start_session as live_start_session

    fixture = _controller_pair_post_handoff_fixture(tmp_path, monkeypatch)
    with _controller_pair_reentry_capabilities(fixture) as capabilities:
        publication = capabilities.package_lease.publication
        assert publication is not None
        published_output = PublishedOutput(
            output_root=capabilities.package_lease.output_root,
            revision_root=capabilities.package_lease.package_root.parent,
            package_root=capabilities.package_lease.package_root,
            content_root_sha256=publication.content_root_sha256,
            reused_existing_revision=True,
        )
        plan = runtime_installer.plan_runtime_install(
            published_output=published_output,
            runtime_root=capabilities.pipeline.runtime_root,
        )
        with runtime_installer.lease_controller_apply_pair(
            **{
                **_pair_arguments(capabilities),
                "runtime_admission": fixture.runtime_admission,
            }
        ) as pair:
            authorization = (
                live_start_session._authorize_runtime_observation_under_lock(
                    session_lease=capabilities.session_lease,
                    expected_session=fixture.apply_started,
                    observation_family="first_install",
                    apply_attempt_id=fixture.runtime_admission.apply_attempt_id,
                )
            )
            receipt = runtime_installer.observe_initial_runtime_install_from_pair(
                plan,
                lease_pair=pair,
                observation_authorization=authorization,
                transaction_id=fixture.runtime_admission.apply_attempt_id,
                retention_owner_run_id=fixture.apply_started.run_id,
                runtime_admission=fixture.runtime_admission,
            )
            cursor = live_start_session.prepare_first_runtime_install_under_lock(
                session_lease=capabilities.session_lease,
                expected_apply_started_session=fixture.apply_started,
                runtime_observation_receipt=receipt,
            )
            action_rows: list[tuple[str, Path, bytes | None]] = []
            for expected_action in (
                "materialize_file_action_staging",
                "commit_bound_initial_attempt_record",
                "materialize_file_action_staging",
                "commit_bound_candidate_planned_attempt_record",
            ):
                recovery = cursor.apply_recovery
                assert recovery is not None
                assert recovery["expected_action"] == expected_action
                external = recovery["external_file_action"]
                assert external is not None
                for injected_path in (
                    Path(str(recovery["candidate_path"])),
                    Path(str(recovery["renamed_target_path"])),
                ):
                    injected_path.mkdir()
                    before_session = cursor.canonical_json
                    before_retention = (
                        fixture.runtime_admission.retention_fence_path.read_bytes()
                        if fixture.runtime_admission.retention_fence_path.exists()
                        else None
                    )
                    external_staging = Path(str(external["staging_path"]))
                    before_staging = (
                        external_staging.read_bytes()
                        if external_staging.exists()
                        else None
                    )
                    rejected = (
                        live_start_session._authorize_nonterminal_apply_recovery_under_lock(
                            session_lease=capabilities.session_lease,
                            expected_recovery_session=cursor,
                            expected_action=expected_action,
                        )
                    )
                    with pytest.raises(ValueError, match="target|surface"):
                        runtime_installer.recover_runtime_attempt_from_pair(
                            lease_pair=pair,
                            transaction_id=fixture.runtime_admission.apply_attempt_id,
                            expected_retention_owner_run_id=fixture.apply_started.run_id,
                            expected_package_root_sha256=(
                                fixture.runtime_admission.package_root_sha256
                            ),
                            expected_deck_name=plan.deck_name,
                            runtime_admission=fixture.runtime_admission,
                            nonterminal_recovery_authorization=rejected,
                        )
                    assert cursor.canonical_json == before_session
                    assert (
                        fixture.runtime_admission.retention_fence_path.read_bytes()
                        if fixture.runtime_admission.retention_fence_path.exists()
                        else None
                    ) == before_retention
                    assert (
                        external_staging.read_bytes()
                        if external_staging.exists()
                        else None
                    ) == before_staging
                    injected_path.rmdir()
                authorization = (
                    live_start_session._authorize_nonterminal_apply_recovery_under_lock(
                        session_lease=capabilities.session_lease,
                        expected_recovery_session=cursor,
                        expected_action=expected_action,
                    )
                )
                result = runtime_installer.recover_runtime_attempt_from_pair(
                    lease_pair=pair,
                    transaction_id=fixture.runtime_admission.apply_attempt_id,
                    expected_retention_owner_run_id=fixture.apply_started.run_id,
                    expected_package_root_sha256=(
                        fixture.runtime_admission.package_root_sha256
                    ),
                    expected_deck_name=plan.deck_name,
                    runtime_admission=fixture.runtime_admission,
                    nonterminal_recovery_authorization=authorization,
                )
                assert result.apply_recovery_step_receipt is not None
                staging_path = Path(str(external["staging_path"]))
                action_rows.append(
                    (
                        expected_action,
                        staging_path,
                        (
                            staging_path.read_bytes()
                            if expected_action
                            == "materialize_file_action_staging"
                            else None
                        ),
                    )
                )
                cursor = (
                    live_start_session.advance_nonterminal_apply_recovery_under_lock(
                        session_lease=capabilities.session_lease,
                        expected_recovery_session=cursor,
                        transition="physical_recovery_advanced",
                        recovery_evidence=None,
                        recovery_authorization=None,
                        physical_step_receipt=(
                            result.apply_recovery_step_receipt
                        ),
                        runtime_observation_receipt=None,
                    )
                )

        recovery = cursor.apply_recovery
        assert recovery is not None
        assert recovery["expected_action"] == "materialize_file_action_staging"
        assert recovery["install_route"] == "new_target"
        assert recovery["candidate_path"] == str(
            capabilities.pipeline.runtime_root
            / ".hsconfig"
            / "staging"
            / fixture.runtime_admission.apply_attempt_id
        )
        assert recovery["predecessor_candidate_identity"] is None
        assert recovery["successor_candidate_identity"] is None
        for name, value in recovery.items():
            if name.startswith("candidate_tree_"):
                assert value is None
        retention_path = fixture.runtime_admission.retention_fence_path
        record = runtime_installer._runtime_attempt_retention_from_raw(
            retention_path.read_bytes(),
            runtime_root=capabilities.pipeline.runtime_root,
        )
        assert record.state == "CANDIDATE_PLANNED"
        assert record.package_root_sha256 == (
            "sha256:" + plan.package_root_sha256
        )
        assert record.candidate_path == Path(str(recovery["candidate_path"]))
        assert record.candidate_identity is None
        assert record.owns_target is False
        journal_path = runtime_transaction_journal_path(
            capabilities.pipeline.runtime_root,
            fixture.runtime_admission.apply_attempt_id,
        )
        assert record.planned_journal_path == journal_path
        layout = cursor.runtime_layout_bootstrap
        assert layout is not None
        layout_directories = layout["directories"]
        assert isinstance(layout_directories, (list, tuple))
        state_receipt_row = layout_directories[4]
        assert isinstance(state_receipt_row, Mapping)
        state_key = Path(str(state_receipt_row["path"])).name
        assert state_key == runtime_installer._state_key(plan.deck_name)
        planned_raw = runtime_installer._planned_prepared_runtime_journal_bytes(
            plan,
            transaction_id=fixture.runtime_admission.apply_attempt_id,
            state_key=state_key,
        )
        assert record.planned_journal_size == len(planned_raw)
        assert record.planned_journal_sha256 == (
            "sha256:" + hashlib.sha256(planned_raw).hexdigest()
        )
        assert not journal_path.exists()
        assert not Path(str(recovery["candidate_path"])).exists()
        target_path = (
            capabilities.pipeline.runtime_root
            / "CustomConfig"
            / plan.versioned_config_dir
        )
        assert not target_path.exists()
        later_v1 = recovery["external_file_action"]
        assert later_v1 is not None
        assert later_v1["stage"] == "PLANNED"
        assert later_v1["action_kind"] == "materialize_file_action_staging"
        assert later_v1["final_path"] == str(journal_path)
        assert later_v1["predecessor_state"] == "absent"
        assert later_v1["planned_successor_size"] == len(planned_raw)
        assert later_v1["planned_successor_sha256"] == (
            "sha256:" + hashlib.sha256(planned_raw).hexdigest()
        )
        assert [row[0] for row in action_rows] == [
            "materialize_file_action_staging",
            "commit_bound_initial_attempt_record",
            "materialize_file_action_staging",
            "commit_bound_candidate_planned_attempt_record",
        ]
        assert action_rows[0][1] == action_rows[1][1]
        assert action_rows[2][1] == action_rows[3][1]
        assert action_rows[0][2] is not None
        assert action_rows[2][2] is not None
        assert action_rows[0][2] != action_rows[2][2]


@pytest.mark.parametrize(
    "crash_action",
    (
        "commit_bound_initial_attempt_record",
        "commit_bound_candidate_planned_attempt_record",
    ),
)
def test_initial_route_fence_commit_action_before_cas_confirms_exact_final_only(
    tmp_path: Path,
    monkeypatch: pytest.MonkeyPatch,
    crash_action: str,
) -> None:
    import hsconfig.live_start_session as live_start_session

    fixture = _controller_pair_post_handoff_fixture(tmp_path, monkeypatch)
    with _controller_pair_reentry_capabilities(fixture) as capabilities:
        publication = capabilities.package_lease.publication
        assert publication is not None
        published = PublishedOutput(
            output_root=capabilities.package_lease.output_root,
            revision_root=capabilities.package_lease.package_root.parent,
            package_root=capabilities.package_lease.package_root,
            content_root_sha256=publication.content_root_sha256,
            reused_existing_revision=True,
        )
        plan = plan_runtime_install(
            published_output=published,
            runtime_root=capabilities.pipeline.runtime_root,
        )
        with runtime_installer.lease_controller_apply_pair(
            **{
                **_pair_arguments(capabilities),
                "runtime_admission": fixture.runtime_admission,
            }
        ) as pair:
            observation_authorization = (
                live_start_session._authorize_runtime_observation_under_lock(
                    session_lease=capabilities.session_lease,
                    expected_session=fixture.apply_started,
                    observation_family="first_install",
                    apply_attempt_id=fixture.runtime_admission.apply_attempt_id,
                )
            )
            observation_receipt = (
                runtime_installer.observe_initial_runtime_install_from_pair(
                    plan,
                    lease_pair=pair,
                    observation_authorization=observation_authorization,
                    transaction_id=fixture.runtime_admission.apply_attempt_id,
                    retention_owner_run_id=fixture.apply_started.run_id,
                    runtime_admission=fixture.runtime_admission,
                )
            )
            cursor = live_start_session.prepare_first_runtime_install_under_lock(
                session_lease=capabilities.session_lease,
                expected_apply_started_session=fixture.apply_started,
                runtime_observation_receipt=observation_receipt,
            )
            while True:
                recovery = cursor.apply_recovery
                assert recovery is not None
                action = str(recovery["expected_action"])
                authorization = (
                    live_start_session._authorize_nonterminal_apply_recovery_under_lock(
                        session_lease=capabilities.session_lease,
                        expected_recovery_session=cursor,
                        expected_action=action,
                    )
                )
                first = runtime_installer.recover_runtime_attempt_from_pair(
                    lease_pair=pair,
                    transaction_id=fixture.runtime_admission.apply_attempt_id,
                    expected_retention_owner_run_id=fixture.apply_started.run_id,
                    expected_package_root_sha256=fixture.runtime_admission.package_root_sha256,
                    expected_deck_name=plan.deck_name,
                    runtime_admission=fixture.runtime_admission,
                    nonterminal_recovery_authorization=authorization,
                )
                assert first.apply_recovery_step_receipt is not None
                if action == crash_action:
                    stale_raw = cursor.canonical_json
                    final_path = Path(
                        str(recovery["external_file_action"]["final_path"])
                    )
                    exact_final = (
                        path_identity(final_path),
                        final_path.read_bytes(),
                    )
                    with pytest.raises(
                        live_start_session.SessionCapabilityError,
                        match="consumed|capability",
                    ):
                        runtime_installer.recover_runtime_attempt_from_pair(
                            lease_pair=pair,
                            transaction_id=fixture.runtime_admission.apply_attempt_id,
                            expected_retention_owner_run_id=fixture.apply_started.run_id,
                            expected_package_root_sha256=fixture.runtime_admission.package_root_sha256,
                            expected_deck_name=plan.deck_name,
                            runtime_admission=fixture.runtime_admission,
                            nonterminal_recovery_authorization=authorization,
                        )
                    assert (
                        path_identity(final_path),
                        final_path.read_bytes(),
                    ) == exact_final
                    retry_authorization = (
                        live_start_session._authorize_nonterminal_apply_recovery_under_lock(
                            session_lease=capabilities.session_lease,
                            expected_recovery_session=cursor,
                            expected_action=action,
                        )
                    )
                    retry = runtime_installer.recover_runtime_attempt_from_pair(
                        lease_pair=pair,
                        transaction_id=fixture.runtime_admission.apply_attempt_id,
                        expected_retention_owner_run_id=fixture.apply_started.run_id,
                        expected_package_root_sha256=fixture.runtime_admission.package_root_sha256,
                        expected_deck_name=plan.deck_name,
                        runtime_admission=fixture.runtime_admission,
                        nonterminal_recovery_authorization=retry_authorization,
                    )
                    assert retry.apply_recovery_step_receipt is not None
                    assert cursor.canonical_json == stale_raw
                    cursor = live_start_session.advance_nonterminal_apply_recovery_under_lock(
                        session_lease=capabilities.session_lease,
                        expected_recovery_session=cursor,
                        transition="physical_recovery_advanced",
                        recovery_evidence=None,
                        recovery_authorization=None,
                        physical_step_receipt=retry.apply_recovery_step_receipt,
                        runtime_observation_receipt=None,
                    )
                    break
                cursor = live_start_session.advance_nonterminal_apply_recovery_under_lock(
                    session_lease=capabilities.session_lease,
                    expected_recovery_session=cursor,
                    transition="physical_recovery_advanced",
                    recovery_evidence=None,
                    recovery_authorization=None,
                    physical_step_receipt=first.apply_recovery_step_receipt,
                    runtime_observation_receipt=None,
                )


@pytest.mark.parametrize(
    "layout_index",
    range(7),
)
def test_initial_observation_rejects_replaced_complete_layout_successor(
    tmp_path: Path,
    monkeypatch: pytest.MonkeyPatch,
    layout_index: int,
) -> None:
    import hsconfig.live_start_session as live_start_session

    fixture = _controller_pair_post_handoff_fixture(tmp_path, monkeypatch)
    with _controller_pair_reentry_capabilities(fixture) as capabilities:
        publication = capabilities.package_lease.publication
        assert publication is not None
        published = PublishedOutput(
            output_root=capabilities.package_lease.output_root,
            revision_root=capabilities.package_lease.package_root.parent,
            package_root=capabilities.package_lease.package_root,
            content_root_sha256=publication.content_root_sha256,
            reused_existing_revision=True,
        )
        plan = plan_runtime_install(
            published_output=published,
            runtime_root=capabilities.pipeline.runtime_root,
        )
        layout = fixture.apply_started.runtime_layout_bootstrap
        assert layout is not None
        attacked = Path(str(layout["directories"][layout_index]["path"]))
        held = attacked.with_name(f"{attacked.name}-held")
        attacked.rename(held)
        attacked.mkdir()
        before_session = fixture.apply_started.canonical_json
        with runtime_installer.lease_controller_apply_pair(
            **{
                **_pair_arguments(capabilities),
                "runtime_admission": fixture.runtime_admission,
            }
        ) as pair:
            authorization = (
                live_start_session._authorize_runtime_observation_under_lock(
                    session_lease=capabilities.session_lease,
                    expected_session=fixture.apply_started,
                    observation_family="first_install",
                    apply_attempt_id=fixture.runtime_admission.apply_attempt_id,
                )
            )
            with pytest.raises(ValueError, match="layout|directory|identity"):
                runtime_installer.observe_initial_runtime_install_from_pair(
                    plan,
                    lease_pair=pair,
                    observation_authorization=authorization,
                    transaction_id=fixture.runtime_admission.apply_attempt_id,
                    retention_owner_run_id=fixture.apply_started.run_id,
                    runtime_admission=fixture.runtime_admission,
                )
        assert fixture.apply_started.canonical_json == before_session
        assert not fixture.runtime_admission.retention_fence_path.exists()
        assert attacked.is_dir()
        assert held.is_dir()


def _exercise_candidate_bound_prefix(
    tmp_path: Path,
    monkeypatch: pytest.MonkeyPatch,
    *,
    source_extra_kind: str | None = None,
    source_extra_before_fence_commit: str | None = None,
    bounded_scandir_probe: dict[str, int] | None = None,
    through_owner_bind: bool = False,
    through_committed: bool = False,
    committed_drift: str | None = None,
    replace_suffix_parent_role: str | None = None,
    transactions_parent_race: str | None = None,
    cutover_attack: str | None = None,
    stop_before_action: str | None = None,
    stop_after_action: str | None = None,
    stop_after_candidate_rename: bool = False,
    seed_stale_owned_revision: bool = False,
    existing_child_precondition: bool = False,
    fixture: SimpleNamespace | None = None,
    resume_cursor: Any | None = None,
    initial_actions: tuple[str, ...] = (),
    stop_after_physical_before_cas: tuple[str, ...] = (),
) -> SimpleNamespace:
    import hsconfig.live_start_session as live_start_session

    if resume_cursor is not None and fixture is None:
        raise AssertionError("resumed candidate helper requires its original fixture")
    if resume_cursor is None and initial_actions:
        raise AssertionError("fresh candidate helper cannot inherit action rows")
    if fixture is None:
        fixture = _controller_pair_post_handoff_fixture(
            tmp_path,
            monkeypatch,
            seed_stale_owned_revision=seed_stale_owned_revision,
            existing_child_precondition=existing_child_precondition,
        )
    with _controller_pair_reentry_capabilities(
        fixture,
        expected_session=resume_cursor,
    ) as capabilities:
        publication = capabilities.package_lease.publication
        assert publication is not None
        published = PublishedOutput(
            output_root=capabilities.package_lease.output_root,
            revision_root=capabilities.package_lease.package_root.parent,
            package_root=capabilities.package_lease.package_root,
            content_root_sha256=publication.content_root_sha256,
            reused_existing_revision=True,
        )
        plan = plan_runtime_install(
            published_output=published,
            runtime_root=capabilities.pipeline.runtime_root,
        )
        with runtime_installer.lease_controller_apply_pair(
            **{
                **_pair_arguments(capabilities),
                "runtime_admission": fixture.runtime_admission,
            }
        ) as pair:
            if resume_cursor is None:
                observation_authorization = (
                    live_start_session._authorize_runtime_observation_under_lock(
                        session_lease=capabilities.session_lease,
                        expected_session=fixture.apply_started,
                        observation_family="first_install",
                        apply_attempt_id=fixture.runtime_admission.apply_attempt_id,
                    )
                )
                receipt = runtime_installer.observe_initial_runtime_install_from_pair(
                    plan,
                    lease_pair=pair,
                    observation_authorization=observation_authorization,
                    transaction_id=fixture.runtime_admission.apply_attempt_id,
                    retention_owner_run_id=fixture.apply_started.run_id,
                    runtime_admission=fixture.runtime_admission,
                )
                cursor = live_start_session.prepare_first_runtime_install_under_lock(
                    session_lease=capabilities.session_lease,
                    expected_apply_started_session=fixture.apply_started,
                    runtime_observation_receipt=receipt,
                )
            else:
                cursor = capabilities.prepared_session
                assert cursor.canonical_json == resume_cursor.canonical_json
                assert cursor.session_identity == resume_cursor.session_identity
            actions: list[str] = list(initial_actions)
            while True:
                recovery = cursor.apply_recovery
                assert recovery is not None
                action = str(recovery["expected_action"])
                if action == stop_before_action:
                    return SimpleNamespace(
                        cursor=cursor,
                        recovery=recovery,
                        actions=actions,
                        plan=plan,
                        fixture=fixture,
                    )
                if action == "observe_committed" and committed_drift is not None:
                    runtime_root = Path(str(recovery["runtime_root"]))
                    if committed_drift == "target":
                        target = Path(str(recovery["renamed_target_path"]))
                        victim = next(path for path in target.rglob("*") if path.is_file())
                    elif committed_drift == "ini":
                        victim = runtime_root / "CustomConfig" / "deck_config.ini"
                    elif committed_drift == "state":
                        victim = runtime_root / ".hsconfig" / "state.json"
                    else:
                        journal = runtime_installer._bound_recovery_journal(recovery)
                        victim = runtime_installer._receipt_path(
                            runtime_root, journal.state_key
                        )
                    victim.write_bytes(victim.read_bytes() + b"drift")
                    before_session = cursor.canonical_json
                    authorization = live_start_session._authorize_nonterminal_apply_recovery_under_lock(
                        session_lease=capabilities.session_lease,
                        expected_recovery_session=cursor,
                        expected_action=action,
                    )
                    with pytest.raises(
                        ValueError,
                        match="changed|invalid|mismatch|forbidden",
                    ):
                        runtime_installer.recover_runtime_attempt_from_pair(
                            lease_pair=pair,
                            transaction_id=fixture.runtime_admission.apply_attempt_id,
                            expected_retention_owner_run_id=fixture.apply_started.run_id,
                            expected_package_root_sha256=fixture.runtime_admission.package_root_sha256,
                            expected_deck_name=plan.deck_name,
                            runtime_admission=fixture.runtime_admission,
                            nonterminal_recovery_authorization=authorization,
                        )
                    persisted_after = live_start_session.load_live_start_session_under_lock(
                        session_lease=capabilities.session_lease
                    )
                    assert persisted_after.canonical_json == before_session
                    return SimpleNamespace(cursor=cursor, recovery=recovery)
                external = recovery.get("external_file_action")
                if (
                    stop_after_candidate_rename
                    and action == "materialize_file_action_staging"
                    and recovery.get("successor_renamed_target_identity") is not None
                    and isinstance(external, Mapping)
                    and external.get("stage") == "PLANNED"
                    and Path(str(external.get("final_path"))).name.endswith(".json")
                ):
                    return SimpleNamespace(
                        cursor=cursor,
                        recovery=recovery,
                        actions=actions,
                        plan=plan,
                        fixture=fixture,
                    )
                if (
                    transactions_parent_race == "plan"
                    and action == "verify_candidate_tree"
                ):
                    real_plan = runtime_installer._plan_journal_successor
                    transactions = Path(str(recovery["successor_journal_path"])).parent
                    held = transactions.with_name("transactions.plan-race-held")

                    def replace_before_plan(*args: object, **kwargs: object) -> object:
                        os.rename(transactions, held)
                        transactions.mkdir()
                        return real_plan(*args, **kwargs)

                    monkeypatch.setattr(
                        runtime_installer,
                        "_plan_journal_successor",
                        replace_before_plan,
                    )
                    before_session = cursor.canonical_json
                    authorization = live_start_session._authorize_nonterminal_apply_recovery_under_lock(
                        session_lease=capabilities.session_lease,
                        expected_recovery_session=cursor,
                        expected_action=action,
                    )
                    with pytest.raises(ValueError, match="parent|replaced|changed"):
                        runtime_installer.recover_runtime_attempt_from_pair(
                            lease_pair=pair,
                            transaction_id=fixture.runtime_admission.apply_attempt_id,
                            expected_retention_owner_run_id=fixture.apply_started.run_id,
                            expected_package_root_sha256=fixture.runtime_admission.package_root_sha256,
                            expected_deck_name=plan.deck_name,
                            runtime_admission=fixture.runtime_admission,
                            nonterminal_recovery_authorization=authorization,
                        )
                    assert cursor.canonical_json == before_session
                    return SimpleNamespace(cursor=cursor, recovery=recovery)
                if (
                    transactions_parent_race == "post_commit"
                    and action == "commit_ini_journal"
                ):
                    real_commit = runtime_installer._execute_bound_controller_journal_action
                    transactions = Path(str(recovery["successor_journal_path"])).parent
                    held = transactions.with_name("transactions.commit-race-held")

                    def replace_after_commit(*args: object, **kwargs: object) -> object:
                        committed = real_commit(*args, **kwargs)
                        os.rename(transactions, held)
                        transactions.mkdir()
                        return committed

                    monkeypatch.setattr(
                        runtime_installer,
                        "_execute_bound_controller_journal_action",
                        replace_after_commit,
                    )
                    before_session = cursor.canonical_json
                    authorization = live_start_session._authorize_nonterminal_apply_recovery_under_lock(
                        session_lease=capabilities.session_lease,
                        expected_recovery_session=cursor,
                        expected_action=action,
                    )
                    with pytest.raises(ValueError, match="parent|replaced|changed"):
                        runtime_installer.recover_runtime_attempt_from_pair(
                            lease_pair=pair,
                            transaction_id=fixture.runtime_admission.apply_attempt_id,
                            expected_retention_owner_run_id=fixture.apply_started.run_id,
                            expected_package_root_sha256=fixture.runtime_admission.package_root_sha256,
                            expected_deck_name=plan.deck_name,
                            runtime_admission=fixture.runtime_admission,
                            nonterminal_recovery_authorization=authorization,
                        )
                    assert cursor.canonical_json == before_session
                    return SimpleNamespace(cursor=cursor, recovery=recovery)
                parent_attack_action = {
                    "custom_config": "bind_renamed_target",
                    "metadata_root": "commit_ini_journal",
                    "state_receipts": "commit_state_journal",
                    "attempt_retention": "finalize_journal",
                }.get(replace_suffix_parent_role)
                transactions_attack = (
                    replace_suffix_parent_role == "transactions"
                    and action == "materialize_file_action_staging"
                    and isinstance(external, Mapping)
                    and Path(str(external["final_path"])).parent.name
                    == "transactions"
                    and recovery.get("successor_renamed_target_identity")
                    is not None
                )
                if action == parent_attack_action or transactions_attack:
                    runtime_root = Path(str(recovery["runtime_root"]))
                    parent = {
                        "custom_config": runtime_root / "CustomConfig",
                        "metadata_root": runtime_root / ".hsconfig",
                        "state_receipts": Path(
                            str(
                                live_start_session._thaw(
                                    cursor.runtime_layout_bootstrap
                                )["directories"][4]["path"]
                            )
                        ),
                        "transactions": runtime_root / ".hsconfig" / "transactions",
                        "attempt_retention": runtime_root
                        / ".hsconfig"
                        / "attempt-retention",
                    }[str(replace_suffix_parent_role)]
                    held = parent.with_name(f"{parent.name}.held-parent")
                    if replace_suffix_parent_role == "metadata_root":
                        real_path_identity = runtime_installer.path_identity
                        replacement_identity = (
                            real_path_identity(parent)[0],
                            real_path_identity(parent)[1] + 1,
                            real_path_identity(parent)[2],
                        )

                        def replaced_metadata_identity(path: Path) -> tuple[int, int, int]:
                            if Path(path) == parent:
                                return replacement_identity
                            return real_path_identity(Path(path))

                        monkeypatch.setattr(
                            runtime_installer,
                            "path_identity",
                            replaced_metadata_identity,
                        )
                    else:
                        os.rename(parent, held)
                        parent.mkdir()
                    before_session = cursor.canonical_json
                    authorization = live_start_session._authorize_nonterminal_apply_recovery_under_lock(
                        session_lease=capabilities.session_lease,
                        expected_recovery_session=cursor,
                        expected_action=action,
                    )
                    with pytest.raises(
                        (ValueError, RuntimeError),
                        match=(
                            "parent|changed|missing|invalid|manifest|package|"
                            "conflict|replaced"
                        ),
                    ):
                        runtime_installer.recover_runtime_attempt_from_pair(
                            lease_pair=pair,
                            transaction_id=fixture.runtime_admission.apply_attempt_id,
                            expected_retention_owner_run_id=fixture.apply_started.run_id,
                            expected_package_root_sha256=fixture.runtime_admission.package_root_sha256,
                            expected_deck_name=plan.deck_name,
                            runtime_admission=fixture.runtime_admission,
                            nonterminal_recovery_authorization=authorization,
                        )
                    persisted_after = live_start_session.load_live_start_session_under_lock(
                        session_lease=capabilities.session_lease
                    )
                    assert persisted_after.canonical_json == before_session
                    return SimpleNamespace(cursor=cursor, recovery=recovery)
                if (
                    through_owner_bind
                    and not through_committed
                    and action == "materialize_file_action_staging"
                    and isinstance(external, Mapping)
                    and Path(str(external.get("final_path"))).name
                    == "deck_config.ini"
                    and recovery.get("successor_renamed_target_identity") is not None
                ):
                    break
                if through_committed and action == "None":
                    break
                if action == "materialize_candidate_tree_entry" and not through_owner_bind:
                    break
                actions.append(action)
                if (
                    cutover_attack == "after_verify_before_rename"
                    and action == "rename_candidate_to_target"
                ):
                    manifest, _digest = runtime_installer._candidate_manifest_from_pair(
                        package_lease=capabilities.package_lease,
                        deck_name=plan.deck_name,
                    )
                    file_row = next(
                        row for row in manifest["entries"] if row["kind"] == "file"
                    )
                    relative = Path(str(file_row["relative_path"]))
                    source = (
                        capabilities.package_lease.package_root
                        / "CustomConfig"
                        / plan.logical_config_dir
                        / relative
                    )
                    source_raw = source.read_bytes()
                    source.write_bytes(source_raw + b"drift")
                    candidate = Path(str(recovery["candidate_path"]))
                    target = Path(str(recovery["renamed_target_path"]))
                    journal = Path(str(recovery["successor_journal_path"]))
                    before_session = cursor.canonical_json
                    before_candidate = runtime_installer.path_identity(candidate)
                    before_journal_identity = runtime_installer.path_identity(journal)
                    before_journal = journal.read_bytes()
                    assert not target.exists()
                    authorization = live_start_session._authorize_nonterminal_apply_recovery_under_lock(
                        session_lease=capabilities.session_lease,
                        expected_recovery_session=cursor,
                        expected_action=action,
                    )
                    with pytest.raises(
                        ValueError,
                        match="filesystem_file_invalid|package|verified|manifest|changed",
                    ):
                        runtime_installer.recover_runtime_attempt_from_pair(
                            lease_pair=pair,
                            transaction_id=fixture.runtime_admission.apply_attempt_id,
                            expected_retention_owner_run_id=fixture.apply_started.run_id,
                            expected_package_root_sha256=fixture.runtime_admission.package_root_sha256,
                            expected_deck_name=plan.deck_name,
                            runtime_admission=fixture.runtime_admission,
                            nonterminal_recovery_authorization=authorization,
                        )
                    assert cursor.canonical_json == before_session
                    assert runtime_installer.path_identity(candidate) == before_candidate
                    assert not target.exists()
                    assert runtime_installer.path_identity(journal) == before_journal_identity
                    assert journal.read_bytes() == before_journal
                    source.write_bytes(source_raw)
                    return SimpleNamespace(cursor=cursor, recovery=recovery, actions=actions)
                if (
                    cutover_attack == "after_rename_before_owner"
                    and action == "bind_renamed_target"
                ):
                    manifest, _digest = runtime_installer._candidate_manifest_from_pair(
                        package_lease=capabilities.package_lease,
                        deck_name=plan.deck_name,
                    )
                    file_row = next(
                        row for row in manifest["entries"] if row["kind"] == "file"
                    )
