def test_candidate_create_or_confirm_rejects_nonempty_replaced_wrong_parent_and_unsafe_candidate(
    tmp_path: Path,
    monkeypatch: pytest.MonkeyPatch,
) -> None:
    result = _exercise_candidate_bound_prefix(
        tmp_path,
        monkeypatch,
        stop_before_action="bind_created_candidate",
    )
    recovery = result.recovery
    assert recovery["expected_action"] == "bind_created_candidate"
    candidate = Path(str(recovery["candidate_path"]))
    assert not os.path.lexists(candidate)
    candidate.mkdir()
    (candidate / "foreign.txt").write_bytes(b"foreign\n")
    with pytest.raises(ValueError, match="directory|empty|unsafe"):
        runtime_installer._execute_created_candidate_action(recovery=recovery)
    (candidate / "foreign.txt").unlink()
    candidate.rmdir()
    candidate.write_bytes(b"not-a-directory\n")
    with pytest.raises((OSError, ValueError), match="directory|filesystem"):
        runtime_installer._execute_created_candidate_action(recovery=recovery)
    candidate.unlink()
    parent = candidate.parent
    held = parent.with_name(f"{parent.name}-held")
    parent.rename(held)
    parent.mkdir()
    with pytest.raises(ValueError, match="parent|cursor"):
        runtime_installer._execute_created_candidate_action(recovery=recovery)
    assert not candidate.exists()


def test_candidate_identity_receipt_cas_precedes_candidate_fence_commit(
    tmp_path: Path,
    monkeypatch: pytest.MonkeyPatch,
) -> None:
    result = _exercise_candidate_bound_prefix(tmp_path, monkeypatch)
    candidate_index = result.actions.index("bind_created_candidate")
    fence_materialize_index = result.actions.index(
        "materialize_file_action_staging",
        candidate_index + 1,
    )
    fence_index = result.actions.index("bind_candidate_fence")
    assert candidate_index < fence_materialize_index < fence_index
    assert result.recovery["candidate_tree_cursor"] == 0


