def test_candidate_same_byte_safe_replacement_is_content_equivalent(
    tmp_path: Path,
    monkeypatch: pytest.MonkeyPatch,
) -> None:
    def replace_leaf_after_crash(
        _action: str,
        crashed: SimpleNamespace,
    ) -> None:
        leaf = Path(str(crashed.recovery["candidate_path"])) / Path(
            str(crashed.recovery["candidate_tree_next_relative_path"])
        )
        if not leaf.is_file():
            pytest.skip("same-byte replacement requires a file manifest row")
        raw = leaf.read_bytes()
        predecessor_identity = path_identity(leaf)
        leaf.unlink()
        leaf.write_bytes(raw)
        if path_identity(leaf) == predecessor_identity:
            pytest.skip("filesystem reused same-byte leaf identity")

    result = _exercise_candidate_bound_prefix_with_process_replays(
        tmp_path,
        monkeypatch,
        through_owner_bind=True,
        replay_actions=("materialize_candidate_tree_entry",),
        after_physical_crash=replace_leaf_after_crash,
    )
    assert result.recovery["successor_renamed_target_identity"] is not None


@pytest.mark.parametrize(
    "attack",
    (
        "wrong_bytes",
        "source_drift",
        "candidate_parent_replacement",
        "candidate_root_replacement",
        "extra_membership",
        "hardlink",
        "ads",
        "reparse",
    ),
)
def test_candidate_leaf_rejects_wrong_bytes_source_parent_root_extra_hardlink_ads_or_reparse(
    tmp_path: Path,
    monkeypatch: pytest.MonkeyPatch,
    attack: str,
) -> None:
    import hsconfig.live_start_session as live_start_session

    assert "expected_parent_identity" in inspect.signature(
        runtime_installer._verify_candidate_tree_prefix
    ).parameters
    crashed = _exercise_candidate_bound_prefix(
        tmp_path,
        monkeypatch,
        through_owner_bind=True,
        stop_after_physical_before_cas=("materialize_candidate_tree_entry",),
    )
    assert crashed.crashed_action == "materialize_candidate_tree_entry"
    assert crashed.recovery["candidate_tree_cursor"] == 0
    evidence: SimpleNamespace | None = None
    try:
        with _controller_pair_reentry_capabilities(
            crashed.fixture,
            expected_session=crashed.cursor,
        ) as capabilities:
            with runtime_installer.lease_controller_apply_pair(
                **{
                    **_pair_arguments(capabilities),
                    "runtime_admission": crashed.fixture.runtime_admission,
                }
            ) as pair:
                evidence = _apply_candidate_leaf_attack_after_process_crash(
                    crashed,
                    attack=attack,
                )
                authorization = (
                    live_start_session._authorize_nonterminal_apply_recovery_under_lock(
                        session_lease=capabilities.session_lease,
                        expected_recovery_session=crashed.cursor,
                        expected_action="materialize_candidate_tree_entry",
                    )
                )
                with pytest.raises(
                    ValueError,
                    match={
                        "wrong_bytes": (
                            "leaf|prefix|changed|"
                            "filesystem_alternate_data_stream_forbidden"
                        ),
                        "source_drift": (
                            "source|package|changed|filesystem_file_invalid"
                        ),
                        "candidate_parent_replacement": "layout|parent|replaced",
                        "candidate_root_replacement": (
                            "candidate|prefix|replaced|changed"
                        ),
                        "extra_membership": (
                            "candidate|prefix|membership|changed"
                        ),
                        "hardlink": (
                            "hardlink|link|candidate|prefix|filesystem"
                        ),
                        "ads": "alternate|stream|candidate|prefix|filesystem",
                        "reparse": "reparse|candidate|prefix|filesystem",
                    }[attack],
                ):
                    runtime_installer.recover_runtime_attempt_from_pair(
                        lease_pair=pair,
                        transaction_id=(
                            crashed.fixture.runtime_admission.apply_attempt_id
                        ),
                        expected_retention_owner_run_id=(
                            crashed.fixture.apply_started.run_id
                        ),
                        expected_package_root_sha256=(
                            crashed.fixture.runtime_admission.package_root_sha256
                        ),
                        expected_deck_name=crashed.plan.deck_name,
                        runtime_admission=crashed.fixture.runtime_admission,
                        nonterminal_recovery_authorization=authorization,
                    )
                persisted = live_start_session.load_live_start_session_under_lock(
                    session_lease=capabilities.session_lease
                )
                assert persisted.canonical_json == crashed.cursor.canonical_json
                _assert_candidate_leaf_attack_did_not_mutate(evidence)
    finally:
        if evidence is not None:
            evidence.restore()


