def test_candidate_rename_remint_rejects_replaced_persisted_parent_before_receipt_cas(
    tmp_path: Path,
    monkeypatch: pytest.MonkeyPatch,
) -> None:
    import hsconfig.live_start_session as live_start_session

    crashed = _exercise_candidate_bound_prefix(
        tmp_path,
        monkeypatch,
        through_owner_bind=True,
        stop_after_physical_before_cas=("rename_candidate_to_target",),
    )
    assert crashed.recovery["expected_action"] == "rename_candidate_to_target"
    candidate_path = Path(str(crashed.recovery["candidate_path"]))
    target_path = Path(str(crashed.recovery["renamed_target_path"]))
    assert not candidate_path.exists()
    target_identity = runtime_installer.path_identity(target_path)
    candidate_parent = candidate_path.parent
    held_parent = candidate_parent.with_name(
        candidate_parent.name + ".held-remint-parent"
    )
    session_path = crashed.fixture.pipeline.session_root / "session.json"
    session_before = session_path.read_bytes()
    try:
        with _controller_pair_reentry_capabilities(
            crashed.fixture,
            expected_session=crashed.cursor,
        ) as capabilities:
            with runtime_installer.lease_controller_apply_pair(
                **{
                    **_pair_arguments(capabilities),
                    "runtime_admission": crashed.fixture.runtime_admission,
                }
            ) as pair:
                candidate_parent.rename(held_parent)
                candidate_parent.mkdir()
                authorization = (
                    live_start_session._authorize_nonterminal_apply_recovery_under_lock(
                        session_lease=capabilities.session_lease,
                        expected_recovery_session=crashed.cursor,
                        expected_action="rename_candidate_to_target",
                    )
                )
                with pytest.raises(
                    ValueError,
                    match="parent|layout|candidate|changed|replaced",
                ):
                    runtime_installer.recover_runtime_attempt_from_pair(
                        lease_pair=pair,
                        transaction_id=(
                            crashed.fixture.runtime_admission.apply_attempt_id
                        ),
                        expected_retention_owner_run_id=(
                            crashed.fixture.apply_started.run_id
                        ),
                        expected_package_root_sha256=(
                            crashed.fixture.runtime_admission.package_root_sha256
                        ),
                        expected_deck_name=crashed.plan.deck_name,
                        runtime_admission=crashed.fixture.runtime_admission,
                        nonterminal_recovery_authorization=authorization,
                    )
                persisted = live_start_session.load_live_start_session_under_lock(
                    session_lease=capabilities.session_lease
                )
                assert persisted.canonical_json == crashed.cursor.canonical_json
                assert session_path.read_bytes() == session_before
                assert (
                    runtime_installer.path_identity(target_path)
                    == target_identity
                )
    finally:
        if held_parent.exists():
            candidate_parent.rmdir()
            held_parent.rename(candidate_parent)


def test_candidate_prefix_revalidates_parent_identity_after_bounded_snapshot(
    tmp_path: Path,
    monkeypatch: pytest.MonkeyPatch,
) -> None:
    parent = tmp_path / "parent"
    parent.mkdir()
    root = parent / "candidate"
    root.mkdir()
    parent_identity = runtime_installer.path_identity(parent)
    root_identity = runtime_installer.path_identity(root)
    original_snapshot = runtime_installer.snapshot_bounded_filesystem_package

    def replace_parent_during_snapshot(path: Path) -> object:
        snapshot = original_snapshot(path)
        held = parent.with_name("held-parent")
        parent.rename(held)
        parent.mkdir()
        (held / root.name).rename(root)
        return snapshot

    monkeypatch.setattr(
        runtime_installer,
        "snapshot_bounded_filesystem_package",
        replace_parent_during_snapshot,
    )
    with pytest.raises(ValueError, match="prefix|parent|changed"):
        runtime_installer._verify_candidate_tree_prefix(
            root=root,
            root_identity=root_identity,
            expected_parent_identity=parent_identity,
            entries=(),
            cursor=0,
        )


