def test_first_install_then_later_new_target_finalization_creates_owner_retirement_cursor(
    tmp_path: Path,
    monkeypatch: pytest.MonkeyPatch,
) -> None:
    """A real new target retires the distinct stale finalized owner only later."""

    result = _exercise_candidate_bound_prefix(
        tmp_path,
        monkeypatch,
        through_owner_bind=True,
        through_committed=True,
        seed_stale_owned_revision=True,
    )

    recovery = result.recovery
    owner = recovery["owner_retirement"]
    assert isinstance(owner, Mapping)
    assert owner["stage"] == "OWNER_RETIRED"
    assert result.actions.index("finalize_attempt_record") < result.actions.index(
        "commit_owner_retirement_prepared"
    )
    assert result.actions.count("commit_owner_retirement_prepared") == 1
    assert Path(str(owner["retired_target_path"])) != Path(
        str(recovery["renamed_target_path"])
    )
    assert not Path(str(owner["retired_target_path"])).exists()
    tombstone = Path(str(owner["tombstone_path"]))
    assert runtime_installer._parse_owner_retirement_tombstone_bytes(
        tombstone.read_bytes(), runtime_root=result.fixture.pipeline.runtime_root
    )["state"] == "COMPLETED"
    assert not Path(str(owner["initial_owner_journal_path"])).exists()
    for owner_field, recovery_field in (
        ("successor_owner_journal_path", "predecessor_journal_path"),
        ("successor_owner_journal_identity", "predecessor_journal_identity"),
        ("successor_owner_journal_sha256", "predecessor_journal_sha256"),
        ("successor_owner_journal_path", "predecessor_target_owner_journal_path"),
        (
            "successor_owner_journal_identity",
            "predecessor_target_owner_journal_identity",
        ),
        (
            "successor_owner_journal_sha256",
            "predecessor_target_owner_journal_sha256",
        ),
    ):
        assert owner[owner_field] == recovery[recovery_field]
    for prefix in ("successor_journal", "successor_target_owner_journal"):
        assert recovery[f"{prefix}_path"] is None
        assert recovery[f"{prefix}_identity"] is None
        assert recovery[f"{prefix}_sha256"] is None


