def test_suffix_noop_staging_retirement_is_identity_bound(
    tmp_path: Path,
) -> None:
    parent_identity = path_identity(tmp_path)
    final_path = tmp_path / "deck_config.ini"
    final_path.write_bytes(b"same\n")
    final_identity = path_identity(final_path)
    staging = tmp_path / "deck_config.ini.staged"
    staging.write_bytes(b"same\n")
    staging_identity = path_identity(staging)
    retired = runtime_installer._retire_unbound_runtime_external_file(
        staging,
        expected_parent_identity=parent_identity,
        expected_identity=staging_identity,
        maximum_size=5,
        expected_size=5,
        expected_sha256="sha256:" + hashlib.sha256(b"same\n").hexdigest(),
    )
    assert retired is not None
    assert not staging.exists()
    assert path_identity(final_path) == final_identity
    staging.write_bytes(b"same\n")
    bound_identity = path_identity(staging)
    replacement = tmp_path / "replacement.staged"
    replacement.write_bytes(b"same\n")
    replacement_identity = path_identity(replacement)
    if replacement_identity == bound_identity:
        pytest.skip("filesystem reused replacement identity")
    os.replace(replacement, staging)
    with pytest.raises(ValueError, match="residue|identity"):
        runtime_installer._retire_unbound_runtime_external_file(
            staging,
            expected_parent_identity=parent_identity,
            expected_identity=bound_identity,
            maximum_size=5,
            expected_size=5,
            expected_sha256=(
                "sha256:" + hashlib.sha256(b"same\n").hexdigest()
            ),
        )
    assert path_identity(staging) == replacement_identity
    assert staging.read_bytes() == b"same\n"
    assert path_identity(final_path) == final_identity


