@pytest.mark.parametrize(
    ("route", "contradiction"),
    (
        ("candidate", "missing_root"),
        ("candidate", "replacement_root"),
        ("prior_owner", "missing_target"),
        ("prior_owner", "replacement_target"),
        ("prior_owner", "missing_owner_journal"),
        ("prior_owner", "replacement_owner_journal"),
    ),
    ids=(
        "candidate-root-missing",
        "candidate-root-byte-identical-new-identity",
        "prior-owner-target-missing",
        "prior-owner-target-byte-identical-new-identity",
        "prior-owner-owner-journal-missing",
        "prior-owner-owner-journal-byte-identical-new-identity",
    ),
)
def test_failure_classification_maps_bound_tree_and_prior_owner_authority_contradictions_to_unknown(
    tmp_path: Path,
    monkeypatch: pytest.MonkeyPatch,
    route: str,
    contradiction: str,
) -> None:
    import hsconfig.live_start_session as live_start_session

    result = (
        _exercise_candidate_bound_prefix(
            tmp_path,
            monkeypatch,
            through_owner_bind=True,
            stop_before_action="rename_candidate_to_target",
        )
        if route == "candidate"
        else _exercise_prior_owner_route(tmp_path, monkeypatch, max_actions=4)
    )
    recovery = result.recovery
    assert recovery["install_route"] == (
        "new_target" if route == "candidate" else "prior_owner"
    )
    protected_fence = Path(str(recovery["successor_attempt_record_path"]))
    protected_before = {
        protected_fence: (
            path_identity(protected_fence),
            protected_fence.read_bytes(),
        )
    }
    bound_attempt_journal = (
        recovery["successor_journal_path"]
        or recovery["predecessor_journal_path"]
    )
    unbound_attempt_journal = runtime_transaction_journal_path(
        result.fixture.runtime_admission.runtime_root,
        result.fixture.runtime_admission.apply_attempt_id,
    )
    if bound_attempt_journal is None:
        assert not os.path.lexists(unbound_attempt_journal)
    else:
        protected_journal = Path(str(bound_attempt_journal))
        protected_before[protected_journal] = (
            path_identity(protected_journal),
            protected_journal.read_bytes(),
        )
    external = recovery["external_file_action"]
    temp_paths = (
        ()
        if not isinstance(external, Mapping)
        else (
            Path(str(external["staging_path"])),
            Path(str(external["inner_temp_path"])),
        )
    )
    assert all(not os.path.lexists(path) for path in temp_paths)
    for prefix in ("predecessor_transaction_temp", "successor_transaction_temp"):
        assert all(
            recovery[f"{prefix}_{suffix}"] is None
            for suffix in (
                "path",
                "parent_identity",
                "identity",
                "size",
                "sha256",
                "classification",
                "origin",
            )
        )
    if contradiction.endswith("root"):
        changed_path = Path(str(recovery["candidate_path"]))
        directory = True
    elif contradiction.endswith("target"):
        changed_path = Path(str(recovery["renamed_target_path"]))
        directory = True
    else:
        changed_path = Path(
            str(recovery["predecessor_target_owner_journal_path"])
        )
        directory = False
    held_root = tmp_path / "held-authority"
    held_root.mkdir()
    held_path = held_root / f"{route}-{contradiction}-{changed_path.name}"
    assert not os.path.lexists(held_path)
    os.replace(changed_path, held_path)
    if contradiction.startswith("replacement"):
        if directory:
            shutil.copytree(held_path, changed_path)
        else:
            changed_path.write_bytes(held_path.read_bytes())
        assert path_identity(changed_path) != path_identity(held_path)

    try:
        runtime_after_setup = _runtime_nonlock_surface_evidence(
            result.fixture.runtime_admission.runtime_root
        )
        for path, evidence in protected_before.items():
            assert (path_identity(path), path.read_bytes()) == evidence
        assert all(not os.path.lexists(path) for path in temp_paths)
        with _controller_pair_reentry_capabilities(
            result.fixture, expected_session=result.cursor
        ) as capabilities:
            with runtime_installer.lease_controller_apply_pair(
                **{
                    **_pair_arguments(capabilities),
                    "runtime_admission": result.fixture.runtime_admission,
                }
            ) as pair:
                session_path = capabilities.session_lease.session_root / "session.json"
                session_before = session_path.read_bytes()
                selection = runtime_installer.classify_runtime_failure_from_pair(
                    lease_pair=pair,
                    transaction_id=(
                        result.fixture.runtime_admission.apply_attempt_id
                    ),
                    runtime_admission=result.fixture.runtime_admission,
                    expected_recovery=live_start_session.RuntimeApplyRecoveryEvidence(
                        recovery
                    ),
                )
                assert selection.disposition == "select_terminal_observation"
                assert selection.selected_observation == "observe_unknown"
                assert session_path.read_bytes() == session_before
                assert _runtime_nonlock_surface_evidence(
                    result.fixture.runtime_admission.runtime_root
                ) == runtime_after_setup
                for path, evidence in protected_before.items():
                    assert (path_identity(path), path.read_bytes()) == evidence
                if bound_attempt_journal is None:
                    assert not os.path.lexists(unbound_attempt_journal)
                classification = (
                    live_start_session._authorize_runtime_observation_under_lock(
                        session_lease=capabilities.session_lease,
                        expected_session=result.cursor,
                        observation_family="terminal_classification",
                        apply_attempt_id=(
                            result.fixture.runtime_admission.apply_attempt_id
                        ),
                    )
                )
                receipt = runtime_installer.observe_runtime_failure_selection_from_pair(
                    lease_pair=pair,
                    transaction_id=result.fixture.runtime_admission.apply_attempt_id,
                    runtime_admission=result.fixture.runtime_admission,
                    expected_recovery=live_start_session.RuntimeApplyRecoveryEvidence(
                        recovery
                    ),
                    observation_authorization=classification,
                )
                selected = live_start_session.advance_nonterminal_apply_recovery_under_lock(
                    session_lease=capabilities.session_lease,
                    expected_recovery_session=result.cursor,
                    transition="select_terminal_classification",
                    recovery_evidence=None,
                    recovery_authorization=None,
                    physical_step_receipt=None,
                    runtime_observation_receipt=receipt,
                )
                physical_authorization = (
                    live_start_session._authorize_nonterminal_apply_recovery_under_lock(
                        session_lease=capabilities.session_lease,
                        expected_recovery_session=selected,
                        expected_action="observe_unknown",
                    )
                )
                selected_raw = session_path.read_bytes()
                physical = runtime_installer.recover_runtime_attempt_from_pair(
                    lease_pair=pair,
                    transaction_id=result.fixture.runtime_admission.apply_attempt_id,
                    expected_retention_owner_run_id=result.fixture.apply_started.run_id,
                    expected_package_root_sha256=(
                        result.fixture.runtime_admission.package_root_sha256
                    ),
                    expected_deck_name=result.plan.deck_name,
                    runtime_admission=result.fixture.runtime_admission,
                    nonterminal_recovery_authorization=physical_authorization,
                )
                assert session_path.read_bytes() == selected_raw
                assert _runtime_nonlock_surface_evidence(
                    result.fixture.runtime_admission.runtime_root
                ) == runtime_after_setup
                for path, evidence in protected_before.items():
                    assert (path_identity(path), path.read_bytes()) == evidence
                if bound_attempt_journal is None:
                    assert not os.path.lexists(unbound_attempt_journal)
                unknown = live_start_session.advance_nonterminal_apply_recovery_under_lock(
                    session_lease=capabilities.session_lease,
                    expected_recovery_session=selected,
                    transition="physical_recovery_advanced",
                    recovery_evidence=None,
                    recovery_authorization=None,
                    physical_step_receipt=physical.apply_recovery_step_receipt,
                    runtime_observation_receipt=None,
                )
                unknown_recovery = unknown.apply_recovery
                assert unknown_recovery is not None
                assert unknown_recovery["stable_physical_disposition"] == (
                    "UNKNOWN_REQUIRES_RECOVERY"
                )
                assert _runtime_nonlock_surface_evidence(
                    result.fixture.runtime_admission.runtime_root
                ) == runtime_after_setup
    finally:
        if os.path.lexists(changed_path):
            if directory:
                shutil.rmtree(changed_path)
            else:
                changed_path.unlink()
        os.replace(held_path, changed_path)


@pytest.mark.parametrize(
    "attack",
    (
        "malformed_owner_journal",
        "digest_changed_owner_journal",
        "semantic_owner_journal",
        "missing_candidate_root_and_fence",
    ),
)
def test_failure_classification_keeps_unscoped_authority_contradictions_hard(
    tmp_path: Path,
    monkeypatch: pytest.MonkeyPatch,
    attack: str,
) -> None:
    import hsconfig.live_start_session as live_start_session

    candidate_route = attack == "missing_candidate_root_and_fence"
    result = (
        _exercise_candidate_bound_prefix(
            tmp_path,
            monkeypatch,
            through_owner_bind=True,
            stop_before_action="rename_candidate_to_target",
        )
        if candidate_route
        else _exercise_prior_owner_route(tmp_path, monkeypatch, max_actions=4)
    )
    recovery = result.recovery
    held_paths: list[tuple[Path, Path, bool]] = []

    def hold(path: Path, *, directory: bool) -> Path:
        held = path.with_name(f"{path.name}.{attack}.held")
        assert not os.path.lexists(held)
        os.replace(path, held)
        held_paths.append((path, held, directory))
        return held

    if candidate_route:
        hold(Path(str(recovery["candidate_path"])), directory=True)
        hold(
            Path(str(recovery["successor_attempt_record_path"])),
            directory=False,
        )
        expected_error = "^runtime_apply_recovery_attempt_record_changed$"
    else:
        owner_path = Path(
            str(recovery["predecessor_target_owner_journal_path"])
        )
        held_owner = hold(owner_path, directory=False)
        if attack == "malformed_owner_journal":
            owner_path.write_bytes(b"{not-a-journal")
        else:
            owner = runtime_installer.parse_runtime_transaction_journal_bytes(
                held_owner.read_bytes()
            )
            changed_owner = (
                replace(owner, next_ini_sha256="0" * 64)
                if attack == "digest_changed_owner_journal"
                else replace(owner, owns_target=False)
            )
            owner_path.write_bytes(
                runtime_installer.runtime_transaction_journal_bytes(
                    changed_owner
                )
            )
        expected_error = "^runtime_attempt_retained_journal_invalid$"

    try:
        runtime_after_setup = _runtime_nonlock_surface_evidence(
            result.fixture.runtime_admission.runtime_root
        )
        with _controller_pair_reentry_capabilities(
            result.fixture, expected_session=result.cursor
        ) as capabilities:
            with runtime_installer.lease_controller_apply_pair(
                **{
                    **_pair_arguments(capabilities),
                    "runtime_admission": result.fixture.runtime_admission,
                }
            ) as pair:
                session_path = capabilities.session_lease.session_root / "session.json"
                session_before = session_path.read_bytes()
                with pytest.raises(ValueError, match=expected_error):
                    runtime_installer.classify_runtime_failure_from_pair(
                        lease_pair=pair,
                        transaction_id=(
                            result.fixture.runtime_admission.apply_attempt_id
                        ),
                        runtime_admission=result.fixture.runtime_admission,
                        expected_recovery=(
                            live_start_session.RuntimeApplyRecoveryEvidence(
                                recovery
                            )
                        ),
                    )
                assert session_path.read_bytes() == session_before
                assert _runtime_nonlock_surface_evidence(
                    result.fixture.runtime_admission.runtime_root
                ) == runtime_after_setup
    finally:
        for path, held, directory in reversed(held_paths):
            if os.path.lexists(path):
                if directory:
                    shutil.rmtree(path)
                else:
                    path.unlink()
            os.replace(held, path)


@pytest.mark.parametrize(
    "attack",
    (
        "missing_target_and_in_place_malformed_owner",
        "replaced_custom_config_parent_and_missing_target",
        "replaced_transactions_parent_and_missing_owner",
        "missing_candidate_and_unbound_retention_staging",
        "replacement_candidate_with_tree_drift",
    ),
)
def test_failure_classification_does_not_mask_independent_projection_errors_with_authority_marker(
    tmp_path: Path,
    monkeypatch: pytest.MonkeyPatch,
    attack: str,
) -> None:
    import hsconfig.live_start_session as live_start_session

    candidate_route = attack in {
        "missing_candidate_and_unbound_retention_staging",
        "replacement_candidate_with_tree_drift",
    }
    result = (
        _exercise_candidate_bound_prefix(
            tmp_path,
            monkeypatch,
            through_owner_bind=True,
            stop_before_action="rename_candidate_to_target",
        )
        if candidate_route
        else _exercise_prior_owner_route(tmp_path, monkeypatch, max_actions=4)
    )
    recovery = result.recovery
    runtime_root = result.fixture.runtime_admission.runtime_root
    with _controller_pair_reentry_capabilities(
        result.fixture, expected_session=result.cursor
    ) as capabilities:
        with runtime_installer.lease_controller_apply_pair(
            **{
                **_pair_arguments(capabilities),
                "runtime_admission": result.fixture.runtime_admission,
            }
        ) as pair:
            held_root = tmp_path / f"held-combined-{attack}"
            held_root.mkdir()
            restore: list[tuple[str, Path, Path | bytes]] = []
            try:
                if attack == "missing_target_and_in_place_malformed_owner":
                    target = Path(str(recovery["renamed_target_path"]))
                    held_target = held_root / target.name
                    os.replace(target, held_target)
                    restore.append(("move", target, held_target))
                    owner = Path(
                        str(recovery["predecessor_target_owner_journal_path"])
                    )
                    owner_raw = owner.read_bytes()
                    owner_identity = path_identity(owner)
                    owner.write_bytes(b"{not-a-runtime-transaction")
                    assert path_identity(owner) == owner_identity
                    restore.append(("bytes", owner, owner_raw))
                elif attack == "replaced_custom_config_parent_and_missing_target":
                    target = Path(str(recovery["renamed_target_path"]))
                    parent = target.parent
                    held_parent = held_root / parent.name
                    os.replace(parent, held_parent)
                    shutil.copytree(held_parent, parent)
                    shutil.rmtree(parent / target.name)
                    restore.append(("tree", parent, held_parent))
                elif attack == "replaced_transactions_parent_and_missing_owner":
                    owner = Path(
                        str(recovery["predecessor_target_owner_journal_path"])
                    )
                    parent = owner.parent
                    held_parent = held_root / parent.name
                    os.replace(parent, held_parent)
                    shutil.copytree(held_parent, parent)
                    (parent / owner.name).unlink()
                    restore.append(("tree", parent, held_parent))
                elif attack == "missing_candidate_and_unbound_retention_staging":
                    candidate = Path(str(recovery["candidate_path"]))
                    held_candidate = held_root / candidate.name
                    os.replace(candidate, held_candidate)
                    restore.append(("move", candidate, held_candidate))
                    attempt = Path(str(recovery["successor_attempt_record_path"]))
                    residue = attempt.with_name(f"{attempt.name}.staged")
                    residue.write_bytes(b"unbound-retention-staging")
                    restore.append(("unlink", residue, b""))
                else:
                    assert attack == "replacement_candidate_with_tree_drift"
                    candidate = Path(str(recovery["candidate_path"]))
                    held_candidate = held_root / candidate.name
                    os.replace(candidate, held_candidate)
                    shutil.copytree(held_candidate, candidate)
                    victim = next(
                        path for path in candidate.iterdir() if path.is_file()
                    )
                    victim.write_bytes(victim.read_bytes() + b"drift")
                    restore.append(("tree", candidate, held_candidate))

                session_path = capabilities.session_lease.session_root / "session.json"
                session_before = session_path.read_bytes()
                runtime_after_setup = _runtime_nonlock_surface_evidence(runtime_root)
                with pytest.raises(ValueError):
                    runtime_installer.classify_runtime_failure_from_pair(
                        lease_pair=pair,
                        transaction_id=(
                            result.fixture.runtime_admission.apply_attempt_id
                        ),
                        runtime_admission=result.fixture.runtime_admission,
                        expected_recovery=(
                            live_start_session.RuntimeApplyRecoveryEvidence(
                                recovery
                            )
                        ),
                    )
                assert session_path.read_bytes() == session_before
                assert _runtime_nonlock_surface_evidence(runtime_root) == (
                    runtime_after_setup
                )
            finally:
                for kind, path, saved in reversed(restore):
                    if kind == "bytes":
                        assert isinstance(saved, bytes)
                        path.write_bytes(saved)
                    elif kind == "unlink":
                        if os.path.lexists(path):
                            path.unlink()
                    elif kind == "move":
                        assert isinstance(saved, Path)
                        if os.path.lexists(path):
                            shutil.rmtree(path)
                        os.replace(saved, path)
                    else:
                        assert kind == "tree"
                        assert isinstance(saved, Path)
                        if os.path.lexists(path):
                            shutil.rmtree(path)
                        os.replace(saved, path)


