def test_failure_classification_never_selects_pending_with_external_action(
    tmp_path: Path,
    monkeypatch: pytest.MonkeyPatch,
) -> None:
    import hsconfig.live_start_session as live_start_session
    from tests import test_live_start_session as session_tests

    result = _exercise_prior_owner_route(tmp_path, monkeypatch, max_actions=6)
    recovery = result.recovery
    external = recovery["external_file_action"]
    assert recovery["install_route"] == "prior_owner"
    assert recovery["successor_journal_identity"] is not None
    assert isinstance(external, Mapping)
    assert recovery["deck_config_ini_sha256"] is None
    assert external["action_kind"] == "materialize_file_action_staging"
    assert external["stage"] == "PLANNED"
    retention_path = result.fixture.runtime_admission.retention_fence_path
    assert Path(str(external["final_path"])) == retention_path
    assert recovery["successor_attempt_record_path"] == str(retention_path)
    assert external["predecessor_identity"] == recovery[
        "successor_attempt_record_identity"
    ]

    with _controller_pair_reentry_capabilities(
        result.fixture, expected_session=result.cursor
    ) as capabilities:
        with runtime_installer.lease_controller_apply_pair(
            **{
                **_pair_arguments(capabilities),
                "runtime_admission": result.fixture.runtime_admission,
            }
        ) as pair:
            selection = runtime_installer.classify_runtime_failure_from_pair(
                lease_pair=pair,
                transaction_id=result.fixture.runtime_admission.apply_attempt_id,
                runtime_admission=result.fixture.runtime_admission,
                expected_recovery=(
                    live_start_session.RuntimeApplyRecoveryEvidence(recovery)
                ),
            )

    assert selection.disposition == "resume_current_action"
    assert selection.selected_observation is None

    classified = runtime_installer._plain_json_value(recovery)
    assert isinstance(classified, dict)
    classified.pop("content_sha256")
    classified.update(
        {
            "action_index": int(recovery["action_index"]) + 1,
            "expected_action": "observe_pending",
        }
    )
    classified = session_tests._seal_literal_document(classified)
    assert classified["external_file_action"] == runtime_installer._plain_json_value(
        external
    )
    with pytest.raises(
        live_start_session.SessionCapabilityError,
        match="live_start_terminal_classification",
    ):
        live_start_session._validate_apply_recovery_classification_successor(
            predecessor=recovery,
            successor=classified,
        )


def test_runtime_observation_pending_rejects_external_action_before_closure(
    tmp_path: Path,
    monkeypatch: pytest.MonkeyPatch,
) -> None:
    import hsconfig.live_start_session as live_start_session
    from tests import test_live_start_session as session_tests

    result = _exercise_prior_owner_route(tmp_path, monkeypatch, max_actions=6)
    recovery = result.recovery
    external = recovery["external_file_action"]
    assert isinstance(external, Mapping)
    pending = runtime_installer._plain_json_value(recovery)
    assert isinstance(pending, dict)
    pending.pop("content_sha256")
    pending.update(
        {
            "action_index": int(recovery["action_index"]) + 1,
            "expected_action": "observe_pending",
        }
    )
    pending = session_tests._seal_literal_document(pending)
    assert pending["external_file_action"] == runtime_installer._plain_json_value(
        external
    )

    with _controller_pair_reentry_capabilities(
        result.fixture, expected_session=result.cursor
    ) as capabilities:
        with runtime_installer.lease_controller_apply_pair(
            **{
                **_pair_arguments(capabilities),
                "runtime_admission": result.fixture.runtime_admission,
            }
        ) as pair:
            persisted = live_start_session.load_live_start_session_under_lock(
                session_lease=capabilities.session_lease
            )
            assert persisted.canonical_json == result.cursor.canonical_json
            session_path = capabilities.session_lease.session_root / "session.json"
            session_before = session_path.read_bytes()
            runtime_before = _runtime_nonlock_surface_evidence(
                result.fixture.runtime_admission.runtime_root
            )
            observation = runtime_installer._observe_exact_paired_runtime_attempt(
                result.fixture.runtime_admission.runtime_root,
                transaction_id=result.fixture.runtime_admission.apply_attempt_id,
                expected_retention_owner_run_id=(
                    result.fixture.runtime_admission.retention_owner_run_id
                ),
                expected_package_root_sha256=str(recovery["package_root_sha256"]),
                expected_deck_name=persisted.deck_name,
                recovery_cursor=recovery,
            )
            assert observation.transaction.journal is not None
            with pytest.raises(
                ValueError,
                match="^runtime_pending_observation_external_action_invalid$",
            ):
                runtime_installer._runtime_observation_recovery_postcondition(
                    recovery=pending,
                    action="observe_pending",
                    observation=observation,
                    package_lease=capabilities.package_lease,
                    persisted=persisted,
                    profile_lease=capabilities.profile_lease,
                    session_root=capabilities.session_lease.session_root,
                    lease_pair=pair,
                    runtime_admission=result.fixture.runtime_admission,
                )
            assert session_path.read_bytes() == session_before
            assert _runtime_nonlock_surface_evidence(
                result.fixture.runtime_admission.runtime_root
            ) == runtime_before
            assert live_start_session.load_live_start_session_under_lock(
                session_lease=capabilities.session_lease
            ).canonical_json == result.cursor.canonical_json


