@pytest.mark.parametrize(
    "substitute", ["target", "owner", "observation_target", "observation_owner"]
)
def test_nonowning_fastpath_rejects_same_byte_target_or_owner_substitution(
    tmp_path: Path,
    monkeypatch: pytest.MonkeyPatch,
    substitute: str,
) -> None:
    import hsconfig.live_start_session as live_start_session

    observation_probe: dict[str, Any] = {}
    def replace_same_bytes(
        _action: str, recovery: Mapping[str, Any], index: int
    ) -> None:
        if index != 0:
            return
        if substitute == "owner":
            path = Path(str(recovery["predecessor_target_owner_journal_path"]))
            replacement = path.with_suffix(".replacement")
            replacement.write_bytes(path.read_bytes())
            os.replace(replacement, path)
            return
        path = Path(str(recovery["renamed_target_path"]))
        old = path.with_name(f"{path.name}.old")
        os.replace(path, old)
        shutil.copytree(old, path)

    expected_error = {
        "observation_target": "runtime_initial_prior_owner_target_changed",
        "observation_owner": "runtime_initial_prior_owner_changed",
    }.get(substitute, "changed|identity|owner|target|retained_journal_invalid")
    with pytest.raises(ValueError, match=expected_error):
        _exercise_prior_owner_route(
            tmp_path,
            monkeypatch,
            before_action=replace_same_bytes,
            replace_target_during_observation=(
                substitute == "observation_target"
            ),
            replace_owner_during_observation=(
                substitute == "observation_owner"
            ),
            observation_probe=observation_probe,
        )
    if substitute.startswith("observation_"):
        assert _runtime_nonlock_surface_evidence(
            observation_probe["runtime_root"]
        ) == observation_probe["runtime_before"]
        with _controller_pair_reentry_capabilities(
            observation_probe["fixture"]
        ) as capabilities:
            persisted = live_start_session.load_live_start_session_under_lock(
                session_lease=capabilities.session_lease
            )
            assert persisted.canonical_json == observation_probe["session_before"]


