@pytest.mark.parametrize("substitute", ["fence", "journal", "owner"])
def test_same_byte_fence_journal_or_owner_substitution_fails_closed(
    tmp_path: Path,
    monkeypatch: pytest.MonkeyPatch,
    substitute: str,
) -> None:
    expected_index = 4 if substitute == "fence" else 6
    probe: dict[str, Any] = {}

    def replace_bound_file(
        _action: str, recovery: Mapping[str, Any], index: int
    ) -> None:
        if index != expected_index:
            return
        field = {
            "fence": "successor_attempt_record_path",
            "journal": "successor_journal_path",
            "owner": "predecessor_target_owner_journal_path",
        }[substitute]
        path = Path(str(recovery[field]))
        replacement = path.with_suffix(".replacement")
        replacement.write_bytes(path.read_bytes())
        os.replace(replacement, path)
        runtime_root = Path(str(recovery["runtime_root"]))
        probe["runtime_root"] = runtime_root
        probe["runtime_before"] = _runtime_nonlock_surface_evidence(runtime_root)

    expected_error = {
        "fence": "runtime_apply_recovery_attempt_record_changed",
        "journal": "runtime_apply_recovery_journal_changed",
        "owner": "runtime_attempt_retained_journal_invalid",
    }[substitute]
    with pytest.raises(ValueError, match=expected_error):
        _exercise_prior_owner_route(
            tmp_path,
            monkeypatch,
            before_action=replace_bound_file,
            failure_probe=probe,
        )
    assert _runtime_nonlock_surface_evidence(probe["runtime_root"]) == probe[
        "runtime_before"
    ]
    assert probe["session_after"] == probe["session_before"]
    assert probe["action_index_after"] == probe["action_index_before"]
    assert probe["content_sha256_after"] == probe["content_sha256_before"]


