def test_pair_observation_receipt_binds_exact_requested_initial_recovery_evidence(
    tmp_path: Path,
    monkeypatch: pytest.MonkeyPatch,
    request: pytest.FixtureRequest,
) -> None:
    import hsconfig.live_start_session as live_start_session

    foreign = _controller_pair_post_handoff_fixture(
        tmp_path / "foreign",
        monkeypatch,
        seed_prior_owner=True,
    )
    monkeypatch.setenv("LOCALAPPDATA", str(foreign.pipeline.local_app_data))
    foreign_stack = ExitStack()
    request.addfinalizer(foreign_stack.close)
    capabilities = foreign_stack.enter_context(
        _controller_pair_reentry_capabilities(foreign)
    )
    publication = capabilities.package_lease.publication
    assert publication is not None
    foreign_plan = plan_runtime_install(
        published_output=PublishedOutput(
            output_root=capabilities.package_lease.output_root,
            revision_root=capabilities.package_lease.package_root.parent,
            package_root=capabilities.package_lease.package_root,
            content_root_sha256=publication.content_root_sha256,
            reused_existing_revision=True,
        ),
        runtime_root=capabilities.pipeline.runtime_root,
    )
    with runtime_installer.lease_controller_apply_pair(
        **{
            **_pair_arguments(capabilities),
            "runtime_admission": foreign.runtime_admission,
        }
    ) as pair:
        authorization = live_start_session._authorize_runtime_observation_under_lock(
            session_lease=capabilities.session_lease,
            expected_session=foreign.apply_started,
            observation_family="first_install",
            apply_attempt_id=foreign.runtime_admission.apply_attempt_id,
        )
        foreign_receipt = runtime_installer.observe_initial_runtime_install_from_pair(
            foreign_plan,
            lease_pair=pair,
            observation_authorization=authorization,
            transaction_id=foreign.runtime_admission.apply_attempt_id,
            retention_owner_run_id=foreign.apply_started.run_id,
            runtime_admission=foreign.runtime_admission,
        )

    primary = _controller_pair_post_handoff_fixture(
        tmp_path / "primary",
        monkeypatch,
        seed_prior_owner=True,
    )
    monkeypatch.setenv("LOCALAPPDATA", str(primary.pipeline.local_app_data))
    with _controller_pair_reentry_capabilities(primary) as capabilities:
        publication = capabilities.package_lease.publication
        assert publication is not None
        plan = plan_runtime_install(
            published_output=PublishedOutput(
                output_root=capabilities.package_lease.output_root,
                revision_root=capabilities.package_lease.package_root.parent,
                package_root=capabilities.package_lease.package_root,
                content_root_sha256=publication.content_root_sha256,
                reused_existing_revision=True,
            ),
            runtime_root=capabilities.pipeline.runtime_root,
        )
        session_path = capabilities.session_lease.session_root / "session.json"
        canonical_before = primary.apply_started.canonical_json
        raw_before = session_path.read_bytes()
        with pytest.raises(
            live_start_session.SessionCapabilityError,
            match=(
                "^live_start_runtime_observation_receipt_"
                "session_or_cursor_mismatch$"
            ),
        ):
            live_start_session.prepare_first_runtime_install_under_lock(
                session_lease=capabilities.session_lease,
                expected_apply_started_session=primary.apply_started,
                runtime_observation_receipt=foreign_receipt,
            )
        assert session_path.read_bytes() == raw_before
        assert live_start_session.load_live_start_session_under_lock(
            session_lease=capabilities.session_lease
        ).canonical_json == canonical_before
        with runtime_installer.lease_controller_apply_pair(
            **{
                **_pair_arguments(capabilities),
                "runtime_admission": primary.runtime_admission,
            }
        ) as pair:
            authorization = live_start_session._authorize_runtime_observation_under_lock(
                session_lease=capabilities.session_lease,
                expected_session=primary.apply_started,
                observation_family="first_install",
                apply_attempt_id=primary.runtime_admission.apply_attempt_id,
            )
            receipt = runtime_installer.observe_initial_runtime_install_from_pair(
                plan,
                lease_pair=pair,
                observation_authorization=authorization,
                transaction_id=primary.runtime_admission.apply_attempt_id,
                retention_owner_run_id=primary.apply_started.run_id,
                runtime_admission=primary.runtime_admission,
            )
            cursor = live_start_session.prepare_first_runtime_install_under_lock(
                session_lease=capabilities.session_lease,
                expected_apply_started_session=primary.apply_started,
                runtime_observation_receipt=receipt,
            )
    recovery = cursor.apply_recovery
    assert recovery is not None
    assert recovery["apply_attempt_id"] == primary.runtime_admission.apply_attempt_id
    assert recovery["runtime_admission_sha256"] == primary.runtime_admission.admission_sha256
    assert set(recovery) == live_start_session._APPLY_RECOVERY_FIELDS
    unsealed = runtime_installer._plain_json_value(recovery)
    assert isinstance(unsealed, dict)
    digest = unsealed.pop("content_sha256")
    raw = (
        json.dumps(
            unsealed,
            allow_nan=False,
            ensure_ascii=False,
            separators=(",", ":"),
            sort_keys=True,
        )
        + "\n"
    ).encode("utf-8")
    assert digest == "sha256:" + hashlib.sha256(raw).hexdigest()
    layout = cursor.runtime_layout_bootstrap
    assert layout is not None
    layout_identities = (
        runtime_installer._validated_complete_layout_successor_identities(
            layout=layout,
            runtime_root=primary.runtime_admission.runtime_root,
        )
    )
    target = Path(recovery["renamed_target_path"])
    owner = Path(recovery["predecessor_target_owner_journal_path"])
    expected = runtime_installer._initial_prior_owner_apply_recovery(
        plan=plan,
        runtime_admission=primary.runtime_admission,
        layout_identities=layout_identities,
        state_key=Path(layout["directories"][4]["path"]).name,
        target_identity=path_identity(target),
        owner_path=owner,
        owner_identity=path_identity(owner),
        owner_sha256="sha256:" + hashlib.sha256(owner.read_bytes()).hexdigest(),
    )
    assert dict(recovery) == dict(expected.value)


