def test_terminal_inventory_rejects_descendant_directory_identity_substitution_after_enqueue(
    tmp_path: Path,
    monkeypatch: pytest.MonkeyPatch,
) -> None:
    root = tmp_path / "candidate"
    child = root / "nested"
    child.mkdir(parents=True)
    (child / "card.json").write_bytes(b"{}\n")
    root_identity = path_identity(root)
    parent_identity = path_identity(root.parent)
    original = runtime_installer.path_identity_from_status
    directory_calls = 0
    replaced = False

    def replace_after_enqueue(status: os.stat_result) -> tuple[int, int, int]:
        nonlocal directory_calls, replaced
        identity = original(status)
        if stat.S_ISDIR(status.st_mode):
            directory_calls += 1
            if directory_calls == 2 and not replaced:
                held = child.with_name("nested-held")
                os.replace(child, held)
                shutil.copytree(held, child)
                replaced = True
        return identity

    monkeypatch.setattr(
        runtime_installer,
        "path_identity_from_status",
        replace_after_enqueue,
    )
    with pytest.raises(
        ValueError,
        match="^runtime_terminal_cleanup_entry_changed$",
    ):
        runtime_installer._snapshot_terminal_cleanup_root(
            root_role="candidate",
            root_path=root,
            root_identity=root_identity,
            root_parent_identity=parent_identity,
        )
    assert replaced is True


def test_terminal_no_commit_inventory_accepts_exact_candidate_planned_prepared_authority(
    tmp_path: Path,
    monkeypatch: pytest.MonkeyPatch,
) -> None:
    metadata_generations = 0
    metadata_cursors: list[object] = []
    original_observer = runtime_installer._observe_exact_paired_runtime_attempt

    def counted_observer(*args: object, **kwargs: object) -> object:
        nonlocal metadata_generations
        if (
            kwargs.get("action_bound_candidate_identity") is not None
            and kwargs.get("action_bound_journal_triplet") is not None
        ):
            metadata_generations += 1
            metadata_cursors.append(kwargs.get("recovery_cursor"))
        return original_observer(*args, **kwargs)

    monkeypatch.setattr(
        runtime_installer,
        "_observe_exact_paired_runtime_attempt",
        counted_observer,
    )
    prepared = _real_no_commit_cleanup_cursor(
        tmp_path,
        monkeypatch,
        role="planned_candidate",
    )
    resolution = prepared.cursor.terminal_retirement[
        "terminal_resolution_evidence"
    ]
    fence_path = Path(str(resolution["predecessor_attempt_record_path"]))
    journal_path = Path(str(resolution["predecessor_journal_path"]))
    record = runtime_installer._runtime_attempt_retention_from_raw(
        fence_path.read_bytes(),
        runtime_root=prepared.fixture.runtime_admission.runtime_root,
    )
    journal_raw = journal_path.read_bytes()
    journal = runtime_installer.parse_runtime_transaction_journal_bytes(
        journal_raw,
        expected_transaction_id=(
            prepared.fixture.runtime_admission.apply_attempt_id
        ),
    )
    assert record.state == "CANDIDATE_PLANNED"
    assert record.candidate_identity is None
    assert record.journal_path is None
    assert record.planned_journal_path == journal_path
    assert record.planned_journal_size == len(journal_raw)
    assert record.planned_journal_sha256 == (
        "sha256:" + hashlib.sha256(journal_raw).hexdigest()
    )
    assert journal.phase == RuntimeTransactionPhase.PREPARED
    assert journal.candidate_identity is None
    assert tuple(resolution["predecessor_candidate_identity"]) == path_identity(
        prepared.root_path
    )
    assert resolution["successor_candidate_identity"] is None
    assert prepared.root_path.exists()
    assert prepared.inventory.value["cleanup_roots"][0][
        "source_identity"
    ] == path_identity(prepared.root_path)
    assert metadata_generations == 1
    assert isinstance(metadata_cursors[0], Mapping)
    assert metadata_cursors[0]["recovery_stage"] == "CLOSED"


def test_runtime_attempt_recovery_inventory_binds_status_run_attempt_and_runtime_root(
    tmp_path: Path,
    monkeypatch: pytest.MonkeyPatch,
) -> None:
    import hsconfig.live_start_session as live_start_session
    from tests import test_live_start_session as session_tests

    prepared = _real_no_commit_cleanup_cursor(
        tmp_path,
        monkeypatch,
        role="planned_candidate",
        stop_at_recovery_prepared=True,
    )
    observed = prepared.terminal_observation
    assert observed.status == "not_committed"
    assert observed.terminal_cleanup_inventory == prepared.inventory
    base = {
        name: getattr(observed, name)
        for name in runtime_installer.RuntimeAttemptRecovery.__dataclass_fields__
    }
    invalid_rows: list[dict[str, object]] = [{"status": "unknown"}]
    for field_name, replacement in (
        ("run_id", "f" * 32),
        ("apply_attempt_id", "e" * 32),
        ("runtime_root_path", str((tmp_path / "foreign-runtime").absolute())),
        ("runtime_root_identity", [991, 992, 0o40755]),
    ):
        value = runtime_installer._plain_json_value(prepared.inventory.value)
        value.pop("content_sha256")
        value[field_name] = replacement
        invalid_rows.append(
            {
                "terminal_cleanup_inventory": (
                    live_start_session.TerminalResolutionCleanupInventory(
                        session_tests._seal_literal_document(value)
                    )
                )
            }
        )
    for changes in invalid_rows:
        arguments = dict(base)
        arguments.update(changes)
        with pytest.raises(
            ValueError,
            match="^runtime_attempt_recovery_family_nullability_invalid$",
        ):
            runtime_installer.RuntimeAttemptRecovery(**arguments)


