@pytest.mark.parametrize(
    "substitution", ("entry", "parent", "fence", "journal")
)
def test_terminal_inventory_prepared_rejects_same_byte_entry_or_parent_identity_substitution(
    tmp_path: Path,
    monkeypatch: pytest.MonkeyPatch,
    substitution: str,
) -> None:
    import hsconfig.live_start_session as live_start_session

    prepared = _real_no_commit_cleanup_cursor(
        tmp_path,
        monkeypatch,
        role="candidate",
        stop_at_recovery_prepared=True,
    )
    root = prepared.root_path
    held = root.parent.with_name(f"{root.parent.name}.held")
    renamed_parent = False
    try:
        if substitution == "entry":
            row = next(
                item
                for item in prepared.inventory.value["entries"]
                if item["entry_kind"] == "file"
            )
            path = root / str(row["relative_path"])
            raw = path.read_bytes()
            path.unlink()
            path.write_bytes(raw)
            assert path_identity(path) != tuple(row["identity"])
        elif substitution == "parent":
            assert not held.exists()
            os.replace(root.parent, held)
            renamed_parent = True
            shutil.copytree(held, root.parent)
            assert path_identity(root.parent) != tuple(
                prepared.inventory.value["cleanup_roots"][0][
                    "expected_parent_identity"
                ]
            )
        else:
            resolution = prepared.cursor.terminal_retirement[
                "terminal_resolution_evidence"
            ]
            prefix = (
                "predecessor_attempt_record"
                if substitution == "fence"
                else "predecessor_journal"
            )
            path = Path(str(resolution[f"{prefix}_path"]))
            old_identity = tuple(resolution[f"{prefix}_identity"])
            raw = path.read_bytes()
            path.unlink()
            path.write_bytes(raw)
            assert path_identity(path) != old_identity
        session_before = prepared.cursor.canonical_json
        monkeypatch.setenv(
            "LOCALAPPDATA", str(prepared.fixture.pipeline.local_app_data)
        )
        with _controller_pair_reentry_capabilities(
            prepared.fixture, expected_session=prepared.cursor
        ) as capabilities:
            with runtime_installer.lease_controller_apply_pair(
                **{
                    **_pair_arguments(capabilities),
                    "runtime_admission": prepared.fixture.runtime_admission,
                }
            ) as pair:
                with pytest.raises(ValueError):
                    runtime_installer.reconstruct_runtime_no_commit_inventory_from_pair(
                        lease_pair=pair,
                        transaction_id=(
                            prepared.fixture.runtime_admission.apply_attempt_id
                        ),
                        runtime_admission=prepared.fixture.runtime_admission,
                    )
                assert live_start_session.load_live_start_session_under_lock(
                    session_lease=capabilities.session_lease
                ).canonical_json == session_before
    finally:
        if renamed_parent:
            shutil.rmtree(root.parent)
            os.replace(held, root.parent)


