def _retire_success_ack_evidence_row(
    *,
    fixture: SimpleNamespace,
    capabilities: SimpleNamespace,
    prepared: object,
    action: str,
):
    import hsconfig.live_start_session as live_start_session

    assert isinstance(prepared, live_start_session.LiveStartSession)
    acknowledgement = prepared.attempt_acknowledgement
    assert acknowledgement is not None
    with runtime_installer.lease_controller_apply_pair(
        **{
            **_pair_arguments(capabilities),
            "runtime_admission": fixture.runtime_admission,
        }
    ) as pair:
        authorization = live_start_session.authorize_terminal_retirement_under_lock(
            session_lease=capabilities.session_lease,
            expected_retirement_session=prepared,
        )
        assert authorization._opaque.action == f"retire_ack_{action}"
        return runtime_installer._retire_success_attempt_evidence_step_from_pair(
            lease_pair=pair,
            session_lease=capabilities.session_lease,
            expected_retirement_session=prepared,
            terminal_authorization=authorization,
            transaction_id=fixture.runtime_admission.apply_attempt_id,
            expected_retention_owner_run_id=fixture.apply_started.run_id,
            expected_package_root_sha256=fixture.runtime_admission.package_root_sha256,
            expected_retention_fence_path=Path(
                str(acknowledgement["retention_fence_path"])
            ),
            expected_retention_fence_identity=tuple(
                acknowledgement["retention_fence_identity"]
            ),
            expected_retention_fence_sha256=str(
                acknowledgement["retention_fence_sha256"]
            ),
            expected_journal_path=Path(str(acknowledgement["journal_path"])),
            expected_journal_identity=tuple(acknowledgement["journal_identity"]),
            expected_journal_sha256=str(acknowledgement["journal_sha256"]),
            expected_target_owner_journal_path=Path(
                str(acknowledgement["target_owner_journal_path"])
            ),
            expected_target_owner_journal_identity=tuple(
                acknowledgement["target_owner_journal_identity"]
            ),
            expected_target_owner_journal_sha256=str(
                acknowledgement["target_owner_journal_sha256"]
            ),
            expected_target_path=Path(str(acknowledgement["target_path"])),
            expected_target_identity=tuple(acknowledgement["target_identity"]),
            expected_runtime_admission_path=fixture.runtime_admission.admission_path,
            expected_runtime_admission_parent_identity=(
                fixture.runtime_admission.admission_parent_identity
            ),
            expected_runtime_admission_identity=(
                fixture.runtime_admission.admission_identity
            ),
            expected_runtime_admission_sha256=(
                fixture.runtime_admission.admission_sha256
            ),
            action=action,
        )


def _retire_owning_success_ack_fence(
    *,
    fixture: SimpleNamespace,
    capabilities: SimpleNamespace,
    prepared: object,
):
    return _retire_success_ack_evidence_row(
        fixture=fixture,
        capabilities=capabilities,
        prepared=prepared,
        action="fence",
    )


def test_owning_ack_deletes_only_fence_before_evidence_retired(
    tmp_path: Path,
    monkeypatch: pytest.MonkeyPatch,
) -> None:
    """Owning Success-Ack fence retirement is one idempotent row before CAS."""

    import hsconfig.live_start_session as live_start_session

    prepared_context = _prepared_owning_success_ack_cursor(tmp_path, monkeypatch)
    fixture = prepared_context.fixture
    prepared = prepared_context.prepared
    acknowledgement = prepared.attempt_acknowledgement
    assert acknowledgement is not None
    fence_path = Path(str(acknowledgement["retention_fence_path"]))
    journal_path = Path(str(acknowledgement["journal_path"]))
    owner_path = Path(str(acknowledgement["target_owner_journal_path"]))
    target_path = Path(str(acknowledgement["target_path"]))
    admission_path = fixture.runtime_admission.admission_path
    assert (
        prepared.terminal_retirement is not None
        and prepared.terminal_retirement["stage"] == "PREPARED"
        and fence_path.is_file()
    )
    journal_before = journal_path.read_bytes()
    owner_before = owner_path.read_bytes()
    target_before = _filesystem_surface_evidence(target_path)
    admission_before = admission_path.read_bytes()
    admission_identity_before = path_identity(admission_path)
    first_receipt: object

    with _controller_pair_reentry_capabilities(
        fixture, expected_session=prepared
    ) as capabilities:
        session_path = capabilities.session_lease.session_root / "session.json"
        session_before = session_path.read_bytes()
        session_identity_before = path_identity(session_path)
        first = _retire_owning_success_ack_fence(
            fixture=fixture,
            capabilities=capabilities,
            prepared=prepared,
        )
        first_receipt = first.step_receipt
        assert first.action == "fence"
        assert first.object_was_already_absent is False
        assert isinstance(
            first.step_receipt._opaque.successor,
            live_start_session.SuccessAckStepEvidence,
        )
        assert not fence_path.exists()
        assert session_path.read_bytes() == session_before
        assert path_identity(session_path) == session_identity_before
        assert journal_path.read_bytes() == journal_before
        assert owner_path.read_bytes() == owner_before
        assert _filesystem_surface_evidence(target_path) == target_before
        assert admission_path.read_bytes() == admission_before
        assert path_identity(admission_path) == admission_identity_before
        persisted = live_start_session.load_live_start_session_under_lock(
            session_lease=capabilities.session_lease
        )
        assert persisted.canonical_json == prepared.canonical_json
        assert persisted.session_identity == prepared.session_identity
        assert persisted.terminal_retirement is not None
        assert persisted.terminal_retirement["stage"] == "PREPARED"

    with _controller_pair_reentry_capabilities(
        fixture, expected_session=prepared
    ) as capabilities:
        with pytest.raises(live_start_session.SessionCapabilityError):
            live_start_session.advance_terminal_retirement_under_lock(
                session_lease=capabilities.session_lease,
                expected_retirement_session=prepared,
                transition="evidence_retired",
                terminal_authorization=None,
                physical_step_receipt=first_receipt,
            )
        replay = _retire_owning_success_ack_fence(
            fixture=fixture,
            capabilities=capabilities,
            prepared=prepared,
        )
        assert replay.action == "fence"
        assert replay.object_was_already_absent is True
        assert isinstance(
            replay.step_receipt._opaque.successor,
            live_start_session.SuccessAckStepEvidence,
        )
        evidence_retired = live_start_session.advance_terminal_retirement_under_lock(
            session_lease=capabilities.session_lease,
            expected_retirement_session=prepared,
            transition="evidence_retired",
            terminal_authorization=None,
            physical_step_receipt=replay.step_receipt,
        )
        assert evidence_retired.terminal_retirement is not None
        assert evidence_retired.terminal_retirement["stage"] == "EVIDENCE_RETIRED"
        with pytest.raises(live_start_session.SessionCapabilityError):
            live_start_session.advance_terminal_retirement_under_lock(
                session_lease=capabilities.session_lease,
                expected_retirement_session=prepared,
                transition="evidence_retired",
                terminal_authorization=None,
                physical_step_receipt=replay.step_receipt,
            )
        assert journal_path.read_bytes() == journal_before
        assert owner_path.read_bytes() == owner_before
        assert _filesystem_surface_evidence(target_path) == target_before
        assert admission_path.read_bytes() == admission_before
        assert path_identity(admission_path) == admission_identity_before


def test_success_ack_threads_one_receipt_per_deleted_row(
    tmp_path: Path,
    monkeypatch: pytest.MonkeyPatch,
) -> None:
    """A prior-owner Success-Ack retires its journal and fence in separate rows."""

    import hsconfig.live_start_session as live_start_session

    prepared_context = _prepared_nonowning_success_ack_cursor(tmp_path, monkeypatch)
    fixture = prepared_context.fixture
    prepared = prepared_context.prepared
    acknowledgement = prepared.attempt_acknowledgement
    retirement = prepared.terminal_retirement
    assert acknowledgement is not None and retirement is not None
    assert acknowledgement["journal_owns_target"] is False
    assert acknowledgement["acknowledgement_action"] == (
        "delete_nonowning_attempt_and_fence"
    )
    assert retirement["stage"] == "PREPARED"

    fence_path = Path(str(acknowledgement["retention_fence_path"]))
    journal_path = Path(str(acknowledgement["journal_path"]))
    owner_path = Path(str(acknowledgement["target_owner_journal_path"]))
    target_path = Path(str(acknowledgement["target_path"]))
    admission_path = fixture.runtime_admission.admission_path
    assert journal_path != owner_path
    assert fence_path.is_file() and journal_path.is_file() and owner_path.is_file()

    owner_journal_before = (path_identity(owner_path), owner_path.read_bytes())
    target_before = _filesystem_surface_evidence(target_path)
    admission_before = (path_identity(admission_path), admission_path.read_bytes())
    runtime_root = fixture.runtime_admission.runtime_root
    attempt_journal = runtime_installer.read_runtime_transaction_journal(journal_path)
    current_runtime_paths = (
        runtime_root / "CustomConfig" / "deck_config.ini",
        runtime_root / ".hsconfig" / "state.json",
        runtime_installer._receipt_path(runtime_root, attempt_journal.state_key),
    )
    assert all(path.is_file() for path in current_runtime_paths)
    current_runtime_before = {
        path: (path_identity(path), path.read_bytes())
        for path in current_runtime_paths
    }
    immutable_retirement = runtime_installer._plain_json_value(retirement)
    assert isinstance(immutable_retirement, dict)
    immutable_retirement.pop("content_sha256")
    immutable_retirement.pop("stage")

    with _controller_pair_reentry_capabilities(
        fixture, expected_session=prepared
    ) as capabilities:
        session_path = capabilities.session_lease.session_root / "session.json"
        session_before = (path_identity(session_path), session_path.read_bytes())
        journal_step = _retire_success_ack_evidence_row(
            fixture=fixture,
            capabilities=capabilities,
            prepared=prepared,
            action="journal",
        )
        assert journal_step.action == "journal"
        assert journal_step.object_was_already_absent is False
        assert type(journal_step.step_receipt) is (
            live_start_session.TerminalResolutionStepReceipt
        )
        assert isinstance(
            journal_step.step_receipt._opaque.successor,
            live_start_session.SuccessAckStepEvidence,
        )
        assert not journal_path.exists()
        assert fence_path.is_file()
        assert (path_identity(owner_path), owner_path.read_bytes()) == (
            owner_journal_before
        )
        assert _filesystem_surface_evidence(target_path) == target_before
        assert (path_identity(admission_path), admission_path.read_bytes()) == (
            admission_before
        )
        assert {
            path: (path_identity(path), path.read_bytes())
            for path in current_runtime_paths
        } == current_runtime_before
        assert (path_identity(session_path), session_path.read_bytes()) == (
            session_before
        )
        persisted = live_start_session.load_live_start_session_under_lock(
            session_lease=capabilities.session_lease
        )
        assert persisted.canonical_json == prepared.canonical_json
        assert persisted.session_identity == prepared.session_identity
        assert persisted.terminal_retirement is not None
        assert persisted.terminal_retirement["stage"] == "PREPARED"

        ack_journal_retired = (
            live_start_session.advance_terminal_retirement_under_lock(
                session_lease=capabilities.session_lease,
                expected_retirement_session=prepared,
                transition="ack_journal_retired",
                terminal_authorization=None,
                physical_step_receipt=journal_step.step_receipt,
            )
        )

    retired_retirement = ack_journal_retired.terminal_retirement
    assert retired_retirement is not None
    assert retired_retirement["stage"] == "ACK_JOURNAL_RETIRED"
    retired_immutable = runtime_installer._plain_json_value(retired_retirement)
    assert isinstance(retired_immutable, dict)
    retired_immutable.pop("content_sha256")
    retired_immutable.pop("stage")
    assert retired_immutable == immutable_retirement

    with _controller_pair_reentry_capabilities(
        fixture, expected_session=ack_journal_retired
    ) as capabilities:
        session_path = capabilities.session_lease.session_root / "session.json"
        session_before_fence = (
            path_identity(session_path),
            session_path.read_bytes(),
        )
        fence_step = _retire_success_ack_evidence_row(
            fixture=fixture,
            capabilities=capabilities,
            prepared=ack_journal_retired,
            action="fence",
        )
        assert fence_step.action == "fence"
        assert fence_step.object_was_already_absent is False
        assert type(fence_step.step_receipt) is (
            live_start_session.TerminalResolutionStepReceipt
        )
        assert isinstance(
            fence_step.step_receipt._opaque.successor,
            live_start_session.SuccessAckStepEvidence,
        )
        assert fence_step.step_receipt is not journal_step.step_receipt
        assert not journal_path.exists()
        assert not fence_path.exists()
        assert (path_identity(owner_path), owner_path.read_bytes()) == (
            owner_journal_before
        )
        assert _filesystem_surface_evidence(target_path) == target_before
        assert (path_identity(admission_path), admission_path.read_bytes()) == (
            admission_before
        )
        assert {
            path: (path_identity(path), path.read_bytes())
            for path in current_runtime_paths
        } == current_runtime_before
        assert (path_identity(session_path), session_path.read_bytes()) == (
            session_before_fence
        )
        persisted = live_start_session.load_live_start_session_under_lock(
            session_lease=capabilities.session_lease
        )
        assert persisted.canonical_json == ack_journal_retired.canonical_json
        assert persisted.session_identity == ack_journal_retired.session_identity
        assert persisted.terminal_retirement is not None
        assert persisted.terminal_retirement["stage"] == "ACK_JOURNAL_RETIRED"

        evidence_retired = live_start_session.advance_terminal_retirement_under_lock(
            session_lease=capabilities.session_lease,
            expected_retirement_session=ack_journal_retired,
            transition="evidence_retired",
            terminal_authorization=None,
            physical_step_receipt=fence_step.step_receipt,
        )

    final_retirement = evidence_retired.terminal_retirement
    assert final_retirement is not None
    assert final_retirement["stage"] == "EVIDENCE_RETIRED"
    final_immutable = runtime_installer._plain_json_value(final_retirement)
    assert isinstance(final_immutable, dict)
    final_immutable.pop("content_sha256")
    final_immutable.pop("stage")
    assert final_immutable == immutable_retirement
    assert not fence_path.exists() and not journal_path.exists()
    assert (path_identity(owner_path), owner_path.read_bytes()) == owner_journal_before
    assert _filesystem_surface_evidence(target_path) == target_before
    assert (path_identity(admission_path), admission_path.read_bytes()) == admission_before
    assert {
        path: (path_identity(path), path.read_bytes())
        for path in current_runtime_paths
    } == current_runtime_before


def test_nonowning_ack_crash_after_journal_before_fence_resumes_from_ack_journal_retired(
    tmp_path: Path,
    monkeypatch: pytest.MonkeyPatch,
) -> None:
    """A lost non-owning journal receipt cannot skip its durable replay row."""

    import hsconfig.live_start_session as live_start_session

    prepared_context = _prepared_nonowning_success_ack_cursor(tmp_path, monkeypatch)
    fixture = prepared_context.fixture
    prepared = prepared_context.prepared
    acknowledgement = prepared.attempt_acknowledgement
    retirement = prepared.terminal_retirement
    assert acknowledgement is not None and retirement is not None
    assert retirement["stage"] == "PREPARED"
    assert acknowledgement["journal_owns_target"] is False
    assert acknowledgement["acknowledgement_action"] == (
        "delete_nonowning_attempt_and_fence"
    )
    fence_path = Path(str(acknowledgement["retention_fence_path"]))
    journal_path = Path(str(acknowledgement["journal_path"]))
    owner_path = Path(str(acknowledgement["target_owner_journal_path"]))
    target_path = Path(str(acknowledgement["target_path"]))
    admission_path = fixture.runtime_admission.admission_path
    assert journal_path != owner_path
    assert fence_path.is_file() and journal_path.is_file() and owner_path.is_file()

    owner_before = (path_identity(owner_path), owner_path.read_bytes())
    target_before = _filesystem_surface_evidence(target_path)
    admission_before = (path_identity(admission_path), admission_path.read_bytes())
    fence_before = (path_identity(fence_path), fence_path.read_bytes())
    journal_before = (path_identity(journal_path), journal_path.read_bytes())
    owner = runtime_installer.read_runtime_transaction_journal(owner_path)
    runtime_root = fixture.runtime_admission.runtime_root
    current_runtime_paths = (
        runtime_root / "CustomConfig" / "deck_config.ini",
        runtime_root / ".hsconfig" / "state.json",
        runtime_installer._receipt_path(runtime_root, owner.state_key),
    )
    assert all(path.is_file() for path in current_runtime_paths)
    current_runtime_before = {
        path: (path_identity(path), path.read_bytes())
        for path in current_runtime_paths
    }
    immutable_retirement = runtime_installer._plain_json_value(retirement)
    assert isinstance(immutable_retirement, dict)
    immutable_retirement.pop("content_sha256")
    immutable_retirement.pop("stage")

    def assert_surviving_surfaces(
        *, journal_present: bool, fence_present: bool
    ) -> None:
        assert (path_identity(owner_path), owner_path.read_bytes()) == owner_before
        assert _filesystem_surface_evidence(target_path) == target_before
        assert (path_identity(admission_path), admission_path.read_bytes()) == (
            admission_before
        )
        assert {
            path: (path_identity(path), path.read_bytes())
            for path in current_runtime_paths
        } == current_runtime_before
        if journal_present:
            assert (path_identity(journal_path), journal_path.read_bytes()) == (
                journal_before
            )
        else:
            assert not os.path.lexists(journal_path)
        if fence_present:
            assert (path_identity(fence_path), fence_path.read_bytes()) == (
                fence_before
            )
        else:
            assert not os.path.lexists(fence_path)

    first_receipt: object
    with _controller_pair_reentry_capabilities(
        fixture, expected_session=prepared
    ) as capabilities:
        session_path = capabilities.session_lease.session_root / "session.json"
        session_before = (path_identity(session_path), session_path.read_bytes())
        first = _retire_success_ack_evidence_row(
            fixture=fixture,
            capabilities=capabilities,
            prepared=prepared,
            action="journal",
        )
        first_receipt = first.step_receipt
        assert first.action == "journal"
        assert first.object_was_already_absent is False
        assert type(first.step_receipt) is live_start_session.TerminalResolutionStepReceipt
        assert isinstance(
            first.step_receipt._opaque.successor,
            live_start_session.SuccessAckStepEvidence,
        )
        assert_surviving_surfaces(journal_present=False, fence_present=True)
        assert (path_identity(session_path), session_path.read_bytes()) == (
            session_before
        )
        persisted = live_start_session.load_live_start_session_under_lock(
            session_lease=capabilities.session_lease
        )
        assert persisted.canonical_json == prepared.canonical_json
        assert persisted.session_identity == prepared.session_identity
        assert persisted.terminal_retirement is not None
        assert persisted.terminal_retirement["stage"] == "PREPARED"

    with _controller_pair_reentry_capabilities(
        fixture, expected_session=prepared
    ) as capabilities:
        session_path = capabilities.session_lease.session_root / "session.json"
        session_before_replay = (
            path_identity(session_path),
            session_path.read_bytes(),
        )
        with pytest.raises(live_start_session.SessionCapabilityError):
            live_start_session.advance_terminal_retirement_under_lock(
                session_lease=capabilities.session_lease,
                expected_retirement_session=prepared,
                transition="ack_journal_retired",
                terminal_authorization=None,
                physical_step_receipt=first_receipt,
            )
        assert_surviving_surfaces(journal_present=False, fence_present=True)
        assert (path_identity(session_path), session_path.read_bytes()) == (
            session_before_replay
        )
        persisted = live_start_session.load_live_start_session_under_lock(
            session_lease=capabilities.session_lease
        )
        assert persisted.canonical_json == prepared.canonical_json
        assert persisted.session_identity == prepared.session_identity
        assert persisted.terminal_retirement is not None
        assert persisted.terminal_retirement["stage"] == "PREPARED"

        replay = _retire_success_ack_evidence_row(
            fixture=fixture,
            capabilities=capabilities,
            prepared=prepared,
            action="journal",
        )
        assert replay.action == "journal"
        assert replay.object_was_already_absent is True
        assert replay.step_receipt is not first_receipt
        assert isinstance(
            replay.step_receipt._opaque.successor,
            live_start_session.SuccessAckStepEvidence,
        )
        assert_surviving_surfaces(journal_present=False, fence_present=True)
        assert (path_identity(session_path), session_path.read_bytes()) == (
            session_before_replay
        )
        persisted = live_start_session.load_live_start_session_under_lock(
            session_lease=capabilities.session_lease
        )
        assert persisted.canonical_json == prepared.canonical_json
        assert persisted.session_identity == prepared.session_identity
        assert persisted.terminal_retirement is not None
        assert persisted.terminal_retirement["stage"] == "PREPARED"
        ack_journal_retired = live_start_session.advance_terminal_retirement_under_lock(
            session_lease=capabilities.session_lease,
            expected_retirement_session=prepared,
            transition="ack_journal_retired",
            terminal_authorization=None,
            physical_step_receipt=replay.step_receipt,
        )

    retired_retirement = ack_journal_retired.terminal_retirement
    assert retired_retirement is not None
    assert retired_retirement["stage"] == "ACK_JOURNAL_RETIRED"
    retired_immutable = runtime_installer._plain_json_value(retired_retirement)
    assert isinstance(retired_immutable, dict)
    retired_immutable.pop("content_sha256")
    retired_immutable.pop("stage")
    assert retired_immutable == immutable_retirement

    with _controller_pair_reentry_capabilities(
        fixture, expected_session=ack_journal_retired
    ) as capabilities:
        session_path = capabilities.session_lease.session_root / "session.json"
        session_before_fence = (
            path_identity(session_path),
            session_path.read_bytes(),
        )
        fence = _retire_success_ack_evidence_row(
            fixture=fixture,
            capabilities=capabilities,
            prepared=ack_journal_retired,
            action="fence",
        )
        assert fence.action == "fence"
        assert fence.object_was_already_absent is False
        assert isinstance(
            fence.step_receipt._opaque.successor,
            live_start_session.SuccessAckStepEvidence,
        )
        assert_surviving_surfaces(journal_present=False, fence_present=False)
        assert (path_identity(session_path), session_path.read_bytes()) == (
            session_before_fence
        )
        persisted = live_start_session.load_live_start_session_under_lock(
            session_lease=capabilities.session_lease
        )
        assert persisted.canonical_json == ack_journal_retired.canonical_json
        assert persisted.session_identity == ack_journal_retired.session_identity
        assert persisted.terminal_retirement is not None
        assert persisted.terminal_retirement["stage"] == "ACK_JOURNAL_RETIRED"
        evidence_retired = live_start_session.advance_terminal_retirement_under_lock(
            session_lease=capabilities.session_lease,
            expected_retirement_session=ack_journal_retired,
            transition="evidence_retired",
            terminal_authorization=None,
            physical_step_receipt=fence.step_receipt,
        )

    final_retirement = evidence_retired.terminal_retirement
    assert final_retirement is not None
    assert final_retirement["stage"] == "EVIDENCE_RETIRED"
    final_immutable = runtime_installer._plain_json_value(final_retirement)
    assert isinstance(final_immutable, dict)
    final_immutable.pop("content_sha256")
    final_immutable.pop("stage")
    assert final_immutable == immutable_retirement
    assert_surviving_surfaces(journal_present=False, fence_present=False)


def test_fault_between_nonowner_delete_and_attempt_record_delete_is_idempotent(
    tmp_path: Path,
    monkeypatch: pytest.MonkeyPatch,
) -> None:
    """A post-unlink fence fault replays only its ACK_JOURNAL_RETIRED row."""

    import hsconfig.live_start_session as live_start_session

    prepared_context = _prepared_nonowning_success_ack_cursor(tmp_path, monkeypatch)
    fixture = prepared_context.fixture
    prepared = prepared_context.prepared
    acknowledgement = prepared.attempt_acknowledgement
    retirement = prepared.terminal_retirement
    assert acknowledgement is not None and retirement is not None
    fence_path = Path(str(acknowledgement["retention_fence_path"]))
    journal_path = Path(str(acknowledgement["journal_path"]))
    owner_path = Path(str(acknowledgement["target_owner_journal_path"]))
    target_path = Path(str(acknowledgement["target_path"]))
    admission_path = fixture.runtime_admission.admission_path
    assert fence_path.is_file() and journal_path.is_file() and owner_path.is_file()
    assert journal_path != owner_path

    owner_before = (path_identity(owner_path), owner_path.read_bytes())
    target_before = _filesystem_surface_evidence(target_path)
    admission_before = (path_identity(admission_path), admission_path.read_bytes())
    owner = runtime_installer.read_runtime_transaction_journal(owner_path)
    runtime_root = fixture.runtime_admission.runtime_root
    current_runtime_paths = (
        runtime_root / "CustomConfig" / "deck_config.ini",
        runtime_root / ".hsconfig" / "state.json",
        runtime_installer._receipt_path(runtime_root, owner.state_key),
    )
    assert all(path.is_file() for path in current_runtime_paths)
    current_runtime_before = {
        path: (path_identity(path), path.read_bytes())
        for path in current_runtime_paths
    }
    immutable_retirement = runtime_installer._plain_json_value(retirement)
    assert isinstance(immutable_retirement, dict)
    immutable_retirement.pop("content_sha256")
    immutable_retirement.pop("stage")

    def assert_surviving_surfaces(*, fence_present: bool) -> None:
        assert not os.path.lexists(journal_path)
        assert (path_identity(owner_path), owner_path.read_bytes()) == owner_before
        assert _filesystem_surface_evidence(target_path) == target_before
        assert (path_identity(admission_path), admission_path.read_bytes()) == (
            admission_before
        )
        assert {
            path: (path_identity(path), path.read_bytes())
            for path in current_runtime_paths
        } == current_runtime_before
        if fence_present:
            assert fence_path.is_file()
        else:
            assert not os.path.lexists(fence_path)

    with _controller_pair_reentry_capabilities(
        fixture, expected_session=prepared
    ) as capabilities:
        journal_step = _retire_success_ack_evidence_row(
            fixture=fixture,
            capabilities=capabilities,
            prepared=prepared,
            action="journal",
        )
        assert journal_step.object_was_already_absent is False
        ack_journal_retired = live_start_session.advance_terminal_retirement_under_lock(
            session_lease=capabilities.session_lease,
            expected_retirement_session=prepared,
            transition="ack_journal_retired",
            terminal_authorization=None,
            physical_step_receipt=journal_step.step_receipt,
        )

    retired_retirement = ack_journal_retired.terminal_retirement
    assert retired_retirement is not None
    assert retired_retirement["stage"] == "ACK_JOURNAL_RETIRED"
    retired_immutable = runtime_installer._plain_json_value(retired_retirement)
    assert isinstance(retired_immutable, dict)
    retired_immutable.pop("content_sha256")
    retired_immutable.pop("stage")
    assert retired_immutable == immutable_retirement
    assert_surviving_surfaces(fence_present=True)

    real_secure_unlink_verified = runtime_installer.secure_unlink_verified
    with monkeypatch.context() as injected:

        def fail_after_exact_fence_unlink(
            path: Path, *args: object, **kwargs: object
        ) -> None:
            assert path == fence_path
            real_secure_unlink_verified(path, *args, **kwargs)
            raise RuntimeError("injected_success_ack_fence_after_unlink")

        injected.setattr(
            runtime_installer,
            "secure_unlink_verified",
            fail_after_exact_fence_unlink,
        )
        with _controller_pair_reentry_capabilities(
            fixture, expected_session=ack_journal_retired
        ) as capabilities:
            session_path = capabilities.session_lease.session_root / "session.json"
            session_before = (
                path_identity(session_path),
                session_path.read_bytes(),
            )
            with pytest.raises(
                RuntimeError,
                match="^injected_success_ack_fence_after_unlink$",
            ):
                _retire_success_ack_evidence_row(
                    fixture=fixture,
                    capabilities=capabilities,
                    prepared=ack_journal_retired,
                    action="fence",
                )
            assert_surviving_surfaces(fence_present=False)
            assert (path_identity(session_path), session_path.read_bytes()) == (
                session_before
            )
            persisted = live_start_session.load_live_start_session_under_lock(
                session_lease=capabilities.session_lease
            )
            assert persisted.canonical_json == ack_journal_retired.canonical_json
            assert persisted.session_identity == ack_journal_retired.session_identity
            assert persisted.terminal_retirement is not None
            assert persisted.terminal_retirement["stage"] == "ACK_JOURNAL_RETIRED"

    with _controller_pair_reentry_capabilities(
        fixture, expected_session=ack_journal_retired
    ) as capabilities:
        session_path = capabilities.session_lease.session_root / "session.json"
        session_before_replay = (
            path_identity(session_path),
            session_path.read_bytes(),
        )
        replay = _retire_success_ack_evidence_row(
            fixture=fixture,
            capabilities=capabilities,
            prepared=ack_journal_retired,
            action="fence",
        )
        assert replay.action == "fence"
        assert replay.object_was_already_absent is True
        assert isinstance(
            replay.step_receipt._opaque.successor,
            live_start_session.SuccessAckStepEvidence,
        )
        assert_surviving_surfaces(fence_present=False)
        assert (path_identity(session_path), session_path.read_bytes()) == (
            session_before_replay
        )
        persisted = live_start_session.load_live_start_session_under_lock(
            session_lease=capabilities.session_lease
        )
        assert persisted.canonical_json == ack_journal_retired.canonical_json
        assert persisted.session_identity == ack_journal_retired.session_identity
        assert persisted.terminal_retirement is not None
        assert persisted.terminal_retirement["stage"] == "ACK_JOURNAL_RETIRED"
        evidence_retired = live_start_session.advance_terminal_retirement_under_lock(
            session_lease=capabilities.session_lease,
            expected_retirement_session=ack_journal_retired,
            transition="evidence_retired",
            terminal_authorization=None,
            physical_step_receipt=replay.step_receipt,
        )

    final_retirement = evidence_retired.terminal_retirement
    assert final_retirement is not None
    assert final_retirement["stage"] == "EVIDENCE_RETIRED"
    final_immutable = runtime_installer._plain_json_value(final_retirement)
    assert isinstance(final_immutable, dict)
    final_immutable.pop("content_sha256")
    final_immutable.pop("stage")
    assert final_immutable == immutable_retirement
    assert_surviving_surfaces(fence_present=False)


def test_acknowledge_runtime_attempt_retires_only_exact_attempt_evidence(
    tmp_path: Path,
    monkeypatch: pytest.MonkeyPatch,
) -> None:
    """Owning Success-Ack retires only its bound attempt fence, never a peer."""

    import hsconfig.live_start_session as live_start_session

    prepared_context = _prepared_owning_success_ack_cursor(tmp_path, monkeypatch)
    fixture = prepared_context.fixture
    prepared = prepared_context.prepared
    acknowledgement = prepared.attempt_acknowledgement
    assert acknowledgement is not None
    runtime_root = fixture.runtime_admission.runtime_root
    foreign = _seed_task9_protected_target(runtime_root)
    fence_path = Path(str(acknowledgement["retention_fence_path"]))
    journal_path = Path(str(acknowledgement["journal_path"]))
    owner_path = Path(str(acknowledgement["target_owner_journal_path"]))
    target_path = Path(str(acknowledgement["target_path"]))
    admission_path = fixture.runtime_admission.admission_path
    assert fence_path.is_file() and journal_path.is_file() and owner_path.is_file()
    assert target_path.is_dir()
    active_transaction_id = fixture.runtime_admission.apply_attempt_id
    assert active_transaction_id not in {
        foreign.owner.transaction_id,
        foreign.controller.transaction_id,
    }
    assert foreign.owner.transaction_id != foreign.controller.transaction_id
    assert fence_path != foreign.retention_path
    assert journal_path not in {foreign.owner_path, foreign.controller_path}
    assert owner_path not in {foreign.owner_path, foreign.controller_path}
    assert target_path != foreign.target
    assert foreign.owner_path != foreign.controller_path
    assert foreign.retention_path.stem == foreign.controller.transaction_id
    active_fence_before = (path_identity(fence_path), fence_path.read_bytes())
    active_journal_before = (path_identity(journal_path), journal_path.read_bytes())
    active_owner_before = (path_identity(owner_path), owner_path.read_bytes())
    active_target_before = _filesystem_surface_evidence(target_path)
    admission_before = (path_identity(admission_path), admission_path.read_bytes())
    active_journal = runtime_installer.read_runtime_transaction_journal(journal_path)
    current_runtime_paths = (
        runtime_root / "CustomConfig" / "deck_config.ini",
        runtime_root / ".hsconfig" / "state.json",
        runtime_installer._receipt_path(runtime_root, active_journal.state_key),
    )
    assert all(path.is_file() for path in current_runtime_paths)
    current_runtime_before = {
        path: (path_identity(path), path.read_bytes())
        for path in current_runtime_paths
    }
    parent_identities_before = {
        journal_path.parent: path_identity(journal_path.parent),
        fence_path.parent: path_identity(fence_path.parent),
        target_path.parent: path_identity(target_path.parent),
    }
    assert journal_path.parent == foreign.owner_path.parent
    assert journal_path.parent == foreign.controller_path.parent
    assert fence_path.parent == foreign.retention_path.parent
    assert target_path.parent == foreign.target.parent
    foreign_target_before = _filesystem_surface_evidence(foreign.target)
    foreign_before = {
        foreign.card: (path_identity(foreign.card), foreign.card.read_bytes()),
        foreign.owner_path: (
            path_identity(foreign.owner_path),
            foreign.owner_path.read_bytes(),
        ),
        foreign.controller_path: (
            path_identity(foreign.controller_path),
            foreign.controller_path.read_bytes(),
        ),
        foreign.retention_path: (
            path_identity(foreign.retention_path),
            foreign.retention_path.read_bytes(),
        ),
    }
    assert all(path.is_file() for path in foreign_before)

    def assert_preserved_runtime_surfaces(*, fence_present: bool) -> None:
        if fence_present:
            assert (path_identity(fence_path), fence_path.read_bytes()) == (
                active_fence_before
            )
        else:
            assert not os.path.lexists(fence_path)
        assert (path_identity(journal_path), journal_path.read_bytes()) == (
            active_journal_before
        )
        assert (path_identity(owner_path), owner_path.read_bytes()) == (
            active_owner_before
        )
        assert _filesystem_surface_evidence(target_path) == active_target_before
        assert (path_identity(admission_path), admission_path.read_bytes()) == (
            admission_before
        )
        assert {
            path: (path_identity(path), path.read_bytes())
            for path in current_runtime_paths
        } == current_runtime_before
        assert {
            path: path_identity(path) for path in parent_identities_before
        } == parent_identities_before
        assert _filesystem_surface_evidence(foreign.target) == foreign_target_before
        for path, expected in foreign_before.items():
            assert path.is_file()
            observed = (path_identity(path), path.read_bytes())
            assert observed == expected

    with _controller_pair_reentry_capabilities(
        fixture, expected_session=prepared
    ) as capabilities:
        session_path = capabilities.session_lease.session_root / "session.json"
        session_before = (path_identity(session_path), session_path.read_bytes())
        foreign_fence_raw = foreign.retention_path.read_bytes()
        foreign_fence_identity = path_identity(foreign.retention_path)
        with runtime_installer.lease_controller_apply_pair(
            **{
                **_pair_arguments(capabilities),
                "runtime_admission": fixture.runtime_admission,
            }
        ) as pair:
            wrong_row_authorization = (
                live_start_session.authorize_terminal_retirement_under_lock(
                    session_lease=capabilities.session_lease,
                    expected_retirement_session=prepared,
                )
            )
            assert wrong_row_authorization._opaque.action == "retire_ack_fence"
            with pytest.raises(
                ValueError,
                match="^runtime_success_ack_binding_changed$",
            ):
                runtime_installer._retire_success_attempt_evidence_step_from_pair(
                    lease_pair=pair,
                    session_lease=capabilities.session_lease,
                    expected_retirement_session=prepared,
                    terminal_authorization=wrong_row_authorization,
                    transaction_id=active_transaction_id,
                    expected_retention_owner_run_id=fixture.apply_started.run_id,
                    expected_package_root_sha256=(
                        fixture.runtime_admission.package_root_sha256
                    ),
                    expected_retention_fence_path=foreign.retention_path,
                    expected_retention_fence_identity=foreign_fence_identity,
                    expected_retention_fence_sha256=(
                        "sha256:" + hashlib.sha256(foreign_fence_raw).hexdigest()
                    ),
                    expected_journal_path=journal_path,
                    expected_journal_identity=tuple(
                        acknowledgement["journal_identity"]
                    ),
                    expected_journal_sha256=str(acknowledgement["journal_sha256"]),
                    expected_target_owner_journal_path=owner_path,
                    expected_target_owner_journal_identity=tuple(
                        acknowledgement["target_owner_journal_identity"]
                    ),
                    expected_target_owner_journal_sha256=str(
                        acknowledgement["target_owner_journal_sha256"]
                    ),
                    expected_target_path=target_path,
                    expected_target_identity=tuple(
                        acknowledgement["target_identity"]
                    ),
                    expected_runtime_admission_path=admission_path,
                    expected_runtime_admission_parent_identity=(
                        fixture.runtime_admission.admission_parent_identity
                    ),
                    expected_runtime_admission_identity=(
                        fixture.runtime_admission.admission_identity
                    ),
                    expected_runtime_admission_sha256=(
                        fixture.runtime_admission.admission_sha256
                    ),
                    action="fence",
                )
        assert_preserved_runtime_surfaces(fence_present=True)
        assert (path_identity(session_path), session_path.read_bytes()) == session_before
        persisted = live_start_session.load_live_start_session_under_lock(
            session_lease=capabilities.session_lease
        )
        assert persisted.canonical_json == prepared.canonical_json
        assert persisted.session_identity == prepared.session_identity
        assert persisted.terminal_retirement is not None
        assert persisted.terminal_retirement["stage"] == "PREPARED"

    with _controller_pair_reentry_capabilities(
        fixture, expected_session=prepared
    ) as capabilities:
        session_path = capabilities.session_lease.session_root / "session.json"
        session_before = (path_identity(session_path), session_path.read_bytes())
        step = _retire_owning_success_ack_fence(
            fixture=fixture,
            capabilities=capabilities,
            prepared=prepared,
        )
        assert step.action == "fence"
        assert step.object_was_already_absent is False
        assert type(step.step_receipt) is live_start_session.TerminalResolutionStepReceipt
        assert isinstance(
            step.step_receipt._opaque.successor,
            live_start_session.SuccessAckStepEvidence,
        )
        assert not os.path.lexists(fence_path)
        assert_preserved_runtime_surfaces(fence_present=False)
        assert (path_identity(session_path), session_path.read_bytes()) == (
            session_before
        )
        persisted = live_start_session.load_live_start_session_under_lock(
            session_lease=capabilities.session_lease
        )
        assert persisted.canonical_json == prepared.canonical_json
        assert persisted.session_identity == prepared.session_identity
        assert persisted.terminal_retirement is not None
        assert persisted.terminal_retirement["stage"] == "PREPARED"
        evidence_retired = live_start_session.advance_terminal_retirement_under_lock(
            session_lease=capabilities.session_lease,
            expected_retirement_session=prepared,
            transition="evidence_retired",
            terminal_authorization=None,
            physical_step_receipt=step.step_receipt,
        )

    assert evidence_retired.terminal_retirement is not None
    assert evidence_retired.terminal_retirement["stage"] == "EVIDENCE_RETIRED"
    assert not os.path.lexists(fence_path)
    assert_preserved_runtime_surfaces(fence_present=False)


def test_already_current_ack_deletes_nonowner_attempt_but_preserves_existing_owner(
    tmp_path: Path,
    monkeypatch: pytest.MonkeyPatch,
) -> None:
    """An already-current prior-owner acknowledgement retires only its rows."""

    import hsconfig.live_start_session as live_start_session

    prepared_context = _prepared_already_current_success_ack_cursor(
        tmp_path, monkeypatch
    )
    fixture = prepared_context.fixture
    prepared = prepared_context.prepared
    acknowledgement = prepared.attempt_acknowledgement
    intent = prepared.result_intent
    retirement = prepared.terminal_retirement
    assert acknowledgement is not None and intent is not None and retirement is not None
    assert prepared.terminal_status == "ALREADY_LIVE"
    assert intent["terminal_status"] == "ALREADY_LIVE"
    assert intent["raw_apply_status"] == "already_current"
    assert acknowledgement["journal_owns_target"] is False
    assert acknowledgement["acknowledgement_action"] == (
        "delete_nonowning_attempt_and_fence"
    )
    assert retirement["stage"] == "PREPARED"

    fence_path = Path(str(acknowledgement["retention_fence_path"]))
    journal_path = Path(str(acknowledgement["journal_path"]))
    owner_path = Path(str(acknowledgement["target_owner_journal_path"]))
    target_path = Path(str(acknowledgement["target_path"]))
    admission_path = fixture.runtime_admission.admission_path
    assert fence_path.is_file() and journal_path.is_file() and owner_path.is_file()
    assert journal_path != owner_path and target_path.is_dir()
    attempt = runtime_installer.read_runtime_transaction_journal(journal_path)
    owner = runtime_installer.read_runtime_transaction_journal(owner_path)
    assert attempt.owns_target is False
    assert owner.owns_target is True
    assert attempt.transaction_id != owner.transaction_id

    owner_before = (path_identity(owner_path), owner_path.read_bytes())
    target_before = _filesystem_surface_evidence(target_path)
    admission_before = (path_identity(admission_path), admission_path.read_bytes())
    runtime_root = fixture.runtime_admission.runtime_root
    current_runtime_paths = (
        runtime_root / "CustomConfig" / "deck_config.ini",
        runtime_root / ".hsconfig" / "state.json",
        runtime_installer._receipt_path(runtime_root, owner.state_key),
    )
    assert all(path.is_file() for path in current_runtime_paths)
    current_runtime_before = {
        path: (path_identity(path), path.read_bytes())
        for path in current_runtime_paths
    }
    immutable_retirement = runtime_installer._plain_json_value(retirement)
    assert isinstance(immutable_retirement, dict)
    immutable_retirement.pop("content_sha256")
    immutable_retirement.pop("stage")

    def assert_surviving_surfaces(
        *, journal_present: bool, fence_present: bool
    ) -> None:
        assert (path_identity(owner_path), owner_path.read_bytes()) == owner_before
        assert _filesystem_surface_evidence(target_path) == target_before
        assert (path_identity(admission_path), admission_path.read_bytes()) == (
            admission_before
        )
        assert {
            path: (path_identity(path), path.read_bytes())
            for path in current_runtime_paths
        } == current_runtime_before
        assert journal_path.is_file() is journal_present
        assert fence_path.is_file() is fence_present

    with _controller_pair_reentry_capabilities(
        fixture, expected_session=prepared
    ) as capabilities:
        session_path = capabilities.session_lease.session_root / "session.json"
        session_before = (path_identity(session_path), session_path.read_bytes())
        journal_step = _retire_success_ack_evidence_row(
            fixture=fixture,
            capabilities=capabilities,
            prepared=prepared,
            action="journal",
        )
        assert journal_step.action == "journal"
        assert journal_step.object_was_already_absent is False
        assert type(journal_step.step_receipt) is (
            live_start_session.TerminalResolutionStepReceipt
        )
        assert isinstance(
            journal_step.step_receipt._opaque.successor,
            live_start_session.SuccessAckStepEvidence,
        )
        assert_surviving_surfaces(journal_present=False, fence_present=True)
        assert (path_identity(session_path), session_path.read_bytes()) == (
            session_before
        )
        persisted = live_start_session.load_live_start_session_under_lock(
            session_lease=capabilities.session_lease
        )
        assert persisted.canonical_json == prepared.canonical_json
        assert persisted.session_identity == prepared.session_identity
        assert persisted.terminal_status == "ALREADY_LIVE"
        assert persisted.terminal_retirement is not None
        assert persisted.terminal_retirement["stage"] == "PREPARED"
        ack_journal_retired = live_start_session.advance_terminal_retirement_under_lock(
            session_lease=capabilities.session_lease,
            expected_retirement_session=prepared,
            transition="ack_journal_retired",
            terminal_authorization=None,
            physical_step_receipt=journal_step.step_receipt,
        )

    retired_retirement = ack_journal_retired.terminal_retirement
    assert retired_retirement is not None
    assert retired_retirement["stage"] == "ACK_JOURNAL_RETIRED"
    retired_immutable = runtime_installer._plain_json_value(retired_retirement)
    assert isinstance(retired_immutable, dict)
    retired_immutable.pop("content_sha256")
    retired_immutable.pop("stage")
    assert retired_immutable == immutable_retirement
    assert_surviving_surfaces(journal_present=False, fence_present=True)

    with _controller_pair_reentry_capabilities(
        fixture, expected_session=ack_journal_retired
    ) as capabilities:
        session_path = capabilities.session_lease.session_root / "session.json"
        session_before = (path_identity(session_path), session_path.read_bytes())
        fence_step = _retire_success_ack_evidence_row(
            fixture=fixture,
            capabilities=capabilities,
            prepared=ack_journal_retired,
            action="fence",
        )
        assert fence_step.action == "fence"
        assert fence_step.object_was_already_absent is False
        assert type(fence_step.step_receipt) is (
            live_start_session.TerminalResolutionStepReceipt
        )
        assert isinstance(
            fence_step.step_receipt._opaque.successor,
            live_start_session.SuccessAckStepEvidence,
        )
        assert fence_step.step_receipt is not journal_step.step_receipt
        assert_surviving_surfaces(journal_present=False, fence_present=False)
        assert (path_identity(session_path), session_path.read_bytes()) == (
            session_before
        )
        persisted = live_start_session.load_live_start_session_under_lock(
            session_lease=capabilities.session_lease
        )
        assert persisted.canonical_json == ack_journal_retired.canonical_json
        assert persisted.session_identity == ack_journal_retired.session_identity
        assert persisted.terminal_status == "ALREADY_LIVE"
        assert persisted.terminal_retirement is not None
        assert persisted.terminal_retirement["stage"] == "ACK_JOURNAL_RETIRED"
        evidence_retired = live_start_session.advance_terminal_retirement_under_lock(
            session_lease=capabilities.session_lease,
            expected_retirement_session=ack_journal_retired,
            transition="evidence_retired",
            terminal_authorization=None,
            physical_step_receipt=fence_step.step_receipt,
        )

    final_retirement = evidence_retired.terminal_retirement
    assert final_retirement is not None
    assert final_retirement["stage"] == "EVIDENCE_RETIRED"
    final_immutable = runtime_installer._plain_json_value(final_retirement)
    assert isinstance(final_immutable, dict)
    final_immutable.pop("content_sha256")
    final_immutable.pop("stage")
    assert final_immutable == immutable_retirement
    assert evidence_retired.terminal_status == "ALREADY_LIVE"
    assert_surviving_surfaces(journal_present=False, fence_present=False)


def test_new_install_ack_preserves_owner_then_later_identical_install_is_already_current(
    tmp_path: Path,
    monkeypatch: pytest.MonkeyPatch,
) -> None:
    """A released owning install remains the exact prior owner for an identical run."""

    import hsconfig.live_start_session as live_start_session
    from hsconfig.package_io import secure_unlink_verified
    from hsconfig.runtime_live_admission import release_runtime_live_attempt_exact

    first_context = _prepared_owning_success_ack_cursor(
        tmp_path,
        monkeypatch,
        existing_child_precondition=True,
    )
    first_fixture = first_context.fixture
    first_operator = (
        first_fixture.pipeline.request.frozen_compiler_inputs.manifest.operator_bindings.to_value()
    )
    first_output_precondition = first_operator["deck_output_precondition"]
    assert first_output_precondition["state"] == "existing"
    assert tuple(first_output_precondition["identity"]) == (
        first_fixture.runtime_admission.output_root_identity
    )
    prepared = first_context.prepared
    acknowledgement = prepared.attempt_acknowledgement
    assert acknowledgement is not None
    assert first_fixture.runtime_admission.apply_attempt_id == "a" * 32
    fence_path = Path(str(acknowledgement["retention_fence_path"]))
    owner_path = Path(str(acknowledgement["target_owner_journal_path"]))
    target_path = Path(str(acknowledgement["target_path"]))
    runtime_root = first_fixture.runtime_admission.runtime_root
    runtime_root_identity = path_identity(runtime_root)
    admission_path = first_fixture.runtime_admission.admission_path
    first_owner = runtime_installer.read_runtime_transaction_journal(owner_path)
    owner_before = (path_identity(owner_path), owner_path.read_bytes())
    target_before = _filesystem_surface_evidence(target_path)
    current_runtime_paths = (
        runtime_root / "CustomConfig" / "deck_config.ini",
        runtime_root / ".hsconfig" / "state.json",
        runtime_installer._receipt_path(
            runtime_root,
            first_owner.state_key,
        ),
    )
    assert fence_path.is_file() and owner_path.is_file() and target_path.is_dir()
    assert all(path.is_file() for path in current_runtime_paths)
    current_runtime_before = {
        path: (path_identity(path), path.read_bytes())
        for path in current_runtime_paths
    }

    with _controller_pair_reentry_capabilities(
        first_fixture, expected_session=prepared
    ) as capabilities:
        first_step = _retire_owning_success_ack_fence(
            fixture=first_fixture,
            capabilities=capabilities,
            prepared=prepared,
        )
        assert first_step.action == "fence"
        assert first_step.object_was_already_absent is False
        assert not os.path.lexists(fence_path)
        evidence_retired = live_start_session.advance_terminal_retirement_under_lock(
            session_lease=capabilities.session_lease,
            expected_retirement_session=prepared,
            transition="evidence_retired",
            terminal_authorization=None,
            physical_step_receipt=first_step.step_receipt,
        )
        release_transition_authorization = (
            live_start_session.authorize_terminal_retirement_under_lock(
                session_lease=capabilities.session_lease,
                expected_retirement_session=evidence_retired,
            )
        )
        release_authorized = live_start_session.advance_terminal_retirement_under_lock(
            session_lease=capabilities.session_lease,
            expected_retirement_session=evidence_retired,
            transition="admission_release_authorized",
            terminal_authorization=release_transition_authorization,
            physical_step_receipt=None,
        )
        assert release_authorized.terminal_retirement is not None
        assert release_authorized.terminal_retirement["stage"] == (
            "ADMISSION_RELEASE_AUTHORIZED"
        )
        runtime_release_authorization = (
            live_start_session.authorize_terminal_retirement_under_lock(
                session_lease=capabilities.session_lease,
                expected_retirement_session=release_authorized,
            )
        )

        def release_runtime_admission() -> (
            live_start_session.RuntimeAdmissionReleasePostcondition
        ):
            observation = release_runtime_live_attempt_exact(
                expected=first_fixture.runtime_admission
            )
            return live_start_session.RuntimeAdmissionReleasePostcondition(
                admission_path=observation.admission_path,
                admission_parent_identity=observation.admission_parent_identity,
                historical_admission_identity=(
                    observation.historical_admission_identity
                ),
                historical_admission_sha256=(
                    observation.historical_admission_sha256
                ),
                disposition=observation.disposition,
                foreign_successor_identity=observation.foreign_successor_identity,
                foreign_successor_sha256=observation.foreign_successor_sha256,
            )

        released_admission = live_start_session._execute_runtime_admission_release(
            terminal_authorization=runtime_release_authorization,
            action="release_runtime_admission",
            physical_action=release_runtime_admission,
        )
        assert released_admission.disposition == "old_unlinked"
        assert not os.path.lexists(admission_path)

        historical_operation = first_fixture.historical_output_operation
        historical_operation_raw = first_fixture.output_operation_raw
        assert len(historical_operation_raw) == historical_operation.admission_size
        assert historical_operation.admission_path.read_bytes() == (
            historical_operation_raw
        )
        output_release_authorization = (
            live_start_session._authorize_output_operation_admission_release_under_lock(
                session_lease=capabilities.session_lease,
                expected_release_authorized_session=release_authorized,
            )
        )

        def release_output_operation() -> None:
            secure_unlink_verified(
                historical_operation.admission_path,
                expected_identity=historical_operation.admission_identity,
                expected_parent_identity=(
                    historical_operation.admission_parent_identity
                ),
                expected_size=historical_operation.admission_size,
                expected_sha256=hashlib.sha256(
                    historical_operation_raw
                ).hexdigest(),
            )

        assert live_start_session._execute_output_operation_release(
            release_authorization=output_release_authorization,
            physical_action=release_output_operation,
        ) is None
        assert not os.path.lexists(historical_operation.admission_path)

    assert (path_identity(owner_path), owner_path.read_bytes()) == owner_before
    assert _filesystem_surface_evidence(target_path) == target_before
    assert {
        path: (path_identity(path), path.read_bytes())
        for path in current_runtime_paths
    } == current_runtime_before

    second_pipeline = _prepared_pipeline_for_existing_runtime(
        root=tmp_path / "second-run",
        fixture=first_fixture,
    )
    assert second_pipeline.runtime_root == runtime_root
    assert path_identity(second_pipeline.runtime_root) == runtime_root_identity
    second_fixture = _controller_pair_post_handoff_fixture(
        tmp_path / "second-controller",
        monkeypatch,
        prepared_pipeline=second_pipeline,
        expect_existing_runtime=True,
        apply_attempt_id="d" * 32,
    )
    assert second_fixture.runtime_admission.apply_attempt_id != (
        first_fixture.runtime_admission.apply_attempt_id
    )
    assert second_fixture.runtime_admission.apply_attempt_id == "d" * 32
    assert second_fixture.apply_started.run_id == "9" * 32
    assert second_fixture.apply_started.run_id != first_fixture.apply_started.run_id
    assert second_fixture.runtime_admission.runtime_root_identity == (
        first_fixture.runtime_admission.runtime_root_identity
    )
    assert second_fixture.runtime_admission.output_root_identity == (
        first_fixture.runtime_admission.output_root_identity
    )
    assert second_fixture.runtime_admission.package_root_sha256 == (
        first_fixture.runtime_admission.package_root_sha256
    )
    assert second_fixture.runtime_admission.publication_content_root_sha256 == (
        first_fixture.runtime_admission.publication_content_root_sha256
    )
    assert second_fixture.runtime_admission.output_child_binding_sha256 != (
        first_fixture.runtime_admission.output_child_binding_sha256
    )
    assert second_fixture.runtime_admission.output_operation_admission_identity != (
        first_fixture.runtime_admission.output_operation_admission_identity
    )
    assert second_fixture.runtime_admission.publication_revision == (
        first_fixture.runtime_admission.publication_revision
    )
    second = _exercise_prior_owner_route(
        tmp_path / "second-route",
        monkeypatch,
        fixture=second_fixture,
    )
    recovery = second.recovery
    assert second.plan.package_root_sha256 == first_owner.package_root_sha256
    assert second.plan.versioned_config_dir == first_owner.next_config_dir
    assert second.fixture.runtime_admission.runtime_root == runtime_root
    assert recovery["install_route"] == "prior_owner"
    assert recovery["stable_physical_disposition"] == "COMMITTED"
    assert "bind_created_candidate" not in second.actions
    assert "rename_candidate_to_target" not in second.actions
    assert not {
        "prepare_owner_retirement",
        "commit_owner_retirement_prepared",
        "initialize_owner_cleanup_journal",
        "delete_owner_cleanup_entry",
        "advance_owner_cleanup_journal",
        "retire_owner_target_root",
        "commit_owner_retirement_completed",
        "retire_old_owner_journal",
        "observe_owner_retirement_completed",
    }.intersection(second.actions)

    second_journal_path = Path(str(recovery["predecessor_journal_path"]))
    second_fence_path = Path(str(recovery["predecessor_attempt_record_path"]))
    second_owner_path = Path(
        str(recovery["predecessor_target_owner_journal_path"])
    )
    assert second_journal_path.is_file() and second_fence_path.is_file()
    assert second_journal_path != owner_path
    second_attempt = runtime_installer.read_runtime_transaction_journal(
        second_journal_path
    )
    assert second_attempt.transaction_id == "d" * 32
    assert second_attempt.owns_target is False
    second_fence = runtime_installer._runtime_attempt_retention_from_raw(
        second_fence_path.read_bytes(),
        runtime_root=runtime_root,
    )
    assert second_fence.schema_version == 2
    assert second_fence.state == "FINALIZED"
    assert second_fence.apply_attempt_id == "d" * 32
    assert second_fence.journal_path == second_journal_path
    assert second_fence.owns_target is False
    assert second_fence.target_owner_journal_path == owner_path
    assert second_owner_path == owner_path
    assert (path_identity(second_owner_path), second_owner_path.read_bytes()) == (
        owner_before
    )
    assert _filesystem_surface_evidence(target_path) == target_before
    assert {
        path: (path_identity(path), path.read_bytes())
        for path in current_runtime_paths
    } == current_runtime_before

    second_prepared_context = _prepared_success_ack_cursor(
        tmp_path / "second-terminal",
        monkeypatch,
        prior_owner=True,
        already_current=True,
        result=second,
    )
    assert second_prepared_context.fixture is second_fixture
    second_prepared = second_prepared_context.prepared
    second_intent = second_prepared.result_intent
    second_acknowledgement = second_prepared.attempt_acknowledgement
    second_retirement = second_prepared.terminal_retirement
    assert second_intent is not None
    assert second_acknowledgement is not None
    assert second_retirement is not None
    assert second_prepared.terminal_status == "ALREADY_LIVE"
    assert second_intent["terminal_status"] == "ALREADY_LIVE"
    assert second_intent["raw_apply_status"] == "already_current"
    assert second_acknowledgement["journal_owns_target"] is False
    assert second_acknowledgement["acknowledgement_action"] == (
        "delete_nonowning_attempt_and_fence"
    )
    assert Path(str(second_acknowledgement["journal_path"])) == (
        second_journal_path
    )
    assert Path(str(second_acknowledgement["retention_fence_path"])) == (
        second_fence_path
    )
    assert Path(str(second_acknowledgement["target_owner_journal_path"])) == (
        owner_path
    )
    assert second_retirement["stage"] == "PREPARED"
    assert second_journal_path.is_file() and second_fence_path.is_file()
    assert (path_identity(owner_path), owner_path.read_bytes()) == owner_before
    assert _filesystem_surface_evidence(target_path) == target_before
    assert {
        path: (path_identity(path), path.read_bytes())
        for path in current_runtime_paths
    } == current_runtime_before


